import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings, SheetStock, SheetUtilizationStrategy } from '../types';
import { generateId } from '../utils/helpers';
import { calculatePartPhysicalExtents } from './geometry';

// ----------------------------------------------------------------------
// TYPES & HELPERS
// ----------------------------------------------------------------------

interface PackerItem {
    uid: string;
    partId: string;
    width: number;
    height: number;
    offsetX: number; 
    offsetY: number;
    allowRotation: boolean;
    // Pre-calculated for 90deg rotation
    rotatedWidth: number;
    rotatedHeight: number;
    rotatedOffsetX: number;
    rotatedOffsetY: number;
}

interface NeighborRef {
    dim: number; // The length of the edge facing the free rect
}

interface FreeRect {
    x: number;
    y: number;
    w: number;
    h: number;
    // Context about what borders this free space
    neighborLeft?: NeighborRef;   // What part is immediately to the left?
    neighborBottom?: NeighborRef; // What part is immediately below?
}

type SplitStrategy = 'Vertical' | 'Horizontal' | 'ShortAxis' | 'LongAxis';

// ----------------------------------------------------------------------
// ROBUST GUILLOTINE PACKER CLASS
// ----------------------------------------------------------------------

class GuillotinePacker {
    width: number;
    height: number;
    spacingX: number;
    spacingY: number;
    useCommonLine: boolean;
    freeRects: FreeRect[];
    placedItems: { item: PackerItem, x: number, y: number, rotation: number }[];
    strategy: SplitStrategy;

    constructor(
        width: number, 
        height: number, 
        spacingX: number, 
        spacingY: number, 
        strategy: SplitStrategy = 'ShortAxis',
        useCommonLine: boolean = false
    ) {
        this.width = width;
        this.height = height;
        this.spacingX = spacingX;
        this.spacingY = spacingY;
        this.useCommonLine = useCommonLine;
        this.freeRects = [{ x: 0, y: 0, w: width, h: height }];
        this.placedItems = [];
        this.strategy = strategy;
    }

    // Helper to calculate required spacing based on neighbor match
    getDynamicSpacing(itemDim: number, neighbor?: NeighborRef, axisSpacing?: number): number {
        const defaultSpacing = axisSpacing || 0;

        if (this.useCommonLine && neighbor) {
            // Check if dimensions match (with small tolerance for float errors)
            if (Math.abs(itemDim - neighbor.dim) < 0.1) {
                return -5; // Common Line overlap
            }
        }
        return defaultSpacing;
    }

    // Heuristic: Best Area Fit (BAF)
    findPosition(item: PackerItem): { rectIndex: number, rotation: number, score: number, appliedSpacingX: number, appliedSpacingY: number } | null {
        let bestScore = Infinity;
        let bestRectIndex = -1;
        let bestRotation = 0; // 0 or 90
        let bestSpacingX = this.spacingX;
        let bestSpacingY = this.spacingY;

        for (let i = 0; i < this.freeRects.length; i++) {
            const rect = this.freeRects[i];

            // --- Strategy Position Penalty ---
            // Small bias to pick top-left or bottom-left depending on strategy
            let positionPenalty = 0;
            if (this.strategy === 'Vertical') {
                positionPenalty = (rect.x * 10 + rect.y) * 0.0001; 
            } else if (this.strategy === 'Horizontal') {
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            }

            // --- Try 0 degrees ---
            {
                // Determine spacing based on neighbors
                const sX = this.getDynamicSpacing(item.height, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.width, rect.neighborBottom, this.spacingY);

                const requiredW = item.width + (rect.x === 0 ? 0 : sX); // No spacing on sheet edge usually, but here simplified to neighbor check logic handled by packer bounds
                const requiredH = item.height + (rect.y === 0 ? 0 : sY); 

                // For checking fit, we treat the spacing as part of the "consumed" space from the free rect.
                // However, negative spacing means we consume LESS space (effectively starting earlier relative to the gap).
                // But the FreeRect starts at the edge of the previous part + gap.
                // Actually, in this Guillotine model:
                // FreeRect X = PreviousPart X + PreviousPart W.
                // If we want spacing S, placed X should be FreeRect X + S.
                // If S is negative (-5), placed X is FreeRect X - 5.
                // Does the item fit? (Item W) <= (FreeRect W + 5)? Yes.
                // So effective width needed is Item W + S.

                const effectiveUsedW = Math.max(0, item.width + sX);
                const effectiveUsedH = Math.max(0, item.height + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);
                    const fitScore = Math.min(leftoverX, leftoverY); 

                    const totalScore = fitScore + positionPenalty;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 0;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }

            // --- Try 90 degrees ---
            if (item.allowRotation) {
                // Determine spacing based on neighbors (Rotated dimensions!)
                // Item Height becomes Width. Item Width becomes Height.
                // Neighbor Left (Vertical edge) compares to Item Rotated Height (which is its physical Width).
                // Neighbor Bottom (Horizontal edge) compares to Item Rotated Width (which is its physical Height).

                const sX = this.getDynamicSpacing(item.rotatedHeight, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.rotatedWidth, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.rotatedWidth + sX);
                const effectiveUsedH = Math.max(0, item.rotatedHeight + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);
                    const fitScore = Math.min(leftoverX, leftoverY);

                    const totalScore = fitScore + positionPenalty;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 90;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }
        }

        if (bestRectIndex !== -1) {
            return { 
                rectIndex: bestRectIndex, 
                rotation: bestRotation, 
                score: bestScore,
                appliedSpacingX: bestSpacingX,
                appliedSpacingY: bestSpacingY
            };
        }
        return null;
    }

    placeItem(item: PackerItem, rectIndex: number, rotation: number, spacingX: number, spacingY: number) {
        const rect = this.freeRects[rectIndex];
        const w = rotation === 90 ? item.rotatedWidth : item.width;
        const h = rotation === 90 ? item.rotatedHeight : item.height;

        // Calculate placement coordinates
        // If it's the very first item (at 0,0), spacing is usually 0 (handled by sheet margins externally).
        // But internal to packer, if rect.x > 0, we apply spacing.
        const actualSpacingX = rect.x === 0 ? 0 : spacingX;
        const actualSpacingY = rect.y === 0 ? 0 : spacingY;

        const placedX = rect.x + actualSpacingX;
        const placedY = rect.y + actualSpacingY;

        this.placedItems.push({
            item,
            x: placedX,
            y: placedY,
            rotation
        });

        // "Used" dimensions for splitting
        // The free rect is consumed starting from rect.x.
        // We effectively used (placedX - rect.x) + w = spacingX + w.
        const usedW = w + actualSpacingX;
        const usedH = h + actualSpacingY;

        // Determine Split Method
        const freeW = rect.w - usedW;
        const freeH = rect.h - usedH;

        let splitHorizontal = false;

        if (this.strategy === 'Horizontal') {
            splitHorizontal = true;
        } else if (this.strategy === 'Vertical') {
            splitHorizontal = false;
        } else if (this.strategy === 'ShortAxis') {
            splitHorizontal = freeW < freeH;
        } else {
            splitHorizontal = freeW > freeH;
        }

        // Remove the used rectangle
        this.freeRects.splice(rectIndex, 1);

        // GUILLOTINE SPLIT LOGIC
        // We create new FreeRects. We must also propagate Neighbor Info.

        let newRectTop: FreeRect | null = null;
        let newRectRight: FreeRect | null = null;

        // Logic coordinate bases relative to original rect
        const splitX = rect.x + usedW;
        const splitY = rect.y + usedH;

        if (splitHorizontal) {
            // --- HORIZONTAL SPLIT (Cut along X axis) ---
            // Top Rect: Full Width of original.
            // Right Rect: Height limited to item height.

            if (freeH > 0) {
                // Top: Neighbor Bottom is the Item we just placed (partially) + remaining space?
                // For simplicity: The part directly below the start of this rect is the Item.
                // Dimension of the item facing up is 'w' (width).
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: rect.w, 
                    h: freeH,
                    neighborBottom: { dim: w }, // New neighbor below is the item's top edge
                    neighborLeft: rect.neighborLeft // Inherits left neighbor (e.g. sheet edge or prev col)
                };
            }
            if (freeW > 0) {
                // Right: Neighbor Left is the Item we just placed.
                // Dimension of item facing right is 'h' (height).
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: Math.min(usedH, rect.h), // Bounded by item height if split horizontal
                    neighborLeft: { dim: h }, // New neighbor to left is item's right edge
                    neighborBottom: rect.neighborBottom // Inherits bottom neighbor
                };
            }
        } else {
            // --- VERTICAL SPLIT (Cut along Y axis) ---
            // Top Rect: Width limited to item width.
            // Right Rect: Full Height of original.

            if (freeH > 0) {
                // Top: Neighbor Bottom is Item.
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: Math.min(usedW, rect.w), 
                    h: freeH,
                    neighborBottom: { dim: w },
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                // Right: Neighbor Left is Item.
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: rect.h,
                    neighborLeft: { dim: h },
                    neighborBottom: rect.neighborBottom
                };
            }
        }

        if (newRectTop && newRectTop.w > 0 && newRectTop.h > 0) this.freeRects.push(newRectTop);
        if (newRectRight && newRectRight.w > 0 && newRectRight.h > 0) this.freeRects.push(newRectRight);

        // Pruning tiny rectangles
        this.freeRects = this.freeRects.filter(r => r.w >= 5 && r.h >= 5);
    }
}

// ----------------------------------------------------------------------
// GENERATOR
// ----------------------------------------------------------------------

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestResultSheet[]> {

    // 1. Prepare Items
    const rawItems: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const dims0 = calculatePartPhysicalExtents(part, tools);
        const maxY0 = dims0.height - dims0.offsetY; 

        for (let i = 0; i < sp.quantity; i++) {
            rawItems.push({
                uid: generateId(),
                partId: sp.partId,
                width: dims0.width,
                height: dims0.height,
                offsetX: dims0.offsetX,
                offsetY: dims0.offsetY,
                allowRotation: sp.nesting.allow90_270,
                rotatedWidth: dims0.height,
                rotatedHeight: dims0.width,
                rotatedOffsetX: maxY0,
                rotatedOffsetY: dims0.offsetX
            });
        }
    }

    const completedSheets: NestResultSheet[] = [];
    const { 
        sheetMarginTop, sheetMarginBottom, sheetMarginLeft, sheetMarginRight, 
        partSpacingX, partSpacingY, useCommonLine
    } = settings;

    // Helper to calculate packing efficiency
    const calculateEfficiency = (packer: GuillotinePacker, totalArea: number) => {
        const usedArea = packer.placedItems.reduce((sum, p) => {
            const w = p.rotation === 90 ? p.item.rotatedWidth : p.item.width;
            const h = p.rotation === 90 ? p.item.rotatedHeight : p.item.height;
            return sum + (w * h);
        }, 0);
        return usedArea / totalArea;
    };

    let remainingItems = [...rawItems];

    // 2. Packing Loop
    while (remainingItems.length > 0) {

        // Get Active Sheet
        let activeStock: SheetStock | undefined;
        if (settings.activeSheetId) {
            activeStock = settings.availableSheets.find(s => s.id === settings.activeSheetId);
        }
        if (!activeStock && settings.availableSheets.length > 0) activeStock = settings.availableSheets[0];
        if (!activeStock) break; 

        const packW = activeStock.width - sheetMarginLeft - sheetMarginRight;
        const packH = activeStock.height - sheetMarginTop - sheetMarginBottom;

        // --- MULTI-PASS SIMULATION ---
        const strategies: { name: string, packer: GuillotinePacker, packedIndices: Set<number>, score: number }[] = [];

        const configs = [
            { id: 'Vertical', sort: 'height', strategy: 'Vertical' as SplitStrategy },
            { id: 'Horizontal', sort: 'height', strategy: 'Horizontal' as SplitStrategy },
            { id: 'BestFit', sort: 'area', strategy: 'ShortAxis' as SplitStrategy }
        ];

        for (const config of configs) {
            const currentItems = [...remainingItems];
            if (config.sort === 'height') {
                currentItems.sort((a, b) => Math.max(b.width, b.height) - Math.max(a.width, a.height));
            } else {
                currentItems.sort((a, b) => (b.width * b.height) - (a.width * a.height));
            }

            const packer = new GuillotinePacker(packW, packH, partSpacingX, partSpacingY, config.strategy, useCommonLine);
            const packedUids = new Set<string>();

            for (const item of currentItems) {
                const bestPos = packer.findPosition(item);
                if (bestPos) {
                    packer.placeItem(item, bestPos.rectIndex, bestPos.rotation, bestPos.appliedSpacingX, bestPos.appliedSpacingY);
                    packedUids.add(item.uid);
                }
            }

            const efficiency = calculateEfficiency(packer, packW * packH);
            const count = packedUids.size;
            const score = count * 1000 + efficiency * 100;

            const originalIndices = new Set<number>();
            remainingItems.forEach((item, idx) => {
                if (packedUids.has(item.uid)) originalIndices.add(idx);
            });

            strategies.push({ name: config.id, packer, packedIndices: originalIndices, score });
        }

        // --- PICK WINNER ---
        strategies.sort((a, b) => b.score - a.score);
        const winner = strategies[0];

        if (winner.packedIndices.size === 0) {
            console.warn("Item too big for sheet:", remainingItems[0]);
            remainingItems.shift(); 
            continue;
        }

        remainingItems = remainingItems.filter((_, i) => !winner.packedIndices.has(i));

        // Create Result Sheet from Winner
        const packer = winner.packer;

        // Auto-Calc Width Logic
        let finalSheetWidth = activeStock.width;
        let maxPlacedX = 0;
        packer.placedItems.forEach(p => {
            const w = (p.rotation === 90) ? p.item.rotatedWidth : p.item.width;
            if (p.x + w > maxPlacedX) maxPlacedX = p.x + w;
        });

        const isAutoCalc = settings.utilizationStrategy === SheetUtilizationStrategy.AutoCalculation;
        if (isAutoCalc) {
            const requiredPhys = sheetMarginLeft + maxPlacedX + sheetMarginRight;
            finalSheetWidth = Math.ceil(requiredPhys / 100) * 100;
            if (finalSheetWidth > 2560) finalSheetWidth = 2560;
        }

        const usedAreaPx = packer.placedItems.reduce((sum, p) => {
             const w = p.rotation === 90 ? p.item.rotatedWidth : p.item.width;
             const h = p.rotation === 90 ? p.item.rotatedHeight : p.item.height;
             return sum + (w * h);
        }, 0);
        const totalAreaPx = finalSheetWidth * activeStock.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: isAutoCalc ? `Auto ${finalSheetWidth}x${activeStock.height} (${winner.name})` : `Sheet ${completedSheets.length + 1}`,
            stockSheetId: activeStock.id,
            width: finalSheetWidth,
            height: activeStock.height,
            material: activeStock.material,
            thickness: activeStock.thickness,
            placedParts: packer.placedItems.map(p => {
                const ox = (p.rotation === 90) ? p.item.rotatedOffsetX : p.item.offsetX;
                const oy = (p.rotation === 90) ? p.item.rotatedOffsetY : p.item.offsetY;

                return {
                    id: generateId(),
                    partId: p.item.partId,
                    x: p.x + sheetMarginLeft + ox,
                    y: p.y + sheetMarginBottom + oy,
                    rotation: p.rotation
                };
            }),
            usedArea: totalAreaPx > 0 ? (usedAreaPx / totalAreaPx) * 100 : 0,
            scrapPercentage: totalAreaPx > 0 ? 100 - ((usedAreaPx / totalAreaPx) * 100) : 100,
            partCount: packer.placedItems.length,
            quantity: 1
        };

        completedSheets.push(resultSheet);

        await new Promise(resolve => setTimeout(resolve, 5));
        yield [...completedSheets];
    }
}

import React, { forwardRef } from 'react';
import { Tool, StationConfig } from '../../types';
import { ToolSvg } from './ToolDisplay';

interface VisualizerProps {
    viewBox?: string;
    onMouseDown?: React.MouseEventHandler;
    onMouseMove?: React.MouseEventHandler;
    onMouseUp?: React.MouseEventHandler;
    onWheel?: React.WheelEventHandler;
    onMouseLeave?: React.MouseEventHandler;
    className?: string;
    style?: React.CSSProperties;
}

interface TurretVisualizerProps extends VisualizerProps {
    stations: StationConfig[];
    tools: Tool[]; // Tools currently on turret (filtered)
    selectedStationId: number | null;
    onStationClick: (id: number) => void;
    mode: 'setup' | 'control'; // 'setup' shows config types, 'control' focuses on tools
}

export const TurretVisualizer = forwardRef<SVGSVGElement, TurretVisualizerProps>(({ 
    stations, 
    tools, 
    selectedStationId, 
    onStationClick,
    mode,
    viewBox,
    className,
    style,
    ...events
}, ref) => {
    return (
        <svg 
            ref={ref}
            width="100%" 
            height="100%" 
            viewBox={viewBox || "-350 -350 700 700"}
            className={className}
            style={style}
            {...events}
        >
            <defs>
                <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
                    <feDropShadow dx="2" dy="2" stdDeviation="3" floodColor="#000" floodOpacity="0.3" />
                </filter>
            </defs>

            {/* Base Plate */}
            <circle r="320" fill="#2d3748" stroke="#4a5568" strokeWidth="2" />
            <circle r="300" fill="#cbd5e0" stroke="#718096" strokeWidth="5" filter="url(#shadow)" />
            <circle r="200" fill="#e2e8f0" stroke="#a0aec0" strokeWidth="2" />
            <circle r="100" fill="#edf2f7" stroke="#cbd5e0" strokeWidth="1" />

            <text x="0" y="0" textAnchor="middle" dy="5" className="fill-gray-600 text-lg font-bold pointer-events-none select-none">
                Main Turret
            </text>

            {stations.map((s, i) => {
                // Stations typically ordered clockwise or counter-clockwise.
                // Assuming standard layout starting at 90deg (Top) and going CW.
                const step = 360 / stations.length;
                const angleDeg = 90 - (i * step);
                const rad = (angleDeg * Math.PI) / 180;
                const x = Math.cos(rad) * 250;
                const y = Math.sin(rad) * 250;

                const assignedTools = tools.filter(t => t.stationNumber === s.id);
                const hasTools = assignedTools.length > 0;
                const isMT = s.type === 'MT';
                const isSelected = selectedStationId === s.id;

                // Color Logic
                let circleFill = isSelected ? "#f6e05e" : "#fff";
                let circleStroke = isSelected ? "#d69e2e" : "#a0aec0";

                // In Control mode, highlight presence of tools
                if (mode === 'control' && !isSelected) {
                    if (hasTools) circleFill = isMT ? "#e9d8fd" : "#bee3f8"; // Light purple / Light blue
                    else circleFill = "#cbd5e0"; // Grayed out
                }

                return (
                    <g 
                        key={s.id} 
                        transform={`translate(${x}, ${y})`} 
                        onClick={(e) => { e.stopPropagation(); onStationClick(s.id); }} 
                        className="cursor-pointer hover:opacity-90 transition-opacity"
                    >
                        <circle r="28" fill={circleFill} stroke={circleStroke} strokeWidth={isSelected ? 4 : 2} />

                        {/* Tool Preview (Only non-MT single tools) */}
                        <g transform="scale(0.9)">
                            {hasTools && !isMT && <ToolSvg tool={assignedTools[0]} />}
                        </g>

                        {/* Tool Name Label */}
                        {hasTools && !isMT && (
                            <text y="-22" textAnchor="middle" className="text-[8px] fill-blue-900 font-bold select-none pointer-events-none" style={{ textShadow: '0px 0px 2px white' }}>
                                {assignedTools[0].name}
                            </text>
                        )}

                        {/* Station Number Badge */}
                        <g transform="translate(0, -38)">
                            <rect x="-12" y="-10" width="24" height="20" rx="4" fill="#fff" stroke="#718096" strokeWidth="1" />
                            <text y="4" textAnchor="middle" className="text-xs fill-gray-900 font-bold select-none pointer-events-none">{s.id}</text>
                        </g>

                        {/* Bottom Label: Type or Status */}
                        <text y="40" textAnchor="middle" className="text-[10px] fill-gray-700 font-bold select-none bg-white pointer-events-none">
                            {isMT ? "MT" : (mode === 'setup' ? `${s.type} ${s.isAutoIndex ? '(AI)' : ''}` : (hasTools ? s.type : ""))}
                        </text>

                        {/* MT Indicator */}
                        {isMT && (
                            <g>
                                <circle r="15" fill="#805ad5" opacity="0.2" />
                                <text y="5" textAnchor="middle" className="text-[10px] fill-purple-800 font-bold pointer-events-none select-none">MT</text>
                                {hasTools && mode === 'control' && (
                                     <text y="18" textAnchor="middle" className="text-[8px] fill-purple-900 font-bold pointer-events-none select-none">
                                         {assignedTools.length}/24
                                     </text>
                                )}
                            </g>
                        )}
                    </g>
                );
            })}
        </svg>
    );
});

interface MtVisualizerProps extends VisualizerProps {
    tools: Tool[]; // Tools specific to this station
    selectedSlotId: number | null;
    onSlotClick: (id: number) => void;
}

export const MtVisualizer = forwardRef<SVGSVGElement, MtVisualizerProps>(({ 
    tools, 
    selectedSlotId, 
    onSlotClick,
    viewBox,
    className,
    style,
    ...events
}, ref) => {
    // 24 slots geometry
    const mtSlots = Array.from({ length: 24 }, (_, i) => {
        const id = i + 1;
        // Slots 1-12 Outer, 13-24 Inner
        const isInner = id > 12;
        const indexInRing = isInner ? id - 13 : id - 1;

        // Visual Radius (Scaled for viewBox -150 to 150)
        const radius = isInner ? 84 : 120;

        // Angle layout
        let angleDeg = - (indexInRing * 30); 
        if (isInner) angleDeg -= 15;

        return { id, angle: angleDeg, radius, isInner };
    });

    return (
        <svg 
            ref={ref}
            width="100%" 
            height="100%" 
            viewBox={viewBox || "-150 -150 300 300"}
            className={className}
            style={style}
            {...events}
        >
             <defs>
                <radialGradient id="greenTool" cx="30%" cy="30%" r="70%">
                    <stop offset="0%" stopColor="#81e6d9" />
                    <stop offset="100%" stopColor="#2c7a7b" />
                </radialGradient>
             </defs>

             {/* Background Plate */}
             <circle r="145" fill="#f3e8ff" stroke="#805ad5" strokeWidth="4" />
             <text x="0" y="-5" textAnchor="middle" className="fill-purple-900 text-lg font-bold pointer-events-none select-none">Multi-Tool</text>

             {mtSlots.map(slot => {
                 const rad = (slot.angle * Math.PI) / 180;
                 const x = Math.cos(rad) * slot.radius;
                 const y = Math.sin(rad) * slot.radius;

                 const assignedTool = tools.find(t => t.mtIndex === slot.id);
                 const isSelected = selectedSlotId === slot.id;

                 return (
                    <g 
                        key={slot.id} 
                        transform={`translate(${x}, ${y})`} 
                        onClick={(e) => { e.stopPropagation(); onSlotClick(slot.id); }} 
                        className="cursor-pointer"
                    >
                        <circle r="14" fill={assignedTool ? "#4299e1" : "#fff"} stroke={isSelected ? "#ecc94b" : "#6b46c1"} strokeWidth={isSelected ? 3 : 1} />

                        {/* Tool Indicator */}
                        {assignedTool ? (
                             <circle r="8" fill="url(#greenTool)" />
                        ) : null}

                        <text y="4" textAnchor="middle" className="text-[8px] fill-gray-800 font-bold select-none z-10 pointer-events-none" style={assignedTool ? {fill:'white', textShadow:'0 0 2px black'} : {}}>
                            {slot.id}
                        </text>
                        {assignedTool && <title>{assignedTool.name}</title>}
                    </g>
                 )
             })}
        </svg>
    );
});

import React, { useState, useEffect } from 'react';
import { Tool, TurretLayout, StationConfig } from '../types';
import { ToolPreview } from './common/ToolDisplay';
import { SaveIcon, TrashIcon, SettingsIcon, PlusIcon, MinusIcon, MaximizeIcon } from './Icons';
import { generateId } from '../utils/helpers';
import { TurretVisualizer, MtVisualizer } from './common/TurretVisualizer';
import { usePanAndZoom } from '../hooks/usePanAndZoom';

interface TurretSetupViewProps {
    tools: Tool[];
    setTools: React.Dispatch<React.SetStateAction<Tool[]>>;
    layouts: TurretLayout[];
    setLayouts: React.Dispatch<React.SetStateAction<TurretLayout[]>>;
}

const DEFAULT_TURRET_VIEWBOX = { x: -400, y: -400, width: 800, height: 800 };
const DEFAULT_MT_VIEWBOX = { x: -160, y: -160, width: 320, height: 320 };

export const TurretSetupView: React.FC<TurretSetupViewProps> = ({ tools, setTools, layouts, setLayouts }) => {
    const [activeLayoutId, setActiveLayoutId] = useState<string>(layouts[0]?.id || '');
    const [currentStations, setCurrentStations] = useState<StationConfig[]>(layouts[0]?.stations || []);
    const [selectedStationId, setSelectedStationId] = useState<number | null>(null);
    const [isMtView, setIsMtView] = useState(false);
    const [selectedMtSlotId, setSelectedMtSlotId] = useState<number | null>(null);
    const [newLayoutName, setNewLayoutName] = useState('');

    // Pan & Zoom Hook
    const { 
        svgRef, 
        viewBox, 
        setViewBox, 
        isDragging, 
        panZoomHandlers 
    } = usePanAndZoom(DEFAULT_TURRET_VIEWBOX);

    useEffect(() => {
        const layout = layouts.find(l => l.id === activeLayoutId);
        if (layout) {
            setCurrentStations(layout.stations);
        }
    }, [activeLayoutId, layouts]);

    // Reset ViewBox when switching views
    useEffect(() => {
        if (isMtView) {
            setViewBox(DEFAULT_MT_VIEWBOX);
        } else {
            setViewBox(DEFAULT_TURRET_VIEWBOX);
        }
    }, [isMtView, setViewBox]);

    const toolsOnTurret = tools.filter(t => t.stationNumber !== 0 && t.stationNumber !== undefined);
    const availableTools = tools.filter(t => !t.stationNumber);

    const loadLayout = (layoutId: string) => {
        const layout = layouts.find(l => l.id === layoutId);
        if (!layout) return;
        setTools(JSON.parse(JSON.stringify(layout.toolsSnapshot)));
        setCurrentStations(JSON.parse(JSON.stringify(layout.stations)));
        setActiveLayoutId(layoutId);
        setSelectedStationId(null);
        setIsMtView(false);
        setSelectedMtSlotId(null);
    };

    const saveLayout = () => {
        if (!newLayoutName.trim()) return;
        const newLayout: TurretLayout = {
            id: generateId(),
            name: newLayoutName,
            toolsSnapshot: JSON.parse(JSON.stringify(tools)),
            stations: JSON.parse(JSON.stringify(currentStations))
        };
        setLayouts(prev => [...prev, newLayout]);
        setActiveLayoutId(newLayout.id);
        setNewLayoutName('');
    };

    const deleteLayout = (id: string) => {
        if (layouts.length <= 1) {
            alert("Нельзя удалить единственную конфигурацию.");
            return;
        }
        setLayouts(prev => prev.filter(l => l.id !== id));
        if (activeLayoutId === id) {
            loadLayout(layouts[0].id);
        }
    };

    const updateStationConfig = (id: number, updates: Partial<StationConfig>) => {
        setCurrentStations(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, stations: prev.find(lx => lx.id === activeLayoutId)?.stations.map(s => s.id === id ? { ...s, ...updates } : s) || [] } : l));
    };

    const handleStationClick = (stationId: number) => {
        const station = currentStations.find(s => s.id === stationId);
        if (station?.type === 'MT') {
            setIsMtView(true);
            setSelectedMtSlotId(1);
        }
        setSelectedStationId(stationId);
    };

    const checkCompatibility = (tool: Tool, station: StationConfig): boolean => {
        if (station.type === 'MT') {
            return tool.stationType === 'MT';
        }
        return tool.toolSize === station.type;
    };

    const handleMountTool = (tool: Tool, mtIndex?: number) => {
        if (!selectedStationId) return;

        const station = currentStations.find(s => s.id === selectedStationId);
        if (!station) return;

        if (!checkCompatibility(tool, station)) {
            alert(`Ошибка: Инструмент размера '${tool.toolSize}' нельзя установить в станцию типа '${station.type}'`);
            return;
        }

        const updatedTools = tools.map(t => {
            if (t.stationNumber === selectedStationId) {
                if (isMtView) {
                    if (t.mtIndex === mtIndex) return { ...t, stationNumber: 0, mtIndex: 0 };
                } else {
                    return { ...t, stationNumber: 0, mtIndex: 0 };
                }
            }
            if (t.id === tool.id) {
                return { ...t, stationNumber: selectedStationId, mtIndex: mtIndex || 0 };
            }
            return t;
        });
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    const handleUnmountTool = (toolId: string) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, stationNumber: 0, mtIndex: 0 } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    const updateToolRotation = (toolId: string, rotation: number) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, defaultRotation: rotation } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    // Zoom Controls
    const handleZoomIn = () => setViewBox(prev => ({ ...prev, x: prev.x + prev.width * 0.1, y: prev.y + prev.height * 0.1, width: prev.width * 0.8, height: prev.height * 0.8 }));
    const handleZoomOut = () => setViewBox(prev => ({ ...prev, x: prev.x - prev.width * 0.1, y: prev.y - prev.height * 0.1, width: prev.width * 1.2, height: prev.height * 1.2 }));
    const handleFit = () => setViewBox(isMtView ? DEFAULT_MT_VIEWBOX : DEFAULT_TURRET_VIEWBOX);

    const selectedStation = currentStations.find(s => s.id === selectedStationId);

    const activeTool = isMtView 
        ? toolsOnTurret.find(t => t.stationNumber === selectedStationId && t.mtIndex === selectedMtSlotId)
        : (selectedStation ? toolsOnTurret.find(t => t.stationNumber === selectedStation.id && !t.mtIndex) : null);

    // Helpers for Visualizers
    const mtTools = isMtView ? toolsOnTurret.filter(t => t.stationNumber === selectedStationId) : [];

    return (
        <div className="flex h-full bg-gray-100 text-gray-900 font-sans">
            <div className="flex-1 relative bg-gray-300 shadow-inner overflow-hidden flex items-center justify-center">

                 {/* Visualizer Container */}
                 <div className="w-full h-full relative cursor-grab active:cursor-grabbing">
                     {isMtView ? (
                        <MtVisualizer 
                            ref={svgRef}
                            tools={mtTools}
                            selectedSlotId={selectedMtSlotId}
                            onSlotClick={setSelectedMtSlotId}
                            viewBox={`${viewBox.x} ${viewBox.y} ${viewBox.width} ${viewBox.height}`}
                            {...panZoomHandlers}
                            className={isDragging ? 'cursor-grabbing' : 'cursor-grab'}
                        />
                     ) : (
                        <TurretVisualizer 
                            ref={svgRef}
                            stations={currentStations}
                            tools={toolsOnTurret}
                            selectedStationId={selectedStationId}
                            onStationClick={handleStationClick}
                            mode="setup"
                            viewBox={`${viewBox.x} ${viewBox.y} ${viewBox.width} ${viewBox.height}`}
                            {...panZoomHandlers}
                            className={isDragging ? 'cursor-grabbing' : 'cursor-grab'}
                        />
                     )}
                 </div>

                 {/* Back Button (MT Mode) */}
                 {isMtView && (
                    <div className="absolute top-4 left-4 z-10">
                        <button onClick={() => setIsMtView(false)} className="bg-gray-600 hover:bg-gray-500 text-white px-3 py-1 rounded shadow text-sm transition-colors">
                            &larr; Назад
                        </button>
                    </div>
                 )}

                 {/* Zoom Controls */}
                 <div className="absolute bottom-4 right-4 flex flex-col space-y-2 bg-gray-800/80 p-2 rounded shadow-lg backdrop-blur-sm border border-gray-600 z-10">
                     <button onClick={handleZoomIn} className="p-2 hover:bg-gray-600 rounded text-white" title="Увеличить"><PlusIcon className="w-5 h-5" /></button>
                     <button onClick={handleZoomOut} className="p-2 hover:bg-gray-600 rounded text-white" title="Уменьшить"><MinusIcon className="w-5 h-5" /></button>
                     <button onClick={handleFit} className="p-2 hover:bg-gray-600 rounded text-white" title="По размеру"><MaximizeIcon className="w-5 h-5" /></button>
                 </div>
            </div>

            <div className="w-96 bg-gray-800 text-gray-100 flex flex-col border-l border-gray-700 shadow-xl z-10">
                <div className="p-4 border-b border-gray-700 bg-gray-900">
                    <h2 className="text-lg font-bold text-blue-400 mb-2 flex items-center"><SettingsIcon className="w-5 h-5 mr-2"/> Настройка Револьвера</h2>
                    <div className="space-y-2">
                        <div>
                             <label className="text-xs text-gray-400 block mb-1">Текущая конфигурация</label>
                             <div className="flex space-x-2">
                                <select 
                                    value={activeLayoutId} 
                                    onChange={(e) => loadLayout(e.target.value)} 
                                    className="flex-1 bg-gray-700 text-white border border-gray-600 rounded px-2 py-1 text-sm"
                                >
                                    {layouts.map(l => <option key={l.id} value={l.id}>{l.name}</option>)}
                                </select>
                                <button onClick={() => deleteLayout(activeLayoutId)} className="bg-red-800 hover:bg-red-700 p-1 rounded text-white"><TrashIcon className="w-4 h-4"/></button>
                             </div>
                        </div>
                        <div className="flex space-x-2 pt-2 border-t border-gray-700">
                             <input 
                                type="text" 
                                placeholder="Новое имя..." 
                                value={newLayoutName}
                                onChange={e => setNewLayoutName(e.target.value)}
                                className="flex-1 bg-gray-700 text-white px-2 py-1 rounded border border-gray-600 text-sm"
                            />
                            <button onClick={saveLayout} className="bg-green-600 hover:bg-green-500 p-1 rounded text-white"><SaveIcon className="w-4 h-4"/></button>
                        </div>
                    </div>
                </div>

                <div className="p-4 border-b border-gray-700 bg-gray-800">
                    <h3 className="font-bold text-gray-300 mb-2">
                        {isMtView 
                            ? `MT Станция ${selectedStationId} - Слот ${selectedMtSlotId || 'не выбран'}` 
                            : (selectedStationId ? `Станция ${selectedStationId}` : 'Выберите станцию')}
                    </h3>

                    {(selectedStation && !isMtView) || (isMtView && selectedMtSlotId) ? (
                        <div className="space-y-3">
                            {!isMtView && (
                                <div className="flex space-x-4">
                                    <div className="flex-1">
                                        <label className="text-xs text-gray-400 block mb-1">Тип гнезда</label>
                                        <select 
                                            value={selectedStation?.type}
                                            onChange={(e) => selectedStation && updateStationConfig(selectedStation.id, { type: e.target.value })}
                                            className="w-full bg-gray-700 border border-gray-600 rounded px-2 py-1 text-sm"
                                        >
                                            {['A', 'B', 'C', 'D', 'MT'].map(t => <option key={t} value={t}>{t}</option>)}
                                        </select>
                                    </div>
                                    <div className="flex items-end pb-2">
                                        <label className="flex items-center space-x-2 cursor-pointer">
                                            <input 
                                                type="checkbox" 
                                                checked={selectedStation?.isAutoIndex} 
                                                onChange={(e) => selectedStation && updateStationConfig(selectedStation.id, { isAutoIndex: e.target.checked })}
                                                className="form-checkbox h-4 w-4 text-blue-600 bg-gray-700 border-gray-500" 
                                            />
                                            <span className="text-sm">Auto Index</span>
                                        </label>
                                    </div>
                                </div>
                            )}

                            {activeTool && (
                                <div className="bg-gray-700 p-3 rounded mt-2 border border-gray-600">
                                    <div className="flex items-center space-x-3 mb-3">
                                        <div className="w-10 h-10 bg-white rounded flex-shrink-0 overflow-hidden"><ToolPreview tool={activeTool} /></div>
                                        <div className="overflow-hidden">
                                            <div className="font-bold text-sm text-white truncate" title={activeTool.name}>{activeTool.name}</div>
                                            <div className="text-xs text-gray-400">{activeTool.width}x{activeTool.height}</div>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-2 mb-3">
                                        <div>
                                            <label className="block text-[10px] text-gray-400 mb-1">Положение (град.)</label>
                                            <select 
                                                value={activeTool.defaultRotation || 0} 
                                                onChange={(e) => updateToolRotation(activeTool.id, parseFloat(e.target.value))}
                                                className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs"
                                            >
                                                {[0, 45, 90, 135, 180, 225, 270, 315].map(angle => (
                                                    <option key={angle} value={angle}>{angle}°</option>
                                                ))}
                                            </select>
                                        </div>
                                        <div>
                                            <label className="block text-[10px] text-gray-400 mb-1">Зазор матрицы</label>
                                            <div className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs text-gray-300">
                                                {activeTool.dies?.[0]?.clearance || '0.0'} мм
                                            </div>
                                        </div>
                                    </div>

                                    <button onClick={() => handleUnmountTool(activeTool.id)} className="w-full bg-red-800 hover:bg-red-700 text-white text-xs py-2 rounded flex items-center justify-center transition-colors">
                                        <TrashIcon className="w-4 h-4 mr-2" /> Снять инструмент
                                    </button>
                                </div>
                            )}

                             {!activeTool && (
                                 <div className="bg-gray-700/50 border border-dashed border-gray-600 rounded p-4 text-center">
                                     <p className="text-xs text-gray-500">Инструмент не установлен</p>
                                     {isMtView && !selectedMtSlotId && <p className="text-[10px] text-gray-400 mt-1">Выберите слот на схеме для установки</p>}
                                 </div>
                             )}

                            {selectedStation?.type === 'MT' && !isMtView && (
                                <button onClick={() => { setIsMtView(true); setSelectedMtSlotId(1); }} className="w-full bg-purple-700 hover:bg-purple-600 text-white py-1 rounded text-sm mt-2">
                                    Открыть Multi-Tool
                                </button>
                            )}
                        </div>
                    ) : (
                        <p className="text-xs text-gray-500 italic">
                            {isMtView ? "Выберите слот мультитула для настройки" : "Нажмите на станцию слева для редактирования"}
                        </p>
                    )}
                </div>

                <div className="flex-1 overflow-hidden flex flex-col">
                    <div className="p-2 bg-gray-900 border-b border-gray-700">
                        <h4 className="text-xs font-bold text-gray-400 uppercase">Библиотека</h4>
                    </div>
                    <div className="flex-1 overflow-y-auto p-2 space-y-2">
                         {availableTools.map(tool => {
                             const displaySize = (tool.stationType === 'MT' || tool.name.startsWith('MT')) ? 'MT' : tool.toolSize;
                             const stationType = selectedStation?.type;
                             let isCompatible = false;
                             if (selectedStation) {
                                 if (isMtView) isCompatible = tool.stationType === 'MT'; 
                                 else if (stationType === 'MT') isCompatible = false; 
                                 else isCompatible = tool.toolSize === stationType;
                             }

                             const canMount = isCompatible && ((!isMtView && selectedStationId) || (isMtView && selectedMtSlotId));

                             return (
                                <div key={tool.id} className={`bg-gray-700 p-2 rounded flex flex-col group border border-transparent ${isCompatible ? 'hover:border-blue-400' : 'opacity-50'}`}>
                                    <div className="flex items-center space-x-2">
                                        <div className="w-8 h-8 bg-white rounded flex-shrink-0"><ToolPreview tool={tool} /></div>
                                        <div className="overflow-hidden flex-1">
                                            <div className="font-bold text-sm text-white truncate">{tool.name}</div>
                                            <div className="flex justify-between text-xs text-gray-400">
                                                <span>{tool.shape} {tool.width}x{tool.height}</span>
                                                <span className={`font-bold ${displaySize === 'MT' ? 'text-purple-400' : 'text-yellow-400'}`}>{displaySize}</span>
                                            </div>
                                        </div>
                                    </div>

                                    {canMount && (
                                        <div className="mt-2">
                                            <button 
                                                onClick={() => handleMountTool(tool, isMtView && selectedMtSlotId ? selectedMtSlotId : 0)}
                                                className={`w-full text-white text-xs py-1 rounded ${isMtView ? 'bg-purple-600 hover:bg-purple-500' : 'bg-blue-600 hover:bg-blue-500'}`}
                                            >
                                                {isMtView ? `В слот ${selectedMtSlotId}` : "Установить"}
                                            </button>
                                        </div>
                                    )}
                                </div>
                             );
                         })}
                         {availableTools.length === 0 && <div className="text-center text-gray-500 text-sm mt-4">Все инструменты установлены</div>}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React from 'react';
import { Tool, StationConfig } from '../../types';
import { ToolSvg } from './ToolDisplay';

interface TurretVisualizerProps {
    stations: StationConfig[];
    tools: Tool[]; // Tools currently on turret (filtered)
    selectedStationId: number | null;
    onStationClick: (id: number) => void;
    mode: 'setup' | 'control'; // 'setup' shows config types, 'control' focuses on tools
}

export const TurretVisualizer: React.FC<TurretVisualizerProps> = ({ 
    stations, 
    tools, 
    selectedStationId, 
    onStationClick,
    mode 
}) => {
    return (
        <svg 
            width="100%" 
            height="100%" 
            viewBox="-350 -350 700 700"
        >
            <defs>
                <filter id="shadow" x="-20%" y="-20%" width="140%" height="140%">
                    <feDropShadow dx="2" dy="2" stdDeviation="3" floodColor="#000" floodOpacity="0.3" />
                </filter>
            </defs>

            {/* Base Plate */}
            <circle r="320" fill="#2d3748" stroke="#4a5568" strokeWidth="2" />
            <circle r="300" fill="#cbd5e0" stroke="#718096" strokeWidth="5" filter="url(#shadow)" />
            <circle r="200" fill="#e2e8f0" stroke="#a0aec0" strokeWidth="2" />
            <circle r="100" fill="#edf2f7" stroke="#cbd5e0" strokeWidth="1" />

            <text x="0" y="0" textAnchor="middle" dy="5" className="fill-gray-600 text-lg font-bold pointer-events-none select-none">
                Main Turret
            </text>

            {stations.map((s, i) => {
                // Stations typically ordered clockwise or counter-clockwise.
                // Assuming standard layout starting at 90deg (Top) and going CW.
                const step = 360 / stations.length;
                const angleDeg = 90 - (i * step);
                const rad = (angleDeg * Math.PI) / 180;
                const x = Math.cos(rad) * 250;
                const y = Math.sin(rad) * 250;

                const assignedTools = tools.filter(t => t.stationNumber === s.id);
                const hasTools = assignedTools.length > 0;
                const isMT = s.type === 'MT';
                const isSelected = selectedStationId === s.id;

                // Color Logic
                let circleFill = isSelected ? "#f6e05e" : "#fff";
                let circleStroke = isSelected ? "#d69e2e" : "#a0aec0";

                // In Control mode, highlight presence of tools
                if (mode === 'control' && !isSelected) {
                    if (hasTools) circleFill = isMT ? "#e9d8fd" : "#bee3f8"; // Light purple / Light blue
                    else circleFill = "#cbd5e0"; // Grayed out
                }

                return (
                    <g 
                        key={s.id} 
                        transform={`translate(${x}, ${y})`} 
                        onClick={(e) => { e.stopPropagation(); onStationClick(s.id); }} 
                        className="cursor-pointer hover:opacity-90 transition-opacity"
                    >
                        <circle r="28" fill={circleFill} stroke={circleStroke} strokeWidth={isSelected ? 4 : 2} />

                        {/* Tool Preview (Only non-MT single tools) */}
                        <g transform="scale(0.9)">
                            {hasTools && !isMT && <ToolSvg tool={assignedTools[0]} />}
                        </g>

                        {/* Tool Name Label */}
                        {hasTools && !isMT && (
                            <text y="-22" textAnchor="middle" className="text-[8px] fill-blue-900 font-bold select-none pointer-events-none" style={{ textShadow: '0px 0px 2px white' }}>
                                {assignedTools[0].name}
                            </text>
                        )}

                        {/* Station Number Badge */}
                        <g transform="translate(0, -38)">
                            <rect x="-12" y="-10" width="24" height="20" rx="4" fill="#fff" stroke="#718096" strokeWidth="1" />
                            <text y="4" textAnchor="middle" className="text-xs fill-gray-900 font-bold select-none pointer-events-none">{s.id}</text>
                        </g>

                        {/* Bottom Label: Type or Status */}
                        <text y="40" textAnchor="middle" className="text-[10px] fill-gray-700 font-bold select-none bg-white pointer-events-none">
                            {isMT ? "MT" : (mode === 'setup' ? `${s.type} ${s.isAutoIndex ? '(AI)' : ''}` : (hasTools ? s.type : ""))}
                        </text>

                        {/* MT Indicator */}
                        {isMT && (
                            <g>
                                <circle r="15" fill="#805ad5" opacity="0.2" />
                                <text y="5" textAnchor="middle" className="text-[10px] fill-purple-800 font-bold pointer-events-none select-none">MT</text>
                                {hasTools && mode === 'control' && (
                                     <text y="18" textAnchor="middle" className="text-[8px] fill-purple-900 font-bold pointer-events-none select-none">
                                         {assignedTools.length}/24
                                     </text>
                                )}
                            </g>
                        )}
                    </g>
                );
            })}
        </svg>
    );
};

interface MtVisualizerProps {
    tools: Tool[]; // Tools specific to this station
    selectedSlotId: number | null;
    onSlotClick: (id: number) => void;
}

export const MtVisualizer: React.FC<MtVisualizerProps> = ({ 
    tools, 
    selectedSlotId, 
    onSlotClick
}) => {
    // 24 slots geometry
    const mtSlots = Array.from({ length: 24 }, (_, i) => {
        const id = i + 1;
        // Slots 1-12 Outer, 13-24 Inner
        const isInner = id > 12;
        const indexInRing = isInner ? id - 13 : id - 1;

        // Visual Radius (Scaled for viewBox -150 to 150)
        const radius = isInner ? 84 : 120;

        // Angle layout
        let angleDeg = - (indexInRing * 30); 
        if (isInner) angleDeg -= 15;

        return { id, angle: angleDeg, radius, isInner };
    });

    return (
        <svg 
            width="100%" 
            height="100%" 
            viewBox="-150 -150 300 300"
        >
             <defs>
                <radialGradient id="greenTool" cx="30%" cy="30%" r="70%">
                    <stop offset="0%" stopColor="#81e6d9" />
                    <stop offset="100%" stopColor="#2c7a7b" />
                </radialGradient>
             </defs>

             {/* Background Plate */}
             <circle r="145" fill="#f3e8ff" stroke="#805ad5" strokeWidth="4" />
             <text x="0" y="-5" textAnchor="middle" className="fill-purple-900 text-lg font-bold pointer-events-none select-none">Multi-Tool</text>

             {mtSlots.map(slot => {
                 const rad = (slot.angle * Math.PI) / 180;
                 const x = Math.cos(rad) * slot.radius;
                 const y = Math.sin(rad) * slot.radius;

                 const assignedTool = tools.find(t => t.mtIndex === slot.id);
                 const isSelected = selectedSlotId === slot.id;

                 return (
                    <g 
                        key={slot.id} 
                        transform={`translate(${x}, ${y})`} 
                        onClick={(e) => { e.stopPropagation(); onSlotClick(slot.id); }} 
                        className="cursor-pointer"
                    >
                        <circle r="14" fill={assignedTool ? "#4299e1" : "#fff"} stroke={isSelected ? "#ecc94b" : "#6b46c1"} strokeWidth={isSelected ? 3 : 1} />

                        {/* Tool Indicator */}
                        {assignedTool ? (
                             <circle r="8" fill="url(#greenTool)" />
                        ) : null}

                        <text y="4" textAnchor="middle" className="text-[8px] fill-gray-800 font-bold select-none z-10 pointer-events-none" style={assignedTool ? {fill:'white', textShadow:'0 0 2px black'} : {}}>
                            {slot.id}
                        </text>
                        {assignedTool && <title>{assignedTool.name}</title>}
                    </g>
                 )
             })}
        </svg>
    );
};

import React, { useState, useEffect } from 'react';
import { Tool, TurretLayout, StationConfig } from '../types';
import { ToolPreview } from './common/ToolDisplay';
import { SaveIcon, TrashIcon, SettingsIcon } from './Icons';
import { generateId } from '../utils/helpers';
import { TurretVisualizer, MtVisualizer } from './common/TurretVisualizer';

interface TurretSetupViewProps {
    tools: Tool[];
    setTools: React.Dispatch<React.SetStateAction<Tool[]>>;
    layouts: TurretLayout[];
    setLayouts: React.Dispatch<React.SetStateAction<TurretLayout[]>>;
}

export const TurretSetupView: React.FC<TurretSetupViewProps> = ({ tools, setTools, layouts, setLayouts }) => {
    const [activeLayoutId, setActiveLayoutId] = useState<string>(layouts[0]?.id || '');
    const [currentStations, setCurrentStations] = useState<StationConfig[]>(layouts[0]?.stations || []);
    const [selectedStationId, setSelectedStationId] = useState<number | null>(null);
    const [isMtView, setIsMtView] = useState(false);
    const [selectedMtSlotId, setSelectedMtSlotId] = useState<number | null>(null);
    const [newLayoutName, setNewLayoutName] = useState('');

    useEffect(() => {
        const layout = layouts.find(l => l.id === activeLayoutId);
        if (layout) {
            setCurrentStations(layout.stations);
        }
    }, [activeLayoutId, layouts]);

    const toolsOnTurret = tools.filter(t => t.stationNumber !== 0 && t.stationNumber !== undefined);
    const availableTools = tools.filter(t => !t.stationNumber);

    const loadLayout = (layoutId: string) => {
        const layout = layouts.find(l => l.id === layoutId);
        if (!layout) return;
        setTools(JSON.parse(JSON.stringify(layout.toolsSnapshot)));
        setCurrentStations(JSON.parse(JSON.stringify(layout.stations)));
        setActiveLayoutId(layoutId);
        setSelectedStationId(null);
        setIsMtView(false);
        setSelectedMtSlotId(null);
    };

    const saveLayout = () => {
        if (!newLayoutName.trim()) return;
        const newLayout: TurretLayout = {
            id: generateId(),
            name: newLayoutName,
            toolsSnapshot: JSON.parse(JSON.stringify(tools)),
            stations: JSON.parse(JSON.stringify(currentStations))
        };
        setLayouts(prev => [...prev, newLayout]);
        setActiveLayoutId(newLayout.id);
        setNewLayoutName('');
    };

    const deleteLayout = (id: string) => {
        if (layouts.length <= 1) {
            alert("Нельзя удалить единственную конфигурацию.");
            return;
        }
        setLayouts(prev => prev.filter(l => l.id !== id));
        if (activeLayoutId === id) {
            loadLayout(layouts[0].id);
        }
    };

    const updateStationConfig = (id: number, updates: Partial<StationConfig>) => {
        setCurrentStations(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, stations: prev.find(lx => lx.id === activeLayoutId)?.stations.map(s => s.id === id ? { ...s, ...updates } : s) || [] } : l));
    };

    const handleStationClick = (stationId: number) => {
        const station = currentStations.find(s => s.id === stationId);
        if (station?.type === 'MT') {
            setIsMtView(true);
            setSelectedMtSlotId(1);
        }
        setSelectedStationId(stationId);
    };

    const checkCompatibility = (tool: Tool, station: StationConfig): boolean => {
        if (station.type === 'MT') {
            return tool.stationType === 'MT';
        }
        return tool.toolSize === station.type;
    };

    const handleMountTool = (tool: Tool, mtIndex?: number) => {
        if (!selectedStationId) return;

        const station = currentStations.find(s => s.id === selectedStationId);
        if (!station) return;

        if (!checkCompatibility(tool, station)) {
            alert(`Ошибка: Инструмент размера '${tool.toolSize}' нельзя установить в станцию типа '${station.type}'`);
            return;
        }

        const updatedTools = tools.map(t => {
            if (t.stationNumber === selectedStationId) {
                if (isMtView) {
                    if (t.mtIndex === mtIndex) return { ...t, stationNumber: 0, mtIndex: 0 };
                } else {
                    return { ...t, stationNumber: 0, mtIndex: 0 };
                }
            }
            if (t.id === tool.id) {
                return { ...t, stationNumber: selectedStationId, mtIndex: mtIndex || 0 };
            }
            return t;
        });
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    const handleUnmountTool = (toolId: string) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, stationNumber: 0, mtIndex: 0 } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    const updateToolRotation = (toolId: string, rotation: number) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, defaultRotation: rotation } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    const selectedStation = currentStations.find(s => s.id === selectedStationId);

    const activeTool = isMtView 
        ? toolsOnTurret.find(t => t.stationNumber === selectedStationId && t.mtIndex === selectedMtSlotId)
        : (selectedStation ? toolsOnTurret.find(t => t.stationNumber === selectedStation.id && !t.mtIndex) : null);

    // Helpers for Visualizers
    const mtTools = isMtView ? toolsOnTurret.filter(t => t.stationNumber === selectedStationId) : [];

    return (
        <div className="flex h-full bg-gray-100 text-gray-900 font-sans">
            <div className="flex-1 relative bg-gray-300 shadow-inner overflow-hidden flex items-center justify-center">

                 {/* Visualizer Container */}
                 {isMtView ? (
                    <div className="w-full h-full flex flex-col relative p-8">
                        <button onClick={() => setIsMtView(false)} className="absolute top-4 left-4 bg-gray-600 hover:bg-gray-500 text-white px-3 py-1 rounded shadow text-sm transition-colors z-10">
                            &larr; Назад
                        </button>
                        <MtVisualizer 
                            tools={mtTools}
                            selectedSlotId={selectedMtSlotId}
                            onSlotClick={setSelectedMtSlotId}
                        />
                    </div>
                 ) : (
                    <div className="w-full h-full p-8">
                        <TurretVisualizer 
                            stations={currentStations}
                            tools={toolsOnTurret}
                            selectedStationId={selectedStationId}
                            onStationClick={handleStationClick}
                            mode="setup"
                        />
                    </div>
                 )}
            </div>

            <div className="w-96 bg-gray-800 text-gray-100 flex flex-col border-l border-gray-700 shadow-xl z-10">
                <div className="p-4 border-b border-gray-700 bg-gray-900">
                    <h2 className="text-lg font-bold text-blue-400 mb-2 flex items-center"><SettingsIcon className="w-5 h-5 mr-2"/> Настройка Револьвера</h2>
                    <div className="space-y-2">
                        <div>
                             <label className="text-xs text-gray-400 block mb-1">Текущая конфигурация</label>
                             <div className="flex space-x-2">
                                <select 
                                    value={activeLayoutId} 
                                    onChange={(e) => loadLayout(e.target.value)} 
                                    className="flex-1 bg-gray-700 text-white border border-gray-600 rounded px-2 py-1 text-sm"
                                >
                                    {layouts.map(l => <option key={l.id} value={l.id}>{l.name}</option>)}
                                </select>
                                <button onClick={() => deleteLayout(activeLayoutId)} className="bg-red-800 hover:bg-red-700 p-1 rounded text-white"><TrashIcon className="w-4 h-4"/></button>
                             </div>
                        </div>
                        <div className="flex space-x-2 pt-2 border-t border-gray-700">
                             <input 
                                type="text" 
                                placeholder="Новое имя..." 
                                value={newLayoutName}
                                onChange={e => setNewLayoutName(e.target.value)}
                                className="flex-1 bg-gray-700 text-white px-2 py-1 rounded border border-gray-600 text-sm"
                            />
                            <button onClick={saveLayout} className="bg-green-600 hover:bg-green-500 p-1 rounded text-white"><SaveIcon className="w-4 h-4"/></button>
                        </div>
                    </div>
                </div>

                <div className="p-4 border-b border-gray-700 bg-gray-800">
                    <h3 className="font-bold text-gray-300 mb-2">
                        {isMtView 
                            ? `MT Станция ${selectedStationId} - Слот ${selectedMtSlotId || 'не выбран'}` 
                            : (selectedStationId ? `Станция ${selectedStationId}` : 'Выберите станцию')}
                    </h3>

                    {(selectedStation && !isMtView) || (isMtView && selectedMtSlotId) ? (
                        <div className="space-y-3">
                            {!isMtView && (
                                <div className="flex space-x-4">
                                    <div className="flex-1">
                                        <label className="text-xs text-gray-400 block mb-1">Тип гнезда</label>
                                        <select 
                                            value={selectedStation?.type}
                                            onChange={(e) => selectedStation && updateStationConfig(selectedStation.id, { type: e.target.value })}
                                            className="w-full bg-gray-700 border border-gray-600 rounded px-2 py-1 text-sm"
                                        >
                                            {['A', 'B', 'C', 'D', 'MT'].map(t => <option key={t} value={t}>{t}</option>)}
                                        </select>
                                    </div>
                                    <div className="flex items-end pb-2">
                                        <label className="flex items-center space-x-2 cursor-pointer">
                                            <input 
                                                type="checkbox" 
                                                checked={selectedStation?.isAutoIndex} 
                                                onChange={(e) => selectedStation && updateStationConfig(selectedStation.id, { isAutoIndex: e.target.checked })}
                                                className="form-checkbox h-4 w-4 text-blue-600 bg-gray-700 border-gray-500" 
                                            />
                                            <span className="text-sm">Auto Index</span>
                                        </label>
                                    </div>
                                </div>
                            )}

                            {activeTool && (
                                <div className="bg-gray-700 p-3 rounded mt-2 border border-gray-600">
                                    <div className="flex items-center space-x-3 mb-3">
                                        <div className="w-10 h-10 bg-white rounded flex-shrink-0 overflow-hidden"><ToolPreview tool={activeTool} /></div>
                                        <div className="overflow-hidden">
                                            <div className="font-bold text-sm text-white truncate" title={activeTool.name}>{activeTool.name}</div>
                                            <div className="text-xs text-gray-400">{activeTool.width}x{activeTool.height}</div>
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-2 mb-3">
                                        <div>
                                            <label className="block text-[10px] text-gray-400 mb-1">Положение (град.)</label>
                                            <select 
                                                value={activeTool.defaultRotation || 0} 
                                                onChange={(e) => updateToolRotation(activeTool.id, parseFloat(e.target.value))}
                                                className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs"
                                            >
                                                {[0, 45, 90, 135, 180, 225, 270, 315].map(angle => (
                                                    <option key={angle} value={angle}>{angle}°</option>
                                                ))}
                                            </select>
                                        </div>
                                        <div>
                                            <label className="block text-[10px] text-gray-400 mb-1">Зазор матрицы</label>
                                            <div className="w-full bg-gray-900 border border-gray-600 rounded px-2 py-1 text-xs text-gray-300">
                                                {activeTool.dies?.[0]?.clearance || '0.0'} мм
                                            </div>
                                        </div>
                                    </div>

                                    <button onClick={() => handleUnmountTool(activeTool.id)} className="w-full bg-red-800 hover:bg-red-700 text-white text-xs py-2 rounded flex items-center justify-center transition-colors">
                                        <TrashIcon className="w-4 h-4 mr-2" /> Снять инструмент
                                    </button>
                                </div>
                            )}

                             {!activeTool && (
                                 <div className="bg-gray-700/50 border border-dashed border-gray-600 rounded p-4 text-center">
                                     <p className="text-xs text-gray-500">Инструмент не установлен</p>
                                     {isMtView && !selectedMtSlotId && <p className="text-[10px] text-gray-400 mt-1">Выберите слот на схеме для установки</p>}
                                 </div>
                             )}

                            {selectedStation?.type === 'MT' && !isMtView && (
                                <button onClick={() => { setIsMtView(true); setSelectedMtSlotId(1); }} className="w-full bg-purple-700 hover:bg-purple-600 text-white py-1 rounded text-sm mt-2">
                                    Открыть Multi-Tool
                                </button>
                            )}
                        </div>
                    ) : (
                        <p className="text-xs text-gray-500 italic">
                            {isMtView ? "Выберите слот мультитула для настройки" : "Нажмите на станцию слева для редактирования"}
                        </p>
                    )}
                </div>

                <div className="flex-1 overflow-hidden flex flex-col">
                    <div className="p-2 bg-gray-900 border-b border-gray-700">
                        <h4 className="text-xs font-bold text-gray-400 uppercase">Библиотека</h4>
                    </div>
                    <div className="flex-1 overflow-y-auto p-2 space-y-2">
                         {availableTools.map(tool => {
                             const displaySize = (tool.stationType === 'MT' || tool.name.startsWith('MT')) ? 'MT' : tool.toolSize;
                             const stationType = selectedStation?.type;
                             let isCompatible = false;
                             if (selectedStation) {
                                 if (isMtView) isCompatible = tool.stationType === 'MT'; 
                                 else if (stationType === 'MT') isCompatible = false; 
                                 else isCompatible = tool.toolSize === stationType;
                             }

                             const canMount = isCompatible && ((!isMtView && selectedStationId) || (isMtView && selectedMtSlotId));

                             return (
                                <div key={tool.id} className={`bg-gray-700 p-2 rounded flex flex-col group border border-transparent ${isCompatible ? 'hover:border-blue-400' : 'opacity-50'}`}>
                                    <div className="flex items-center space-x-2">
                                        <div className="w-8 h-8 bg-white rounded flex-shrink-0"><ToolPreview tool={tool} /></div>
                                        <div className="overflow-hidden flex-1">
                                            <div className="font-bold text-sm text-white truncate">{tool.name}</div>
                                            <div className="flex justify-between text-xs text-gray-400">
                                                <span>{tool.shape} {tool.width}x{tool.height}</span>
                                                <span className={`font-bold ${displaySize === 'MT' ? 'text-purple-400' : 'text-yellow-400'}`}>{displaySize}</span>
                                            </div>
                                        </div>
                                    </div>

                                    {canMount && (
                                        <div className="mt-2">
                                            <button 
                                                onClick={() => handleMountTool(tool, isMtView && selectedMtSlotId ? selectedMtSlotId : 0)}
                                                className={`w-full text-white text-xs py-1 rounded ${isMtView ? 'bg-purple-600 hover:bg-purple-500' : 'bg-blue-600 hover:bg-blue-500'}`}
                                            >
                                                {isMtView ? `В слот ${selectedMtSlotId}` : "Установить"}
                                            </button>
                                        </div>
                                    )}
                                </div>
                             );
                         })}
                         {availableTools.length === 0 && <div className="text-center text-gray-500 text-sm mt-4">Все инструменты установлены</div>}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { Tool, TurretLayout, StationConfig } from '../types';
import { ToolPreview } from './common/ToolDisplay';
import { SaveIcon, TrashIcon, SettingsIcon } from './Icons';
import { generateId } from '../utils/helpers';
import { TurretVisualizer, MtVisualizer } from './common/TurretVisualizer';

interface TurretSetupViewProps {
    tools: Tool[];
    setTools: React.Dispatch<React.SetStateAction<Tool[]>>;
    layouts: TurretLayout[];
    setLayouts: React.Dispatch<React.SetStateAction<TurretLayout[]>>;
}

export const TurretSetupView: React.FC<TurretSetupViewProps> = ({ tools, setTools, layouts, setLayouts }) => {
    const [activeLayoutId, setActiveLayoutId] = useState<string>(layouts[0]?.id || '');
    const [currentStations, setCurrentStations] = useState<StationConfig[]>(layouts[0]?.stations || []);
    const [selectedStationId, setSelectedStationId] = useState<number | null>(null);
    const [isMtView, setIsMtView] = useState(false);
    const [selectedMtSlotId, setSelectedMtSlotId] = useState<number | null>(null);
    const [newLayoutName, setNewLayoutName] = useState('');

    useEffect(() => {
        const layout = layouts.find(l => l.id === activeLayoutId);
        if (layout) {
            setCurrentStations(layout.stations);
        }
    }, [activeLayoutId, layouts]);

    const toolsOnTurret = tools.filter(t => t.stationNumber !== 0 && t.stationNumber !== undefined);
    const availableTools = tools.filter(t => !t.stationNumber);

    const loadLayout = (layoutId: string) => {
        const layout = layouts.find(l => l.id === layoutId);
        if (!layout) return;
        setTools(JSON.parse(JSON.stringify(layout.toolsSnapshot)));
        setCurrentStations(JSON.parse(JSON.stringify(layout.stations)));
        setActiveLayoutId(layoutId);
        setSelectedStationId(null);
        setIsMtView(false);
        setSelectedMtSlotId(null);
    };

    const saveLayout = () => {
        if (!newLayoutName.trim()) return;
        const newLayout: TurretLayout = {
            id: generateId(),
            name: newLayoutName,
            toolsSnapshot: JSON.parse(JSON.stringify(tools)),
            stations: JSON.parse(JSON.stringify(currentStations))
        };
        setLayouts(prev => [...prev, newLayout]);
        setActiveLayoutId(newLayout.id);
        setNewLayoutName('');
    };

    const deleteLayout = (id: string) => {
        if (layouts.length <= 1) {
            alert("Нельзя удалить единственную конфигурацию.");
            return;
        }
        setLayouts(prev => prev.filter(l => l.id !== id));
        if (activeLayoutId === id) {
            loadLayout(layouts[0].id);
        }
    };

    const updateStationConfig = (id: number, updates: Partial<StationConfig>) => {
        setCurrentStations(prev => prev.map(s => s.id === id ? { ...s, ...updates } : s));
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, stations: prev.find(lx => lx.id === activeLayoutId)?.stations.map(s => s.id === id ? { ...s, ...updates } : s) || [] } : l));
    };

    const handleStationClick = (stationId: number) => {
        const station = currentStations.find(s => s.id === stationId);
        if (station?.type === 'MT') {
            setIsMtView(true);
            setSelectedMtSlotId(1);
        }
        setSelectedStationId(stationId);
    };

    const checkCompatibility = (tool: Tool, station: StationConfig): boolean => {
        if (station.type === 'MT') {
            return tool.stationType === 'MT';
        }
        return tool.toolSize === station.type;
    };

    const handleMountTool = (tool: Tool, mtIndex?: number) => {
        if (!selectedStationId) return;

        const station = currentStations.find(s => s.id === selectedStationId);
        if (!station) return;

        if (!checkCompatibility(tool, station)) {
            alert(`Ошибка: Инструмент размера '${tool.toolSize}' нельзя установить в станцию типа '${station.type}'`);
            return;
        }

        const updatedTools = tools.map(t => {
            if (t.stationNumber === selectedStationId) {
                if (isMtView) {
                    if (t.mtIndex === mtIndex) return { ...t, stationNumber: 0, mtIndex: 0 };
                } else {
                    return { ...t, stationNumber: 0, mtIndex: 0 };
                }
            }
            if (t.id === tool.id) {
                return { ...t, stationNumber: selectedStationId, mtIndex: mtIndex || 0 };
            }
            return t;
        });
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    const handleUnmountTool = (toolId: string) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, stationNumber: 0, mtIndex: 0 } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    const updateToolRotation = (toolId: string, rotation: number) => {
        const updatedTools = tools.map(t => t.id === toolId ? { ...t, defaultRotation: rotation } : t);
        setTools(updatedTools);
        setLayouts(prev => prev.map(l => l.id === activeLayoutId ? { ...l, toolsSnapshot: updatedTools } : l));
    };

    const selectedStation = currentStations.find(s => s.id === selectedStationId);

    const activeTool = isMtView 
        ? toolsOnTurret.find(t => t.stationNumber === selectedStationId && t.mtIndex === selectedMtSlotId)
        : (selectedStation ? toolsOnTurret.find(t => t.stationNumber === selectedStation.id && !t.mtIndex) : null);

    // Helpers for Visualizers
    const mtTools = isMtView ? toolsOnTurret.filter(t => t.stationNumber === selectedStationId) : [];

    return (
        <div className="flex h-full w-full bg-gray-100 text-gray-900 font-sans">
            <div className="flex-1 relative bg-gray-300 shadow-inner overflow-hidden flex items-center justify-center">

                 {/* Visualizer Container */}
                 {isMtView ? (
                    <div className="w-full h-full flex flex-col relative p-8">
                        <button onClick={() => setIsMtView(false)} className="absolute top-4 left-4 bg-gray-600 hover:bg-gray-500 text-white px-3 py-1 rounded shadow text-sm transition-colors z-10">
                            &larr; Назад
                        </button>
                        <MtVisualizer 
                            tools={mtTools}
                            selectedSlotId={selectedMtSlotId}
                            onSlotClick={setSelectedMtSlotId}
                        />
                    </div>
                 ) : (
                    <div className="w-full h-full p-8">
                        <TurretVisualizer 
                            stations={currentStations}
                            tools={toolsOnTurret}
                            selectedStationId={selectedStationId}
                            onStationClick={handleStationClick}
                            mode="setup"
                        />
                    </div>
                 )}
            </div>

            <div className="w-96 bg-gray-800 text-gray-100 flex flex-col border-l border-gray-700 shadow-xl z-10">
                <div className="p-4 border-b border-gray-700 bg-gray-900">
                    <h2 className="text-lg font-bold text-blue-400 mb-2 flex items-center"><SettingsIcon className="w-5 h-5 mr-2"/> Настройка Револьвера</h2>
                    <div className="space-y-2">
                        <div>
                             <label className="text-xs text-gray-400 block mb-1">Текущая конфигурация</label>
                             <div className="flex space-x-2">
                                <select 
                                    value={activeLayoutId} 
                                    onChange={(e) => loadLayout(e.target.value)} 
                                    className="flex-1 bg-gray-700 text-white border border-gray-600 rounded px-2 py-1 text-sm"
                                >
                                    {layouts.map(l => <option key={l.id} value={l.id}>{l.name}</option>)}
                                </select>
                                <button onClick={() => deleteLayout(activeLayoutId)} className="bg-red-800 hover:bg-red-700 p-1 rounded text-white"><TrashIcon className="w-4 h-4"/></button>
                             </div>
                        </div>
                        <div className="flex space-x-2 pt-2 border-t border-gray-700">
                             <input 
                                type="text" 
                                placeholder="Новое имя..." 
                                value={newLayoutName}
                                onChange={e => setNewLayoutName(e.target.value)}
                                className="flex-1 bg-gray-700 text-white px-2 py-1 rounded border border-gray-600 text-sm"
                            />
                            <button onClick={saveLayout} className="bg-green-600 hover:bg-green-500 p-1 rounded text-white"><SaveIcon className="w-4 h-4"/></button>
                        </div>
                    </div>
                </div>

                <div className="p-4 border-b border-gray-700 bg-gray-800">
                    <h3 className="font-bold text-gray-300 mb-2">
                        {isMtView 
                            ? `MT Станция ${selectedStationId} - Слот ${selectedMtSlotId || 'не выбран'}` 
                            : (selectedStationId ? `Станция ${selectedStationId}` : 'Выберите станцию')}
                    </h3>

                    {(selectedStation && !isMtView) || (isMtView && selectedMtSlotId) ? (
