                                            const oldR = pp.rotation * Math.PI / 180; const newR = ((pp.rotation+90)%360) * Math.PI / 180;
                                            const cxOld = (w/2)*Math.cos(oldR) - (h/2)*Math.sin(oldR); const cyOld = (w/2)*Math.sin(oldR) + (h/2)*Math.cos(oldR);
