// ENABLE DEBUGGING HERE
const DEBUG_TEACH = false;

const debugLog = (msg: string, ...args: any[]) => {
    if (DEBUG_TEACH) console.log(`%c[TeachLogic] ${msg}`, 'color: #bada55', ...args);
};

const debugGroup = (label: string) => {
    if (DEBUG_TEACH) console.groupCollapsed(`%c[TeachLogic] ${label}`, 'color: #dda0dd');
};

const debugGroupEnd = () => {
    if (DEBUG_TEACH) console.groupEnd();
};

// Helper: Distance squared
const distSq = (p1: Point, p2: Point) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
const dist = (p1: Point, p2: Point) => Math.sqrt(distSq(p1, p2));

/**
 * Helper to normalize angle to -180..180
 */
const normalizeAngle = (deg: number) => {
    let d = deg;
    while (d > 180) d -= 360;
    while (d <= -180) d += 360;
    return d;
};

// Check if a point C is to the left of vector AB (2D Cross Product)
const isCenterLeft = (a: Point, b: Point, c: Point): boolean => {
    return ((b.x - a.x)*(c.y - a.y) - (b.y - a.y)*(c.x - a.x)) > 0;
};

/**
 * Checks if a punch is aligned with a line segment.
 * Returns metadata about the alignment (longitudinal t-value and lateral distance).
 * 
 * @param maxLatDist Maximum lateral distance to consider "aligned" (handles tool offset)
 */
const isPunchAlignedWithSegment = (p: {x: number, y: number}, seg: Segment, maxLatDist: number = 50.0): { aligned: boolean, t: number, dist: number } => {
    if (seg.type !== 'line') return { aligned: false, t: 0, dist: 0 };

    const dx = seg.p2.x - seg.p1.x;
    const dy = seg.p2.y - seg.p1.y;
    const l2 = dx*dx + dy*dy;

    if (l2 === 0) return { aligned: false, t: 0, dist: 0 };

    // Projection parameter t (0 = p1, 1 = p2)
    const t = ((p.x - seg.p1.x) * dx + (p.y - seg.p1.y) * dy) / l2;

    // Allow significant extension beyond line ends (e.g. for start/end nibbles)
    // Range -0.5 to 1.5 allows extension up to 50% of line length on either side
    if (t < -0.5 || t > 1.5) return { aligned: false, t, dist: 0 };

    // Signed distance calculation (Cross product / Length)
    const cross = dx * (p.y - seg.p1.y) - dy * (p.x - seg.p1.x);
    const dist = cross / Math.sqrt(l2);

    // Check lateral distance
    if (Math.abs(dist) > maxLatDist) return { aligned: false, t, dist };

    return { aligned: true, t, dist };
};

/**
 * Groups punches based on their adherence to the specific contour segments involved in the match.
 * Uses a "Best Fit" strategy: each punch is assigned to the closest valid segment, 
 * ensuring that adjacent horizontal/vertical lines don't "steal" each other's punches.
 */
const groupPunchesByTopology = (
    punches: Omit<PlacedTool, 'id'>[], 
    matchedSegments: Segment[],
    cycleName: string
): Omit<PlacedTool, 'id'>[] => {

    // Map to store best segment assignment for each punch
    // Key: Punch object reference
    const assignments = new Map<Omit<PlacedTool, 'id'>, { segIdx: number, dist: number, signedOffset: number }>();
    const MAX_LATERAL_DIST = 20.0; // Tighter tolerance to prevent cross-talk

    // 1. Assign each punch to its closest aligned segment
    punches.forEach(p => {
        let bestSegIdx = -1;
        let minAbsDist = Infinity;
        let bestSignedOffset = 0;

        matchedSegments.forEach((seg, sIdx) => {
            if (seg.type !== 'line') return;

            const res = isPunchAlignedWithSegment(p, seg, MAX_LATERAL_DIST);
            if (res.aligned) {
                const absDist = Math.abs(res.dist);
                if (absDist < minAbsDist) {
                    minAbsDist = absDist;
                    bestSegIdx = sIdx;
                    bestSignedOffset = res.dist;
                }
            }
        });

        if (bestSegIdx !== -1) {
            assignments.set(p, { segIdx: bestSegIdx, dist: minAbsDist, signedOffset: bestSignedOffset });
        }
    });

    // 2. Group punches by their assigned Segment
    const segmentGroups = new Map<number, Omit<PlacedTool, 'id'>[]>();
    assignments.forEach((info, p) => {
        if (!segmentGroups.has(info.segIdx)) segmentGroups.set(info.segIdx, []);
        segmentGroups.get(info.segIdx)!.push(p);
    });

    // 3. Process each segment group to create "Nibble Lines"
    segmentGroups.forEach((groupPunches, segIdx) => {
        const seg = matchedSegments[segIdx];

        // Sub-group by Tool, Rotation, and Lateral Offset
        // This ensures separate lines for inner vs outer nibbling, or different tools on same line
        const subGroups = new Map<string, Omit<PlacedTool, 'id'>[]>();

        groupPunches.forEach(p => {
            const info = assignments.get(p)!;
            // Round offset to 0.1mm to group standard nibbles while separating distinct offsets
            const offsetKey = Math.round(info.signedOffset * 10) / 10;
            const rotKey = Math.round(p.rotation * 100) / 100;
            const key = `${p.toolId}_${rotKey}_${offsetKey}`;

            if (!subGroups.has(key)) subGroups.set(key, []);
            subGroups.get(key)!.push(p);
        });

        subGroups.forEach(subGroup => {
            if (subGroup.length >= 2) {
                // Sort by position along the line to ensure correct order
                subGroup.sort((a, b) => distSq(a, seg.p1) - distSq(b, seg.p1));

                const lineId = `teach_${cycleName}_${generateId()}`;
                subGroup.forEach(p => {
                    p.lineId = lineId;
                });
            }
        });
    });

    // Return modified punches (references updated with lineId)
    return punches;
};

/**
 * Normalizes a selection of geometry and punches into a generic Pattern.
 * Automatically sorts and oients selected segments into a continuous chain.
 */
export const createTeachCycleFromSelection = (
    name: string,
    symmetry: CycleSymmetry,
    selectedSegmentIndices: number[],
    selectedPunchIds: string[],
    activePart: Part,
    processedGeometry: ProcessedGeometry
): TeachCycle | null => {
    if (selectedSegmentIndices.length === 0 || selectedPunchIds.length === 0) return null;

    debugGroup(`Creating Cycle: ${name}`);

    // 1. Extract Segments
    const pool = selectedSegmentIndices.map(idx => ({ 
        seg: processedGeometry.segments[idx], 
        originalIndex: idx, 
        used: false,
        reverse: false 
    }));

    // 2. Build Chain (Greedy search for continuity)
    const chain: typeof pool = [];

    // Start with the first selected segment (arbitrary start)
    const seed = pool[0];
    seed.used = true;
    chain.push(seed);

    let headPoint = seed.seg.p2;
    let tailPoint = seed.seg.p1;

    // Extend Head (Forward)
    while(true) {
        let found = false;
        for (const candidate of pool) {
            if (candidate.used) continue;

            // Check connectivity to headPoint
            if (distSq(headPoint, candidate.seg.p1) < 0.1) {
                candidate.reverse = false;
                candidate.used = true;
                chain.push(candidate);
                headPoint = candidate.seg.p2;
                found = true;
                break;
            } else if (distSq(headPoint, candidate.seg.p2) < 0.1) {
                candidate.reverse = true;
                candidate.used = true;
                chain.push(candidate);
                headPoint = candidate.seg.p1; // Reversed
                found = true;
                break;
            }
        }
        if (!found) break;
    }

    // Extend Tail (Backward - Prepend)
    while(true) {
        let found = false;
        for (const candidate of pool) {
            if (candidate.used) continue;

            // Check connectivity to tailPoint
            if (distSq(candidate.seg.p2, tailPoint) < 0.1) {
                candidate.reverse = false;
                candidate.used = true;
                chain.unshift(candidate);
                tailPoint = candidate.seg.p1;
                found = true;
                break;
            } else if (distSq(candidate.seg.p1, tailPoint) < 0.1) {
                candidate.reverse = true; 
                candidate.used = true;
                chain.unshift(candidate);
                tailPoint = candidate.seg.p2;
                found = true;
                break;
            }
        }
        if (!found) break;
    }

    debugLog(`Chain built with ${chain.length} segments`);

    // 3. Define Coordinate System based on first segment of the chain
    const firstItem = chain[0];
    const baseP1 = firstItem.reverse ? firstItem.seg.p2 : firstItem.seg.p1;
    const baseP2 = firstItem.reverse ? firstItem.seg.p1 : firstItem.seg.p2;
    const origin = baseP1;
    const baseAngle = Math.atan2(baseP2.y - baseP1.y, baseP2.x - baseP1.x);

    // Transform function: World -> Local Pattern Space
    const toLocal = (p: Point, rot: number = 0): {x: number, y: number, r: number} => {
        // Translate
        const tx = p.x - origin.x;
        const ty = p.y - origin.y;
        // Rotate by -baseAngle
        const rx = tx * Math.cos(-baseAngle) - ty * Math.sin(-baseAngle);
        const ry = tx * Math.sin(-baseAngle) + ty * Math.cos(-baseAngle);
        return { x: rx, y: ry, r: rot - (baseAngle * 180 / Math.PI) };
    };

    // 4. Build Pattern Segments
    const patternSegments: PatternSegment[] = [];

    chain.forEach((item, idx) => {
        const p1 = item.reverse ? item.seg.p2 : item.seg.p1;
        const p2 = item.reverse ? item.seg.p1 : item.seg.p2;

        const len = dist(p1, p2);

        // Calculate vector direction change relative to base angle
        const segAngle = Math.atan2(p2.y - p1.y, p2.x - p1.x);
        const angleDiff = normalizeAngle((segAngle - baseAngle) * 180 / Math.PI);

        // Calculate arc properties
        let arcCenterLeft: boolean | undefined = undefined;
        let isLargeArc = false;
        let sweepAngle = 0;

        if (item.seg.type === 'arc' && item.seg.center && item.seg.radius) {
            // Determine Side (Left or Right of chord)
            arcCenterLeft = isCenterLeft(p1, p2, item.seg.center);

            // Determine Large Arc flag using Original Entity data if available
            if (item.seg.originalEntity && item.seg.originalEntity.type === 'ARC') {
                const arc = item.seg.originalEntity;
                sweepAngle = arc.endAngle - arc.startAngle;
                if (sweepAngle < 0) sweepAngle += 360;
                isLargeArc = sweepAngle > 180;
            } else {
                // Fallback geometry check
                // This is less reliable but useful for generated geometry
                if (Math.abs(len - 2 * item.seg.radius) < 0.1) {
                    // ambiguous semicircle
                }
            }
        }

        debugLog(`Seg ${idx}: Type=${item.seg.type}, Len=${len.toFixed(2)}, AngChange=${angleDiff.toFixed(2)}, ArcLeft=${arcCenterLeft}, LargeArc=${isLargeArc}`);

        patternSegments.push({
            type: item.seg.type === 'arc' ? 'arc' : 'line',
            length: len, // For arcs, this is Chord Length
            angleChange: angleDiff, // Vector direction change
            radius: item.seg.type === 'arc' ? item.seg.radius : undefined,
            arcCenterLeft: arcCenterLeft,
            largeArc: isLargeArc,
            sweepAngle: sweepAngle > 0 ? sweepAngle : undefined
        });
    });

    // 5. Build Pattern Punches
    const patternPunches: PatternPunch[] = [];

    selectedPunchIds.forEach(pid => {
        const p = activePart.punches.find(x => x.id === pid);
        if (p) {
            const loc = toLocal({ x: p.x, y: p.y }, p.rotation);
            debugLog(`Punch ${pid}: Local X=${loc.x.toFixed(2)}, Y=${loc.y.toFixed(2)}, Rot=${loc.r.toFixed(2)}`);
            patternPunches.push({
                toolId: p.toolId,
                relX: loc.x,
                relY: loc.y,
                relRotation: loc.r
            });
        }
    });

    debugGroupEnd();

    return {
        id: generateId(),
        name,
        symmetry,
        segments: patternSegments,
        punches: patternPunches,
        baseAngle // Store original absolute angle
    };
};

/**
 * Finds occurrences of Teach Cycles in the target geometry.
 */
export const findTeachCycleMatches = (
    partGeometry: ProcessedGeometry,
    teachCycles: TeachCycle[]
): { matches: Omit<PlacedTool, 'id'>[], coveredSegmentIndices: Set<number> } => {

    debugGroup('Searching Teach Cycles');

    const resultPunches: Omit<PlacedTool, 'id'>[] = [];
    const coveredIndices = new Set<number>();

    const TOL_LEN = 1.0; 
    const TOL_ANG = 5.0; 
    const TOL_CONN_SQ = 2.0;
    const TOL_DUP_SQ = 0.2;

    const targetSegments = partGeometry.segments;

    const matchesVal = (v1: number, v2: number, tol: number) => Math.abs(v1 - v2) < tol;

    const markCovered = (idx: number) => {
        if (coveredIndices.has(idx)) return;
        coveredIndices.add(idx);
        // Mark duplicates
        const source = targetSegments[idx];
        for(let j=0; j<targetSegments.length; j++) {
            if(j === idx || coveredIndices.has(j)) continue;
            const cand = targetSegments[j];
            if(cand.type !== source.type) continue;
            const dSq = Math.min(
                distSq(source.p1, cand.p1) + distSq(source.p2, cand.p2),
                distSq(source.p1, cand.p2) + distSq(source.p2, cand.p1)
            );
            if (dSq < TOL_DUP_SQ * 2) {
                coveredIndices.add(j);
            }
        }
    };

    teachCycles.forEach(cycle => {
        if (cycle.segments.length === 0) return;
        debugGroup(`Cycle: ${cycle.name} (Sym: ${cycle.symmetry})`);

        // Generate Variants based on Symmetry
        const variants: { 
            name: string, 
            segments: PatternSegment[], 
            punches: PatternPunch[], 
            isMirrored: boolean // True if chirality is flipped (e.g. Left turns become Right turns)
        }[] = [];

        // 1. Original (Chirality Normal)
        variants.push({ 
            name: "Original",
            segments: cycle.segments, 
            punches: cycle.punches, 
            isMirrored: false
        });

        // 2. Mirrored (Chirality Flipped)
        // If "Full Symmetry" or "Horizontal" or "Vertical", we generate the mirrored variant.
        // This variant represents the topology of the cycle mirrored across its own X-axis (Path).
        if (cycle.symmetry !== 'none') {
             const flippedSegments = cycle.segments.map(s => ({ 
                 ...s, 
                 angleChange: -s.angleChange, // Flip turn direction (Left -> Right)
                 arcCenterLeft: s.arcCenterLeft !== undefined ? !s.arcCenterLeft : undefined // Flip arc side
             }));

             // Flip Tooling across the path axis (X-axis of pattern)
             const flippedPunches = cycle.punches.map(p => ({ 
                ...p, 
                // Flip Y coordinate (Lateral distance from path)
                relY: -p.relY, 
                // Flip Rotation direction (e.g. +45 becomes -45 relative to path)
                relRotation: -p.relRotation 
             }));

             variants.push({
                name: "Mirrored",
                segments: flippedSegments,
                punches: flippedPunches, 
                isMirrored: true
             });
        }

        // Search in target geometry
        for (let i = 0; i < targetSegments.length; i++) {
            if (coveredIndices.has(i)) continue;

            const startSeg = targetSegments[i];

            // Try both directions for the starting segment
            const startDirections = [false, true];

            for (const startReverse of startDirections) {
                if (coveredIndices.has(i)) break; 

                const startP1 = startReverse ? startSeg.p2 : startSeg.p1;
                const startP2 = startReverse ? startSeg.p1 : startSeg.p2;

                // Define Local Coordinate System for this candidate match
                // Angle of the matched segment
                const baseAngle = Math.atan2(startP2.y - startP1.y, startP2.x - startP1.x);
                const origin = startP1;

                // --- ANGLE & SYMMETRY CHECK ---
                const cycleAngleDeg = (cycle.baseAngle || 0) * 180 / Math.PI;
                const matchAngleDeg = baseAngle * 180 / Math.PI;

                for (const variant of variants) {
                    if (coveredIndices.has(i)) break;

                    // Filter Logic: Does the angle of the segment match an allowed angle for this variant?
                    let isAngleAllowed = false;

                    if (!variant.isMirrored) {
                        // "Original" Topology. 
                        // Matches strict rotation (0) OR 180-rotation if symmetry allows.
                        // Full symmetry: Allows Rotation 180 (which preserves topology).

                        // Case A: Exact Match (Rotation 0)
                        const diff0 = normalizeAngle(matchAngleDeg - cycleAngleDeg);
                        if (Math.abs(diff0) < TOL_ANG) isAngleAllowed = true;

                        // Case B: Rotation 180 (Full Symmetry only)
                        // A 180-degree rotation of the whole part is equivalent to Mirror X + Mirror Y.
                        // It preserves chirality (Left turn stays Left turn).
                        if (!isAngleAllowed && cycle.symmetry === 'full') {
                            const diff180 = normalizeAngle(matchAngleDeg - (cycleAngleDeg + 180));
                            if (Math.abs(diff180) < TOL_ANG) isAngleAllowed = true;
                        }
                    } else {
                        // "Mirrored" Topology.
                        // This topology applies if the shape is flipped.
                        // Check if the current angle corresponds to a valid reflection.

                        // Case C: Mirror Y (Horizontal). Angle -> -Angle.
                        if (cycle.symmetry === 'horizontal' || cycle.symmetry === 'full') {
                            const diffHorz = normalizeAngle(matchAngleDeg - (-cycleAngleDeg));
                            if (Math.abs(diffHorz) < TOL_ANG) isAngleAllowed = true;
                        }

                        // Case D: Mirror X (Vertical). Angle -> 180 - Angle.
                        if (!isAngleAllowed && (cycle.symmetry === 'vertical' || cycle.symmetry === 'full')) {
                            const diffVert = normalizeAngle(matchAngleDeg - (180 - cycleAngleDeg));
                            if (Math.abs(diffVert) < TOL_ANG) isAngleAllowed = true;
                        }
                    }

                    if (!isAngleAllowed) continue;

                    const patSegs = variant.segments;
                    const firstPat = patSegs[0];

                    // --- 2. Check FIRST Segment Match ---
                    if (startSeg.type !== firstPat.type) continue;

                    const actualLen = dist(startP1, startP2);
                    if (!matchesVal(actualLen, firstPat.length, TOL_LEN)) continue;

                    // Arc Check (First Segment)
                    if (firstPat.type === 'arc') {
                        if (!startSeg.radius || !firstPat.radius || !matchesVal(startSeg.radius, firstPat.radius, TOL_LEN)) continue;

                        // Strict Large Arc Check
                        let isActualLarge = false;
                        if (startSeg.originalEntity && startSeg.originalEntity.type === 'ARC') {
                            let sweep = startSeg.originalEntity.endAngle - startSeg.originalEntity.startAngle;
                            if (sweep < 0) sweep += 360;
                            isActualLarge = sweep > 180;
                        }

                        if (firstPat.largeArc !== undefined && isActualLarge !== firstPat.largeArc) {
                            continue;
                        }

                        if (firstPat.arcCenterLeft !== undefined && startSeg.center) {
                            const isActualLeft = isCenterLeft(startP1, startP2, startSeg.center);
                            const expectedLeft = firstPat.arcCenterLeft;

                            if (isActualLeft !== expectedLeft) {
                                continue;
                            }
                        }
                    }

                    // --- 3. Check Chain Continuity ---
                    const matchedIndices = [i];
                    let currentEndpoint = startP2;
                    let matchFound = true;

                    for (let k = 1; k < patSegs.length; k++) {
                        const patSeg = patSegs[k];
                        let foundNextIndex = -1;
                        let nextReverse = false;

                        for(let t=0; t<targetSegments.length; t++) {
                            if (matchedIndices.includes(t) || coveredIndices.has(t)) continue;
                            const candidate = targetSegments[t];

                            if (candidate.type !== patSeg.type) continue;
                            if (!matchesVal(dist(candidate.p1, candidate.p2), patSeg.length, TOL_LEN)) continue;

                            // Check endpoints connectivity
                            let isReverseCand = false;
                            if (distSq(currentEndpoint, candidate.p1) < TOL_CONN_SQ) {
                                isReverseCand = false;
                            } else if (distSq(currentEndpoint, candidate.p2) < TOL_CONN_SQ) {
                                isReverseCand = true;
                            } else {
                                continue; 
                            }

                            const candP1 = isReverseCand ? candidate.p2 : candidate.p1;
                            const candP2 = isReverseCand ? candidate.p1 : candidate.p2;

                            let isGeoMatch = false;

                            if (patSeg.type === 'line') {
                                const candAngle = Math.atan2(candP2.y - candP1.y, candP2.x - candP1.x);
                                const diff = normalizeAngle((candAngle - baseAngle) * 180 / Math.PI);

                                if (matchesVal(diff, patSeg.angleChange, TOL_ANG)) {
                                    isGeoMatch = true;
                                }
                            } else if (patSeg.type === 'arc') {
                                if (candidate.radius && patSeg.radius && matchesVal(candidate.radius, patSeg.radius, TOL_LEN)) {
                                    // Large Arc Check
                                    let isCandLarge = false;
                                    if (candidate.originalEntity && candidate.originalEntity.type === 'ARC') {
                                        let sweep = candidate.originalEntity.endAngle - candidate.originalEntity.startAngle;
                                        if (sweep < 0) sweep += 360;
                                        isCandLarge = sweep > 180;
                                    }
                                    if (patSeg.largeArc !== undefined && isCandLarge !== patSeg.largeArc) {
                                        continue;
                                    }

                                    if (patSeg.arcCenterLeft !== undefined && candidate.center) {
                                        const isActualLeft = isCenterLeft(candP1, candP2, candidate.center);
                                        const expectedLeft = patSeg.arcCenterLeft;

                                        if (isActualLeft === expectedLeft) {
                                            isGeoMatch = true;
                                        }
                                    }
                                }
                            }

                            if (isGeoMatch) {
                                foundNextIndex = t;
                                nextReverse = isReverseCand;
                                break;
                            }
                        }

                        if (foundNextIndex !== -1) {
                            matchedIndices.push(foundNextIndex);
                            const chosen = targetSegments[foundNextIndex];
                            currentEndpoint = nextReverse ? chosen.p1 : chosen.p2;
                        } else {
                            matchFound = false;
                            break;
                        }
                    }

                    if (matchFound) {
                        debugLog(`MATCH FOUND! Segs: [${matchedIndices.join(', ')}]. Var: ${variant.name}, StartRev: ${startReverse}`);

                        // Collect raw punches for this instance
                        const instanceRawPunches: Omit<PlacedTool, 'id'>[] = [];

                        variant.punches.forEach(p => {
                            const rx = p.relX * Math.cos(baseAngle) - p.relY * Math.sin(baseAngle);
                            const ry = p.relX * Math.sin(baseAngle) + p.relY * Math.cos(baseAngle);
                            const wx = origin.x + rx;
                            const wy = origin.y + ry;
                            const wr = p.relRotation + (baseAngle * 180 / Math.PI);

                            instanceRawPunches.push({
                                toolId: p.toolId,
                                x: wx,
                                y: wy,
                                rotation: wr
                            });
                        });

                        // Apply Topology-Aware Grouping
                        const groupedInstance = groupPunchesByTopology(
                            instanceRawPunches, 
                            matchedIndices.map(i => targetSegments[i]), 
                            cycle.name
                        );

                        resultPunches.push(...groupedInstance);

                        matchedIndices.forEach(idx => markCovered(idx));
                        break; 
                    }
                }
            }
        }
        debugGroupEnd();
    });

    debugGroupEnd();
    return { matches: resultPunches, coveredSegmentIndices: coveredIndices };
};

import { generateId } from '../utils/helpers';
import { TeachCycle, Part, PlacedTool, Point, CycleSymmetry, PatternSegment, PatternPunch } from '../types';
import { ProcessedGeometry, Segment } from './geometry';

// ENABLE DEBUGGING HERE
const DEBUG_TEACH = false;

const debugLog = (msg: string, ...args: any[]) => {
    if (DEBUG_TEACH) console.log(`%c[TeachLogic] ${msg}`, 'color: #bada55', ...args);
};

const debugGroup = (label: string) => {
    if (DEBUG_TEACH) console.groupCollapsed(`%c[TeachLogic] ${label}`, 'color: #dda0dd');
};

const debugGroupEnd = () => {
    if (DEBUG_TEACH) console.groupEnd();
};

// Helper: Distance squared
const distSq = (p1: Point, p2: Point) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
const dist = (p1: Point, p2: Point) => Math.sqrt(distSq(p1, p2));

/**
 * Helper to normalize angle to -180..180
 */
const normalizeAngle = (deg: number) => {
    let d = deg;
    while (d > 180) d -= 360;
    while (d <= -180) d += 360;
    return d;
};

// Check if a point C is to the left of vector AB (2D Cross Product)
const isCenterLeft = (a: Point, b: Point, c: Point): boolean => {
    return ((b.x - a.x)*(c.y - a.y) - (b.y - a.y)*(c.x - a.x)) > 0;
};

/**
 * Checks if a punch is aligned with a line segment.
 * Returns metadata about the alignment (longitudinal t-value and lateral distance).
 * 
 * @param maxLatDist Maximum lateral distance to consider "aligned" (handles tool offset)
 */
const isPunchAlignedWithSegment = (p: {x: number, y: number}, seg: Segment, maxLatDist: number = 50.0): { aligned: boolean, t: number, dist: number } => {
    if (seg.type !== 'line') return { aligned: false, t: 0, dist: 0 };

    const dx = seg.p2.x - seg.p1.x;
    const dy = seg.p2.y - seg.p1.y;
    const l2 = dx*dx + dy*dy;

    if (l2 === 0) return { aligned: false, t: 0, dist: 0 };

    // Projection parameter t (0 = p1, 1 = p2)
    const t = ((p.x - seg.p1.x) * dx + (p.y - seg.p1.y) * dy) / l2;

    // Allow significant extension beyond line ends (e.g. for start/end nibbles)
    // Range -0.5 to 1.5 allows extension up to 50% of line length on either side
    if (t < -0.5 || t > 1.5) return { aligned: false, t, dist: 0 };

    // Signed distance calculation (Cross product / Length)
    const cross = dx * (p.y - seg.p1.y) - dy * (p.x - seg.p1.x);
    const dist = cross / Math.sqrt(l2);

    // Check lateral distance
    if (Math.abs(dist) > maxLatDist) return { aligned: false, t, dist };

    return { aligned: true, t, dist };
};

/**
 * Groups punches based on their adherence to the specific contour segments involved in the match.
 * Uses a "Best Fit" strategy: each punch is assigned to the closest valid segment, 
 * ensuring that adjacent horizontal/vertical lines don't "steal" each other's punches.
 */
const groupPunchesByTopology = (
    punches: Omit<PlacedTool, 'id'>[], 
    matchedSegments: Segment[],
    cycleName: string
): Omit<PlacedTool, 'id'>[] => {

    // Map to store best segment assignment for each punch
    // Key: Punch object reference
    const assignments = new Map<Omit<PlacedTool, 'id'>, { segIdx: number, dist: number, signedOffset: number }>();
    const MAX_LATERAL_DIST = 20.0; // Tighter tolerance to prevent cross-talk

    // 1. Assign each punch to its closest aligned segment
    punches.forEach(p => {
        let bestSegIdx = -1;
        let minAbsDist = Infinity;
        let bestSignedOffset = 0;

        matchedSegments.forEach((seg, sIdx) => {
            if (seg.type !== 'line') return;

            const res = isPunchAlignedWithSegment(p, seg, MAX_LATERAL_DIST);
            if (res.aligned) {
                const absDist = Math.abs(res.dist);
                if (absDist < minAbsDist) {
                    minAbsDist = absDist;
                    bestSegIdx = sIdx;
                    bestSignedOffset = res.dist;
                }
            }
        });

        if (bestSegIdx !== -1) {
            assignments.set(p, { segIdx: bestSegIdx, dist: minAbsDist, signedOffset: bestSignedOffset });
        }
    });

    // 2. Group punches by their assigned Segment
    const segmentGroups = new Map<number, Omit<PlacedTool, 'id'>[]>();
    assignments.forEach((info, p) => {
        if (!segmentGroups.has(info.segIdx)) segmentGroups.set(info.segIdx, []);
        segmentGroups.get(info.segIdx)!.push(p);
    });

    // 3. Process each segment group to create "Nibble Lines"
    segmentGroups.forEach((groupPunches, segIdx) => {
        const seg = matchedSegments[segIdx];

        // Sub-group by Tool, Rotation, and Lateral Offset
        // This ensures separate lines for inner vs outer nibbling, or different tools on same line
        const subGroups = new Map<string, Omit<PlacedTool, 'id'>[]>();

        groupPunches.forEach(p => {
            const info = assignments.get(p)!;
            // Round offset to 0.1mm to group standard nibbles while separating distinct offsets
            const offsetKey = Math.round(info.signedOffset * 10) / 10;
            const rotKey = Math.round(p.rotation * 100) / 100;
            const key = `${p.toolId}_${rotKey}_${offsetKey}`;

            if (!subGroups.has(key)) subGroups.set(key, []);
            subGroups.get(key)!.push(p);
        });

        subGroups.forEach(subGroup => {
            if (subGroup.length >= 2) {
                // Sort by position along the line to ensure correct order
                subGroup.sort((a, b) => distSq(a, seg.p1) - distSq(b, seg.p1));

                const lineId = `teach_${cycleName}_${generateId()}`;
                subGroup.forEach(p => {
                    p.lineId = lineId;
                });
            }
        });
    });

    // Return modified punches (references updated with lineId)
    return punches;
};

/**
 * Normalizes a selection of geometry and punches into a generic Pattern.
 * Automatically sorts and oients selected segments into a continuous chain.
 */
export const createTeachCycleFromSelection = (
    name: string,
    symmetry: CycleSymmetry,
    selectedSegmentIndices: number[],
    selectedPunchIds: string[],
    activePart: Part,
    processedGeometry: ProcessedGeometry
): TeachCycle | null => {
    if (selectedSegmentIndices.length === 0 || selectedPunchIds.length === 0) return null;

    debugGroup(`Creating Cycle: ${name}`);

    // 1. Extract Segments
    const pool = selectedSegmentIndices.map(idx => ({ 
        seg: processedGeometry.segments[idx], 
        originalIndex: idx, 
        used: false,
        reverse: false 
    }));

    // 2. Build Chain (Greedy search for continuity)
    const chain: typeof pool = [];

    // Start with the first selected segment (arbitrary start)
    const seed = pool[0];
    seed.used = true;
    chain.push(seed);

    let headPoint = seed.seg.p2;
    let tailPoint = seed.seg.p1;

    // Extend Head (Forward)
    while(true) {
        let found = false;
        for (const candidate of pool) {
            if (candidate.used) continue;

            // Check connectivity to headPoint
            if (distSq(headPoint, candidate.seg.p1) < 0.1) {
                candidate.reverse = false;
                candidate.used = true;
                chain.push(candidate);
                headPoint = candidate.seg.p2;
                found = true;
                break;
            } else if (distSq(headPoint, candidate.seg.p2) < 0.1) {
                candidate.reverse = true;
                candidate.used = true;
                chain.push(candidate);
                headPoint = candidate.seg.p1; // Reversed
                found = true;
                break;
            }
        }
        if (!found) break;
    }

    // Extend Tail (Backward - Prepend)
    while(true) {
        let found = false;
        for (const candidate of pool) {
            if (candidate.used) continue;

            // Check connectivity to tailPoint
            if (distSq(candidate.seg.p2, tailPoint) < 0.1) {
                candidate.reverse = false;
                candidate.used = true;
                chain.unshift(candidate);
                tailPoint = candidate.seg.p1;
                found = true;
                break;
            } else if (distSq(candidate.seg.p1, tailPoint) < 0.1) {
                candidate.reverse = true; 
                candidate.used = true;
                chain.unshift(candidate);
                tailPoint = candidate.seg.p2;
                found = true;
                break;
            }
        }
        if (!found) break;
    }

    debugLog(`Chain built with ${chain.length} segments`);

    // 3. Define Coordinate System based on first segment of the chain
    const firstItem = chain[0];
    const baseP1 = firstItem.reverse ? firstItem.seg.p2 : firstItem.seg.p1;
    const baseP2 = firstItem.reverse ? firstItem.seg.p1 : firstItem.seg.p2;
    const origin = baseP1;
    const baseAngle = Math.atan2(baseP2.y - baseP1.y, baseP2.x - baseP1.x);

    // Transform function: World -> Local Pattern Space
    const toLocal = (p: Point, rot: number = 0): {x: number, y: number, r: number} => {
        // Translate
        const tx = p.x - origin.x;
        const ty = p.y - origin.y;
        // Rotate by -baseAngle
        const rx = tx * Math.cos(-baseAngle) - ty * Math.sin(-baseAngle);
        const ry = tx * Math.sin(-baseAngle) + ty * Math.cos(-baseAngle);
        return { x: rx, y: ry, r: rot - (baseAngle * 180 / Math.PI) };
    };

    // 4. Build Pattern Segments
    const patternSegments: PatternSegment[] = [];

    chain.forEach((item, idx) => {
        const p1 = item.reverse ? item.seg.p2 : item.seg.p1;
        const p2 = item.reverse ? item.seg.p1 : item.seg.p2;

        const len = dist(p1, p2);

        // Calculate vector direction change relative to base angle
        const segAngle = Math.atan2(p2.y - p1.y, p2.x - p1.x);
        const angleDiff = normalizeAngle((segAngle - baseAngle) * 180 / Math.PI);

        // Calculate arc properties
        let arcCenterLeft: boolean | undefined = undefined;
        let isLargeArc = false;
        let sweepAngle = 0;

        if (item.seg.type === 'arc' && item.seg.center && item.seg.radius) {
            // Determine Side (Left or Right of chord)
            arcCenterLeft = isCenterLeft(p1, p2, item.seg.center);

            // Determine Large Arc flag using Original Entity data if available
            if (item.seg.originalEntity && item.seg.originalEntity.type === 'ARC') {
                const arc = item.seg.originalEntity;
                sweepAngle = arc.endAngle - arc.startAngle;
                if (sweepAngle < 0) sweepAngle += 360;
                isLargeArc = sweepAngle > 180;
            } else {
                // Fallback geometry check
                // This is less reliable but useful for generated geometry
                if (Math.abs(len - 2 * item.seg.radius) < 0.1) {
                    // ambiguous semicircle
                }
            }
        }

        debugLog(`Seg ${idx}: Type=${item.seg.type}, Len=${len.toFixed(2)}, AngChange=${angleDiff.toFixed(2)}, ArcLeft=${arcCenterLeft}, LargeArc=${isLargeArc}`);

        patternSegments.push({
            type: item.seg.type === 'arc' ? 'arc' : 'line',
            length: len, // For arcs, this is Chord Length
            angleChange: angleDiff, // Vector direction change
            radius: item.seg.type === 'arc' ? item.seg.radius : undefined,
            arcCenterLeft: arcCenterLeft,
            largeArc: isLargeArc,
            sweepAngle: sweepAngle > 0 ? sweepAngle : undefined
        });
    });

    // 5. Build Pattern Punches
    const patternPunches: PatternPunch[] = [];

    selectedPunchIds.forEach(pid => {
        const p = activePart.punches.find(x => x.id === pid);
        if (p) {
            const loc = toLocal({ x: p.x, y: p.y }, p.rotation);
            debugLog(`Punch ${pid}: Local X=${loc.x.toFixed(2)}, Y=${loc.y.toFixed(2)}, Rot=${loc.r.toFixed(2)}`);
            patternPunches.push({
                toolId: p.toolId,
                relX: loc.x,
                relY: loc.y,
                relRotation: loc.r
            });
        }
    });

    debugGroupEnd();

    return {
        id: generateId(),
        name,
        symmetry,
        segments: patternSegments,
        punches: patternPunches,
        baseAngle // Store original absolute angle
    };
};

/**
 * Finds occurrences of Teach Cycles in the target geometry.
 */
export const findTeachCycleMatches = (
    partGeometry: ProcessedGeometry,
    teachCycles: TeachCycle[]
): { matches: Omit<PlacedTool, 'id'>[], coveredSegmentIndices: Set<number> } => {

    debugGroup('Searching Teach Cycles');

    const resultPunches: Omit<PlacedTool, 'id'>[] = [];
    const coveredIndices = new Set<number>();

    const TOL_LEN = 1.0; 
    const TOL_ANG = 5.0; 
    const TOL_CONN_SQ = 2.0;
    const TOL_DUP_SQ = 0.2;

    const targetSegments = partGeometry.segments;

    const matchesVal = (v1: number, v2: number, tol: number) => Math.abs(v1 - v2) < tol;

    const markCovered = (idx: number) => {
        if (coveredIndices.has(idx)) return;
        coveredIndices.add(idx);
        // Mark duplicates
        const source = targetSegments[idx];
        for(let j=0; j<targetSegments.length; j++) {
            if(j === idx || coveredIndices.has(j)) continue;
            const cand = targetSegments[j];
            if(cand.type !== source.type) continue;
            const dSq = Math.min(
                distSq(source.p1, cand.p1) + distSq(source.p2, cand.p2),
                distSq(source.p1, cand.p2) + distSq(source.p2, cand.p1)
            );
            if (dSq < TOL_DUP_SQ * 2) {
                coveredIndices.add(j);
            }
        }
    };

    teachCycles.forEach(cycle => {
        if (cycle.segments.length === 0) return;
        debugGroup(`Cycle: ${cycle.name} (Sym: ${cycle.symmetry})`);

        // Generate Variants based on Symmetry
        const variants: { 
            name: string, 
            segments: PatternSegment[], 
            punches: PatternPunch[], 
            isMirrored: boolean // True if chirality is flipped (e.g. Left turns become Right turns)
        }[] = [];

        // 1. Original (Chirality Normal)
        variants.push({ 
            name: "Original",
            segments: cycle.segments, 
            punches: cycle.punches, 
            isMirrored: false
        });

        // 2. Mirrored (Chirality Flipped)
        // If "Full Symmetry" or "Horizontal" or "Vertical", we generate the mirrored variant.
        // This variant represents the topology of the cycle mirrored across its own X-axis (Path).
        if (cycle.symmetry !== 'none') {
             const flippedSegments = cycle.segments.map(s => ({ 
                 ...s, 
                 angleChange: -s.angleChange, // Flip turn direction (Left -> Right)
                 arcCenterLeft: s.arcCenterLeft !== undefined ? !s.arcCenterLeft : undefined // Flip arc side
             }));

             // Flip Tooling across the path axis (X-axis of pattern)
             const flippedPunches = cycle.punches.map(p => ({ 
                ...p, 
                // Flip Y coordinate (Lateral distance from path)
                relY: -p.relY, 
                // Flip Rotation direction (e.g. +45 becomes -45 relative to path)
                relRotation: -p.relRotation 
             }));

             variants.push({
                name: "Mirrored",
                segments: flippedSegments,
                punches: flippedPunches, 
                isMirrored: true
             });
        }

        // Search in target geometry
        for (let i = 0; i < targetSegments.length; i++) {
            if (coveredIndices.has(i)) continue;

            const startSeg = targetSegments[i];

            // Try both directions for the starting segment
            const startDirections = [false, true];

            for (const startReverse of startDirections) {
                if (coveredIndices.has(i)) break; 

                const startP1 = startReverse ? startSeg.p2 : startSeg.p1;
                const startP2 = startReverse ? startSeg.p1 : startSeg.p2;

                // Define Local Coordinate System for this candidate match
                // Angle of the matched segment
                const baseAngle = Math.atan2(startP2.y - startP1.y, startP2.x - startP1.x);
                const origin = startP1;

                // --- ANGLE & SYMMETRY CHECK ---
                const cycleAngleDeg = (cycle.baseAngle || 0) * 180 / Math.PI;
                const matchAngleDeg = baseAngle * 180 / Math.PI;

                for (const variant of variants) {
                    if (coveredIndices.has(i)) break;

                    // Filter Logic: Does the angle of the segment match an allowed angle for this variant?
                    let isAngleAllowed = false;

                    if (!variant.isMirrored) {
                        // "Original" Topology. 
                        // Matches strict rotation (0) OR 180-rotation if symmetry allows.
                        // Full symmetry: Allows Rotation 180 (which preserves topology).

                        // Case A: Exact Match (Rotation 0)
                        const diff0 = normalizeAngle(matchAngleDeg - cycleAngleDeg);
                        if (Math.abs(diff0) < TOL_ANG) isAngleAllowed = true;

                        // Case B: Rotation 180 (Full, Horizontal, or Vertical Symmetry)
                        // Allow Rotation 180 for ALL symmetric modes because for closed contours, 
                        // opposite features often appear as Rotated 180 rather than simple reflections 
                        // due to winding direction preservation.
                        if (!isAngleAllowed && (cycle.symmetry === 'full' || cycle.symmetry === 'horizontal' || cycle.symmetry === 'vertical')) {
                            const diff180 = normalizeAngle(matchAngleDeg - (cycleAngleDeg + 180));
                            if (Math.abs(diff180) < TOL_ANG) isAngleAllowed = true;
                        }
                    } else {
                        // "Mirrored" Topology.
                        // This topology applies if the shape is flipped.
                        // Check if the current angle corresponds to a valid reflection.

                        // Case C: Mirror Y (Horizontal). Angle -> -Angle.
                        if (cycle.symmetry === 'horizontal' || cycle.symmetry === 'full') {
                            const diffHorz = normalizeAngle(matchAngleDeg - (-cycleAngleDeg));
                            if (Math.abs(diffHorz) < TOL_ANG) isAngleAllowed = true;
                        }

                        // Case D: Mirror X (Vertical). Angle -> 180 - Angle.
                        if (!isAngleAllowed && (cycle.symmetry === 'vertical' || cycle.symmetry === 'full')) {
                            const diffVert = normalizeAngle(matchAngleDeg - (180 - cycleAngleDeg));
                            if (Math.abs(diffVert) < TOL_ANG) isAngleAllowed = true;
                        }
                    }

                    if (!isAngleAllowed) continue;

                    const patSegs = variant.segments;
                    const firstPat = patSegs[0];

                    // --- 2. Check FIRST Segment Match ---
                    if (startSeg.type !== firstPat.type) continue;

                    const actualLen = dist(startP1, startP2);
                    if (!matchesVal(actualLen, firstPat.length, TOL_LEN)) continue;

                    // Arc Check (First Segment)
                    if (firstPat.type === 'arc') {
                        if (!startSeg.radius || !firstPat.radius || !matchesVal(startSeg.radius, firstPat.radius, TOL_LEN)) continue;

                        // Strict Large Arc Check
                        let isActualLarge = false;
                        if (startSeg.originalEntity && startSeg.originalEntity.type === 'ARC') {
                            let sweep = startSeg.originalEntity.endAngle - startSeg.originalEntity.startAngle;
                            if (sweep < 0) sweep += 360;
                            isActualLarge = sweep > 180;
                        }

                        if (firstPat.largeArc !== undefined && isActualLarge !== firstPat.largeArc) {
                            continue;
                        }

                        if (firstPat.arcCenterLeft !== undefined && startSeg.center) {
                            const isActualLeft = isCenterLeft(startP1, startP2, startSeg.center);
                            const expectedLeft = firstPat.arcCenterLeft;

                            if (isActualLeft !== expectedLeft) {
                                continue;
                            }
                        }
                    }

                    // --- 3. Check Chain Continuity ---
                    const matchedIndices = [i];
                    let currentEndpoint = startP2;
                    let matchFound = true;

                    for (let k = 1; k < patSegs.length; k++) {
                        const patSeg = patSegs[k];
                        let foundNextIndex = -1;
                        let nextReverse = false;

                        for(let t=0; t<targetSegments.length; t++) {
                            if (matchedIndices.includes(t) || coveredIndices.has(t)) continue;
                            const candidate = targetSegments[t];

                            if (candidate.type !== patSeg.type) continue;
                            if (!matchesVal(dist(candidate.p1, candidate.p2), patSeg.length, TOL_LEN)) continue;

                            // Check endpoints connectivity
                            let isReverseCand = false;
                            if (distSq(currentEndpoint, candidate.p1) < TOL_CONN_SQ) {
                                isReverseCand = false;
                            } else if (distSq(currentEndpoint, candidate.p2) < TOL_CONN_SQ) {
                                isReverseCand = true;
                            } else {
                                continue; 
                            }

                            const candP1 = isReverseCand ? candidate.p2 : candidate.p1;
                            const candP2 = isReverseCand ? candidate.p1 : candidate.p2;

                            let isGeoMatch = false;

                            if (patSeg.type === 'line') {
                                const candAngle = Math.atan2(candP2.y - candP1.y, candP2.x - candP1.x);
                                const diff = normalizeAngle((candAngle - baseAngle) * 180 / Math.PI);

                                if (matchesVal(diff, patSeg.angleChange, TOL_ANG)) {
                                    isGeoMatch = true;
                                }
                            } else if (patSeg.type === 'arc') {
                                if (candidate.radius && patSeg.radius && matchesVal(candidate.radius, patSeg.radius, TOL_LEN)) {
                                    // Large Arc Check
                                    let isCandLarge = false;
                                    if (candidate.originalEntity && candidate.originalEntity.type === 'ARC') {
                                        let sweep = candidate.originalEntity.endAngle - candidate.originalEntity.startAngle;
                                        if (sweep < 0) sweep += 360;
                                        isCandLarge = sweep > 180;
                                    }
                                    if (patSeg.largeArc !== undefined && isCandLarge !== patSeg.largeArc) {
                                        continue;
                                    }

                                    if (patSeg.arcCenterLeft !== undefined && candidate.center) {
                                        const isActualLeft = isCenterLeft(candP1, candP2, candidate.center);
                                        const expectedLeft = patSeg.arcCenterLeft;

                                        if (isActualLeft === expectedLeft) {
                                            isGeoMatch = true;
                                        }
                                    }
                                }
                            }

                            if (isGeoMatch) {
                                foundNextIndex = t;
                                nextReverse = isReverseCand;
                                break;
                            }
                        }

                        if (foundNextIndex !== -1) {
                            matchedIndices.push(foundNextIndex);
                            const chosen = targetSegments[foundNextIndex];
                            currentEndpoint = nextReverse ? chosen.p1 : chosen.p2;
                        } else {
                            matchFound = false;
                            break;
                        }
                    }

                    if (matchFound) {
                        debugLog(`MATCH FOUND! Segs: [${matchedIndices.join(', ')}]. Var: ${variant.name}, StartRev: ${startReverse}`);

                        // Collect raw punches for this instance
                        const instanceRawPunches: Omit<PlacedTool, 'id'>[] = [];

                        variant.punches.forEach(p => {
                            const rx = p.relX * Math.cos(baseAngle) - p.relY * Math.sin(baseAngle);
                            const ry = p.relX * Math.sin(baseAngle) + p.relY * Math.cos(baseAngle);
                            const wx = origin.x + rx;
                            const wy = origin.y + ry;
                            const wr = p.relRotation + (baseAngle * 180 / Math.PI);

                            instanceRawPunches.push({
                                toolId: p.toolId,
                                x: wx,
                                y: wy,
                                rotation: wr
                            });
                        });

                        // Apply Topology-Aware Grouping
                        const groupedInstance = groupPunchesByTopology(
                            instanceRawPunches, 
                            matchedIndices.map(i => targetSegments[i]), 
                            cycle.name
                        );

                        resultPunches.push(...groupedInstance);

                        matchedIndices.forEach(idx => markCovered(idx));
                        break; 
                    }
                }
            }
        }
        debugGroupEnd();
    });

    debugGroupEnd();
    return { matches: resultPunches, coveredSegmentIndices: coveredIndices };
};

import { generateId } from '../utils/helpers';
import { TeachCycle, Part, PlacedTool, Point, CycleSymmetry, PatternSegment, PatternPunch } from '../types';
import { ProcessedGeometry, Segment } from './geometry';

// ENABLE DEBUGGING HERE
const DEBUG_TEACH = false;

const debugLog = (msg: string, ...args: any[]) => {
    if (DEBUG_TEACH) console.log(`%c[TeachLogic] ${msg}`, 'color: #bada55', ...args);
};

// Helper: Distance squared
const distSq = (p1: Point, p2: Point) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2;
const dist = (p1: Point, p2: Point) => Math.sqrt(distSq(p1, p2));

/**
 * Normalizes angle to -180..180
 */
const normalizeAngle = (deg: number) => {
    let d = deg;
    while (d > 180) d -= 360;
    while (d <= -180) d += 360;
    return d;
};

// Check if a point C is to the left of vector AB (2D Cross Product)
const isCenterLeft = (a: Point, b: Point, c: Point): boolean => {
    return ((b.x - a.x)*(c.y - a.y) - (b.y - a.y)*(c.x - a.x)) > 0;
};

/**
 * Checks if a punch is aligned with a line segment for topology grouping.
 */
const isPunchAlignedWithSegment = (p: {x: number, y: number}, seg: Segment, maxLatDist: number = 50.0): { aligned: boolean, t: number, dist: number } => {
    if (seg.type !== 'line') return { aligned: false, t: 0, dist: 0 };

    const dx = seg.p2.x - seg.p1.x;
    const dy = seg.p2.y - seg.p1.y;
    const l2 = dx*dx + dy*dy;

    if (l2 === 0) return { aligned: false, t: 0, dist: 0 };

    const t = ((p.x - seg.p1.x) * dx + (p.y - seg.p1.y) * dy) / l2;
    if (t < -0.5 || t > 1.5) return { aligned: false, t, dist: 0 };

    const cross = dx * (p.y - seg.p1.y) - dy * (p.x - seg.p1.x);
    const distVal = cross / Math.sqrt(l2);

    if (Math.abs(distVal) > maxLatDist) return { aligned: false, t, dist: distVal };

    return { aligned: true, t, dist: distVal };
};

/**
 * Groups punches based on their adherence to the matched contour segments.
 */
const groupPunchesByTopology = (
    punches: Omit<PlacedTool, 'id'>[], 
    matchedSegments: Segment[],
    cycleName: string
): Omit<PlacedTool, 'id'>[] => {

    const assignments = new Map<Omit<PlacedTool, 'id'>, { segIdx: number, dist: number, signedOffset: number }>();
    const MAX_LATERAL_DIST = 20.0;

    punches.forEach(p => {
        let bestSegIdx = -1;
        let minAbsDist = Infinity;
        let bestSignedOffset = 0;

        matchedSegments.forEach((seg, sIdx) => {
            if (seg.type !== 'line') return;

            const res = isPunchAlignedWithSegment(p, seg, MAX_LATERAL_DIST);
            if (res.aligned) {
                const absDist = Math.abs(res.dist);
                if (absDist < minAbsDist) {
                    minAbsDist = absDist;
                    bestSegIdx = sIdx;
                    bestSignedOffset = res.dist;
                }
            }
        });

        if (bestSegIdx !== -1) {
            assignments.set(p, { segIdx: bestSegIdx, dist: minAbsDist, signedOffset: bestSignedOffset });
        }
    });

    const segmentGroups = new Map<number, Omit<PlacedTool, 'id'>[]>();
    assignments.forEach((info, p) => {
        if (!segmentGroups.has(info.segIdx)) segmentGroups.set(info.segIdx, []);
        segmentGroups.get(info.segIdx)!.push(p);
    });

    segmentGroups.forEach((groupPunches, segIdx) => {
        const seg = matchedSegments[segIdx];
        const subGroups = new Map<string, Omit<PlacedTool, 'id'>[]>();

        groupPunches.forEach(p => {
            const info = assignments.get(p)!;
            const offsetKey = Math.round(info.signedOffset * 10) / 10;
            const rotKey = Math.round(p.rotation * 100) / 100;
            const key = `${p.toolId}_${rotKey}_${offsetKey}`;

            if (!subGroups.has(key)) subGroups.set(key, []);
            subGroups.get(key)!.push(p);
        });

        subGroups.forEach(subGroup => {
            if (subGroup.length >= 2) {
                subGroup.sort((a, b) => distSq(a, seg.p1) - distSq(b, seg.p1));
                const lineId = `teach_${cycleName}_${generateId()}`;
                subGroup.forEach(p => {
                    p.lineId = lineId;
                });
            }
        });
    });

    return punches;
};

// --- GEOMETRY RECONSTRUCTION HELPERS ---

// Reconstruct explicit points of the pattern chain starting at (0,0)
const reconstructPatternGeometry = (segments: PatternSegment[]): { p1: Point, p2: Point }[] => {
    const result: { p1: Point, p2: Point }[] = [];
    let curX = 0; 
    let curY = 0;
    let curAngle = 0; // Radians. Segment 0 starts at angle 0 relative to itself.

    segments.forEach((seg, idx) => {
        // Apply angle change relative to previous segment vector
        if (idx > 0) {
            curAngle += seg.angleChange * (Math.PI / 180);
        }

        const dx = Math.cos(curAngle) * seg.length;
        const dy = Math.sin(curAngle) * seg.length;
        const nextX = curX + dx;
        const nextY = curY + dy;

        result.push({ 
            p1: { x: curX, y: curY }, 
            p2: { x: nextX, y: nextY } 
        });

        curX = nextX;
        curY = nextY;
    });
    return result;
};

// --- CREATE CYCLE ---
export const createTeachCycleFromSelection = (
    name: string,
    symmetry: CycleSymmetry,
    selectedSegmentIndices: number[],
    selectedPunchIds: string[],
    activePart: Part,
    processedGeometry: ProcessedGeometry
): TeachCycle | null => {
    if (selectedSegmentIndices.length === 0 || selectedPunchIds.length === 0) return null;

    // 1. Build Chain
    const pool = selectedSegmentIndices.map(idx => ({ 
        seg: processedGeometry.segments[idx], 
        originalIndex: idx, used: false, reverse: false 
    }));

    const chain: typeof pool = [];
    const seed = pool[0];
    seed.used = true;
    chain.push(seed);

    let headPoint = seed.seg.p2;
    let tailPoint = seed.seg.p1;

    // Greedy Chain Sort
    // Forward
    while(true) {
        let found = false;
        for (const candidate of pool) {
            if (candidate.used) continue;
            if (distSq(headPoint, candidate.seg.p1) < 0.1) {
                candidate.reverse = false; candidate.used = true;
                chain.push(candidate); headPoint = candidate.seg.p2; found = true; break;
            } else if (distSq(headPoint, candidate.seg.p2) < 0.1) {
                candidate.reverse = true; candidate.used = true;
                chain.push(candidate); headPoint = candidate.seg.p1; found = true; break;
            }
        }
        if (!found) break;
    }
    // Backward
    while(true) {
        let found = false;
        for (const candidate of pool) {
            if (candidate.used) continue;
            if (distSq(candidate.seg.p2, tailPoint) < 0.1) {
                candidate.reverse = false; candidate.used = true;
                chain.unshift(candidate); tailPoint = candidate.seg.p1; found = true; break;
            } else if (distSq(candidate.seg.p1, tailPoint) < 0.1) {
                candidate.reverse = true; candidate.used = true;
                chain.unshift(candidate); tailPoint = candidate.seg.p2; found = true; break;
            }
        }
        if (!found) break;
    }

    // 2. Define Local Coordinate System (Origin at start of first segment, aligned with first segment)
    const firstItem = chain[0];
    const baseP1 = firstItem.reverse ? firstItem.seg.p2 : firstItem.seg.p1;
    const baseP2 = firstItem.reverse ? firstItem.seg.p1 : firstItem.seg.p2;
    const origin = baseP1;
    const baseAngle = Math.atan2(baseP2.y - baseP1.y, baseP2.x - baseP1.x);

    const toLocal = (p: Point, rot: number = 0): {x: number, y: number, r: number} => {
        const tx = p.x - origin.x;
        const ty = p.y - origin.y;
        const rx = tx * Math.cos(-baseAngle) - ty * Math.sin(-baseAngle);
        const ry = tx * Math.sin(-baseAngle) + ty * Math.cos(-baseAngle);
        return { x: rx, y: ry, r: rot - (baseAngle * 180 / Math.PI) };
    };

    // 3. Build Segments
    const patternSegments: PatternSegment[] = [];
    chain.forEach((item, idx) => {
        const p1 = item.reverse ? item.seg.p2 : item.seg.p1;
        const p2 = item.reverse ? item.seg.p1 : item.seg.p2;
        const len = dist(p1, p2);

        // Calculate relative angle change
        // For idx 0, angle change is 0 (it defines the baseline)
        let angleDiff = 0;
        if (idx > 0) {
            // Vector of previous segment
            const prevItem = chain[idx-1];
            const pp1 = prevItem.reverse ? prevItem.seg.p2 : prevItem.seg.p1;
            const pp2 = prevItem.reverse ? prevItem.seg.p1 : prevItem.seg.p2;
            const prevAngle = Math.atan2(pp2.y - pp1.y, pp2.x - pp1.x);
            const currAngle = Math.atan2(p2.y - p1.y, p2.x - p1.x);
            angleDiff = normalizeAngle((currAngle - prevAngle) * 180 / Math.PI);
        }

        let arcCenterLeft: boolean | undefined = undefined;
        let isLargeArc = false;
        let sweepAngle = 0;

        if (item.seg.type === 'arc' && item.seg.center && item.seg.radius) {
            arcCenterLeft = isCenterLeft(p1, p2, item.seg.center);
            if (item.seg.originalEntity && item.seg.originalEntity.type === 'ARC') {
                const arc = item.seg.originalEntity;
                sweepAngle = arc.endAngle - arc.startAngle;
                if (sweepAngle < 0) sweepAngle += 360;
                isLargeArc = sweepAngle > 180;
            }
        }

        patternSegments.push({
            type: item.seg.type === 'arc' ? 'arc' : 'line',
            length: len,
            angleChange: angleDiff,
            radius: item.seg.type === 'arc' ? item.seg.radius : undefined,
            arcCenterLeft,
            largeArc: isLargeArc,
            sweepAngle: sweepAngle > 0 ? sweepAngle : undefined
        });
    });

    // 4. Build Punches
    const patternPunches: PatternPunch[] = [];
    selectedPunchIds.forEach(pid => {
        const p = activePart.punches.find(x => x.id === pid);
        if (p) {
            const loc = toLocal({ x: p.x, y: p.y }, p.rotation);
            patternPunches.push({
                toolId: p.toolId,
                relX: loc.x,
                relY: loc.y,
                relRotation: loc.r
            });
        }
    });

    return {
        id: generateId(),
        name,
        symmetry,
        segments: patternSegments,
        punches: patternPunches,
        baseAngle
    };
};

// --- FIND MATCHES (Matrix Method) ---

export const findTeachCycleMatches = (
    partGeometry: ProcessedGeometry,
    teachCycles: TeachCycle[]
): { matches: Omit<PlacedTool, 'id'>[], coveredSegmentIndices: Set<number> } => {

    const resultPunches: Omit<PlacedTool, 'id'>[] = [];
    const coveredIndices = new Set<number>();

    const TOL_LEN = 1.0; 
    const TOL_POS = 1.5; 

    // Match Helper
    const isSamePoint = (p1: Point, p2: Point) => (p1.x - p2.x)**2 + (p1.y - p2.y)**2 < TOL_POS;

    const targetSegments = partGeometry.segments;

    teachCycles.forEach(cycle => {
        if (cycle.segments.length === 0) return;

        // 1. Reconstruct Abstract Chain Points in Local Pattern Space
        const patternChain = reconstructPatternGeometry(cycle.segments);
        const patternSeg0 = patternChain[0]; // Baseline segment from (0,0) to (L, 0)

        // 2. Define Transformations based on Symmetry
        type Transform = { scaleX: number, scaleY: number, rotation: number, name: string };
        const transforms: Transform[] = [];

        // Always add Identity
        transforms.push({ scaleX: 1, scaleY: 1, rotation: 0, name: 'Original' });

        if (cycle.symmetry === 'full') {
            transforms.push({ scaleX: -1, scaleY: 1, rotation: 0, name: 'Mirror X' }); // Vertical Mirror
            transforms.push({ scaleX: 1, scaleY: -1, rotation: 0, name: 'Mirror Y' }); // Horizontal Mirror
            transforms.push({ scaleX: -1, scaleY: -1, rotation: 0, name: 'Rot 180' });
        } else if (cycle.symmetry === 'vertical') {
            // Vertical symmetry = Left/Right flip = Mirror X
            transforms.push({ scaleX: -1, scaleY: 1, rotation: 0, name: 'Mirror X' });
        } else if (cycle.symmetry === 'horizontal') {
            // Horizontal symmetry = Top/Bottom flip = Mirror Y
            transforms.push({ scaleX: 1, scaleY: -1, rotation: 0, name: 'Mirror Y' });
        }

        // 3. Scan Target Segments
        for (let i = 0; i < targetSegments.length; i++) {
            if (coveredIndices.has(i)) continue;
            const targetSeg = targetSegments[i];

            // Filter by Type and Length immediately
            if (targetSeg.type !== cycle.segments[0].type) continue;
            if (Math.abs(dist(targetSeg.p1, targetSeg.p2) - cycle.segments[0].length) > TOL_LEN) continue;

            // Try both directions of target segment
            const directions = [
                { start: targetSeg.p1, end: targetSeg.p2 },
                { start: targetSeg.p2, end: targetSeg.p1 }
            ];

            for (const dir of directions) {
                const targetStart = dir.start;
                const targetEnd = dir.end;
                const targetAngle = Math.atan2(targetEnd.y - targetStart.y, targetEnd.x - targetStart.x);

                // Try all allowed Symmetry Transforms
                for (const trans of transforms) {
                    if (coveredIndices.has(i)) break;

                    // --- ALIGNMENT ---
                    // 1. Apply Symmetry Transform to Pattern Seg 0
                    // Original Seg0 is (0,0) -> (Len, 0)
                    // Transformed Seg0 Vector:
                    const p0_vec_x = patternSeg0.p2.x - patternSeg0.p1.x; // Len
                    const p0_vec_y = patternSeg0.p2.y - patternSeg0.p1.y; // 0

                    // Apply Scale
                    const sx = p0_vec_x * trans.scaleX;
                    const sy = p0_vec_y * trans.scaleY; // Still 0

                    // Angle of the transformed pattern baseline in Pattern Space
                    const patBaseAngle = Math.atan2(sy, sx);

                    // 2. Determine Required Rotation to align Transformed Pattern to Target
                    // We want patBaseAngle + globalRotation = targetAngle
                    const globalRotation = targetAngle - patBaseAngle;
                    const cosG = Math.cos(globalRotation);
                    const sinG = Math.sin(globalRotation);

                    // Transform Function: Pattern Local -> Target World
                    const transformPoint = (px: number, py: number): Point => {
                        // 1. Symmetry Scale
                        const scaledX = px * trans.scaleX;
                        const scaledY = py * trans.scaleY;
                        // 2. Rotate to align with target
                        const rx = scaledX * cosG - scaledY * sinG;
                        const ry = scaledX * sinG + scaledY * cosG;
                        // 3. Translate to target start
                        return { x: rx + targetStart.x, y: ry + targetStart.y };
                    };

                    // --- VERIFICATION ---
                    // Project all pattern segments into world space and look for matches
                    const matchedIndices: number[] = [i];
                    let allMatched = true;

                    for (let k = 1; k < patternChain.length; k++) {
                        const pSeg = patternChain[k];
                        const patType = cycle.segments[k].type;
                        const patRad = cycle.segments[k].radius;

                        // Calculate Expected World Coordinates
                        const expectedP1 = transformPoint(pSeg.p1.x, pSeg.p1.y);
                        const expectedP2 = transformPoint(pSeg.p2.x, pSeg.p2.y);

                        // Find a target segment that connects P1->P2
                        let foundK = -1;

                        // Optimization: Check only segments starting near expectedP1
                        // This implies O(N^2) worst case but N is small per cycle.
                        // Can iterate all or use spatial hash if needed. Simple loop is fine for < 1000 segs.
                        for (let t = 0; t < targetSegments.length; t++) {
                            if (matchedIndices.includes(t) || coveredIndices.has(t)) continue;
                            const cand = targetSegments[t];

                            if (cand.type !== patType) continue;
                            if (patType === 'arc' && patRad && cand.radius && Math.abs(cand.radius - patRad) > TOL_LEN) continue;

                            // Check connectivity (Allow reverse)
                            const matchForward = isSamePoint(cand.p1, expectedP1) && isSamePoint(cand.p2, expectedP2);
                            const matchReverse = isSamePoint(cand.p2, expectedP1) && isSamePoint(cand.p1, expectedP2);

                            if (matchForward || matchReverse) {
                                // For arcs, verify center side if needed
                                // (If mirrored, 'Left' becomes 'Right')
                                if (patType === 'arc' && cycle.segments[k].arcCenterLeft !== undefined && cand.center) {
                                    const expectedLeft = cycle.segments[k].arcCenterLeft;
                                    // Flip expectation if scaled X * scaled Y is negative (determinant < 0 => chirality flip)
                                    const det = trans.scaleX * trans.scaleY;
                                    const finalExpectedLeft = det < 0 ? !expectedLeft : expectedLeft;

                                    // Actual check: P1->P2 vector vs Center
                                    // Note: If matched Reverse, vector is P2->P1.
                                    const start = matchReverse ? cand.p2 : cand.p1;
                                    const end = matchReverse ? cand.p1 : cand.p2;
                                    const actualLeft = isCenterLeft(start, end, cand.center);

                                    if (actualLeft !== finalExpectedLeft) continue;
                                }

                                foundK = t;
                                break;
                            }
                        }

                        if (foundK !== -1) {
                            matchedIndices.push(foundK);
                        } else {
                            allMatched = false;
                            break;
                        }
                    }

                    if (allMatched) {
                        debugLog(`Matched Cycle '${cycle.name}' Variant '${trans.name}'`);

                        // Collect Punches
                        const instancePunches: Omit<PlacedTool, 'id'>[] = [];
                        cycle.punches.forEach(p => {
                            const worldPos = transformPoint(p.relX, p.relY);

                            // Rotation:
                            // 1. Symmetry flip affects rotation direction.
                            //    If determinant < 0, rotation direction flips.
                            //    Angle A becomes -A.
                            //    Also, Mirror X (scaleX=-1) on 0 deg is 180 deg (flip).
                            //    Logic: Transform unit vector of punch rotation.
                            const punchCos = Math.cos(p.relRotation * Math.PI / 180);
                            const punchSin = Math.sin(p.relRotation * Math.PI / 180);

                            // Apply Scale
                            const scCos = punchCos * trans.scaleX;
                            const scSin = punchSin * trans.scaleY;

                            // Apply Global Rotation
                            const finalCos = scCos * cosG - scSin * sinG;
                            const finalSin = scCos * sinG + scSin * cosG;

                            const finalRotRad = Math.atan2(finalSin, finalCos);
                            let finalRotDeg = finalRotRad * 180 / Math.PI;

                            instancePunches.push({
                                toolId: p.toolId,
                                x: worldPos.x,
                                y: worldPos.y,
                                rotation: normalizeAngle(finalRotDeg)
                            });
                        });

                        // Add to results
                        const grouped = groupPunchesByTopology(instancePunches, matchedIndices.map(mi => targetSegments[mi]), cycle.name);
                        resultPunches.push(...grouped);

                        matchedIndices.forEach(mi => coveredIndices.add(mi));
                        break; // Stop checking transforms for this starting segment
                    }
                }
            }
        }
    });

    return { matches: resultPunches, coveredSegmentIndices: coveredIndices };
};

import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings, SheetStock, SheetUtilizationStrategy } from '../types';
import { generateId } from '../utils/helpers';
import { calculatePartPhysicalExtents } from './geometry';

// ----------------------------------------------------------------------
// TYPES & HELPERS
// ----------------------------------------------------------------------

interface PackerItem {
    uid: string;
    partId: string;
    width: number;
    height: number;
    offsetX: number; 
    offsetY: number;
    allowRotation: boolean;
    // Pre-calculated for 90deg rotation
    rotatedWidth: number;
    rotatedHeight: number;
    rotatedOffsetX: number;
    rotatedOffsetY: number;
}

interface NeighborRef {
    dim: number; // The length of the edge facing the free rect
}

interface FreeRect {
    x: number;
    y: number;
    w: number;
    h: number;
    // Context about what borders this free space
    neighborLeft?: NeighborRef;   // What part is immediately to the left?
    neighborBottom?: NeighborRef; // What part is immediately below?
}

type SplitStrategy = 'Vertical' | 'Horizontal' | 'ShortAxis' | 'LongAxis';

// ----------------------------------------------------------------------
// ROBUST GUILLOTINE PACKER CLASS
// ----------------------------------------------------------------------

class GuillotinePacker {
    width: number;
    height: number;
    spacingX: number;
    spacingY: number;
    useCommonLine: boolean;
    freeRects: FreeRect[];
    placedItems: { item: PackerItem, x: number, y: number, rotation: number }[];
    strategy: SplitStrategy;

    constructor(
        width: number, 
        height: number, 
        spacingX: number, 
        spacingY: number, 
        strategy: SplitStrategy = 'ShortAxis',
        useCommonLine: boolean = false
    ) {
        this.width = width;
        this.height = height;
        this.spacingX = spacingX;
        this.spacingY = spacingY;
        this.useCommonLine = useCommonLine;
        this.freeRects = [{ x: 0, y: 0, w: width, h: height }];
        this.placedItems = [];
        this.strategy = strategy;
    }

    // Helper to calculate required spacing based on neighbor match
    getDynamicSpacing(itemDim: number, neighbor?: NeighborRef, axisSpacing?: number): number {
        const defaultSpacing = axisSpacing || 0;

        if (this.useCommonLine && neighbor) {
            // Check if dimensions match (with small tolerance for float errors)
            if (Math.abs(itemDim - neighbor.dim) < 0.1) {
                return -5; // Common Line overlap (fixed for now, could be dynamic)
            }
        }
        return defaultSpacing;
    }

    // Heuristic: Best Area Fit (BAF)
    findPosition(item: PackerItem): { rectIndex: number, rotation: number, score: number, appliedSpacingX: number, appliedSpacingY: number } | null {
        let bestScore = Infinity;
        let bestRectIndex = -1;
        let bestRotation = 0; // 0 or 90
        let bestSpacingX = this.spacingX;
        let bestSpacingY = this.spacingY;

        for (let i = 0; i < this.freeRects.length; i++) {
            const rect = this.freeRects[i];

            // --- Strategy Position Penalty ---
            // Small bias to pick top-left or bottom-left depending on strategy to break ties
            let positionPenalty = 0;
            if (this.strategy === 'Vertical') {
                positionPenalty = (rect.x * 10 + rect.y) * 0.0001; 
            } else if (this.strategy === 'Horizontal') {
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            } else {
                // Generic reading order bias
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            }

            // --- Try 0 degrees ---
            {
                // Determine spacing based on neighbors
                const sX = this.getDynamicSpacing(item.height, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.width, rect.neighborBottom, this.spacingY);

                // Effective used space in the rect. 
                // If spacing is negative (common line), we consume LESS of the rect's width/height relative to its start.
                // The rect starts at (NeighborEnd + Gap). 
                // With negative spacing, we start at (NeighborEnd - Overlap).
                // But FreeRect.x is mathematically aligned to (NeighborEnd + Gap).
                // So if we place at (FreeRect.x - 5), we technically step outside the FreeRect to the left?
                // NO. In Guillotine packing logic, 'neighborLeft' implies the boundary.
                // Simpler model: FreeRect describes AVAILABLE space. 
                // If common line is used, we assume the FreeRect actually starts earlier or we just consume less.
                // For simplicity here: common line reduces the *effective dimension* needed from the *nominal* gap-inclusive free rect.

                const effectiveUsedW = Math.max(0, item.width + sX);
                const effectiveUsedH = Math.max(0, item.height + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);

                    // Score: Minimize leftover (Best Short Side Fit)
                    const fitScore = Math.min(leftoverX, leftoverY); 

                    // Common Line Bonus: Prefer placements that use common line
                    const commonLineBonus = (sX < 0 || sY < 0) ? 5000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 0;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }

            // --- Try 90 degrees ---
            if (item.allowRotation) {
                const sX = this.getDynamicSpacing(item.rotatedHeight, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.rotatedWidth, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.rotatedWidth + sX);
                const effectiveUsedH = Math.max(0, item.rotatedHeight + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);
                    const fitScore = Math.min(leftoverX, leftoverY);

                    const commonLineBonus = (sX < 0 || sY < 0) ? 5000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 90;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }
        }

        if (bestRectIndex !== -1) {
            return { 
                rectIndex: bestRectIndex, 
                rotation: bestRotation, 
                score: bestScore,
                appliedSpacingX: bestSpacingX,
                appliedSpacingY: bestSpacingY
            };
        }
        return null;
    }

    placeItem(item: PackerItem, rectIndex: number, rotation: number, spacingX: number, spacingY: number) {
        const rect = this.freeRects[rectIndex];
        const w = rotation === 90 ? item.rotatedWidth : item.width;
        const h = rotation === 90 ? item.rotatedHeight : item.height;

        // Calculate placement coordinates
        // rect.x includes the standard spacing from previous split. 
        // If common line is active (spacing < 0), we shift back.
        // NOTE: Standard logic assumes rect.x is "clear". 
        // If sX < 0, we overlap the left boundary.
        // This relies on the previous neighbor having enough space (which it does, it's the part itself).

        const actualSpacingX = rect.x === 0 ? 0 : spacingX;
        const actualSpacingY = rect.y === 0 ? 0 : spacingY;

        const placedX = rect.x + actualSpacingX;
        const placedY = rect.y + actualSpacingY;

        this.placedItems.push({
            item,
            x: placedX,
            y: placedY,
            rotation
        });

        // "Used" dimensions for splitting
        const usedW = w + actualSpacingX;
        const usedH = h + actualSpacingY;

        // Determine Split Method
        const freeW = rect.w - usedW;
        const freeH = rect.h - usedH;

        let splitHorizontal = false;

        if (this.strategy === 'Horizontal') {
            splitHorizontal = true;
        } else if (this.strategy === 'Vertical') {
            splitHorizontal = false;
        } else if (this.strategy === 'ShortAxis') {
            splitHorizontal = freeW < freeH;
        } else {
            // LongAxis
            splitHorizontal = freeW > freeH;
        }

        // Remove the used rectangle
        this.freeRects.splice(rectIndex, 1);

        // GUILLOTINE SPLIT LOGIC
        let newRectTop: FreeRect | null = null;
        let newRectRight: FreeRect | null = null;

        // Logic coordinate bases relative to original rect
        const splitX = rect.x + usedW;
        const splitY = rect.y + usedH;

        if (splitHorizontal) {
            // --- HORIZONTAL SPLIT (Cut along X axis) ---
            // Top Rect: Full Width of original.
            // Right Rect: Height limited to item height.

            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: rect.w, 
                    h: freeH,
                    neighborBottom: { dim: w }, // New neighbor below is the item's top edge
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: Math.min(usedH, rect.h), // Bounded by item height
                    neighborLeft: { dim: h }, // New neighbor to left is item's right edge
                    neighborBottom: rect.neighborBottom 
                };
            }
        } else {
            // --- VERTICAL SPLIT (Cut along Y axis) ---
            // Top Rect: Width limited to item width.
            // Right Rect: Full Height of original.

            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: Math.min(usedW, rect.w), 
                    h: freeH,
                    neighborBottom: { dim: w },
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: rect.h,
                    neighborLeft: { dim: h },
                    neighborBottom: rect.neighborBottom
                };
            }
        }

        if (newRectTop && newRectTop.w > 0 && newRectTop.h > 0) this.freeRects.push(newRectTop);
        if (newRectRight && newRectRight.w > 0 && newRectRight.h > 0) this.freeRects.push(newRectRight);

        // Pruning tiny rectangles (waste)
        this.freeRects = this.freeRects.filter(r => r.w >= 1 && r.h >= 1);
    }
}

// ----------------------------------------------------------------------
// GENERATOR
// ----------------------------------------------------------------------

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestResultSheet[]> {

    // 1. Prepare Items
    const rawItems: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const dims0 = calculatePartPhysicalExtents(part, tools);
        const maxY0 = dims0.height - dims0.offsetY; 

        for (let i = 0; i < sp.quantity; i++) {
            rawItems.push({
                uid: generateId(),
                partId: sp.partId,
                width: dims0.width,
                height: dims0.height,
                offsetX: dims0.offsetX,
                offsetY: dims0.offsetY,
                allowRotation: sp.nesting.allow90_270,
                rotatedWidth: dims0.height,
                rotatedHeight: dims0.width,
                rotatedOffsetX: maxY0,
                rotatedOffsetY: dims0.offsetX
            });
        }
    }

    const completedSheets: NestResultSheet[] = [];
    const { 
        sheetMarginTop, sheetMarginBottom, sheetMarginLeft, sheetMarginRight, 
        partSpacingX, partSpacingY, useCommonLine
    } = settings;

    // Helper to calculate packing efficiency
    const calculateEfficiency = (packer: GuillotinePacker, totalArea: number) => {
        const usedArea = packer.placedItems.reduce((sum, p) => {
            const w = p.rotation === 90 ? p.item.rotatedWidth : p.item.width;
            const h = p.rotation === 90 ? p.item.rotatedHeight : p.item.height;
            return sum + (w * h);
        }, 0);
        return usedArea / totalArea;
    };

    let remainingItems = [...rawItems];

    // 2. Packing Loop
    while (remainingItems.length > 0) {

        // Get Active Sheet
        let activeStock: SheetStock | undefined;
        if (settings.activeSheetId) {
            activeStock = settings.availableSheets.find(s => s.id === settings.activeSheetId);
        }
        if (!activeStock && settings.availableSheets.length > 0) activeStock = settings.availableSheets[0];
        if (!activeStock) break; 

        const packW = activeStock.width - sheetMarginLeft - sheetMarginRight;
        const packH = activeStock.height - sheetMarginTop - sheetMarginBottom;

        // --- MULTI-PASS SIMULATION ---
        const strategies: { name: string, packer: GuillotinePacker, packedIndices: Set<number>, score: number }[] = [];

        // Expanded configurations to ensure finding the best fit and fill gaps
        const configs = [
            { id: 'BestFit-Short', sort: 'area', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'BestFit-Long', sort: 'area', strategy: 'LongAxis' as SplitStrategy },
            { id: 'MaxSide-Short', sort: 'max_side', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'MaxSide-Long', sort: 'max_side', strategy: 'LongAxis' as SplitStrategy },
            { id: 'Width-Short', sort: 'width', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'Vertical-Strip', sort: 'max_side', strategy: 'Vertical' as SplitStrategy },
            { id: 'Horizontal-Strip', sort: 'max_side', strategy: 'Horizontal' as SplitStrategy },
        ];

        for (const config of configs) {
            const currentItems = [...remainingItems];

            // Apply sorting
            currentItems.sort((a, b) => {
                if (config.sort === 'width') {
                    // Sort by width descending
                    return b.width - a.width;
                } else if (config.sort === 'max_side') {
                    // Sort by maximum dimension descending
                    return Math.max(b.width, b.height) - Math.max(a.width, a.height);
                } else {
                    // Default 'area' descending
                    return (b.width * b.height) - (a.width * a.height);
                }
            });

            const packer = new GuillotinePacker(packW, packH, partSpacingX, partSpacingY, config.strategy, useCommonLine);
            const packedUids = new Set<string>();

            // Try to place every item in the list
            // This loop naturally tries to fill gaps with smaller items if big ones don't fit
            for (const item of currentItems) {
                const bestPos = packer.findPosition(item);
                if (bestPos) {
                    packer.placeItem(item, bestPos.rectIndex, bestPos.rotation, bestPos.appliedSpacingX, bestPos.appliedSpacingY);
                    packedUids.add(item.uid);
                }
            }

            const efficiency = calculateEfficiency(packer, packW * packH);
            const count = packedUids.size;

            // Score prioritizes Count first, then Efficiency
            const score = count * 1000 + efficiency * 100;

            const originalIndices = new Set<number>();
            remainingItems.forEach((item, idx) => {
                if (packedUids.has(item.uid)) originalIndices.add(idx);
            });

            strategies.push({ name: config.id, packer, packedIndices: originalIndices, score });
        }

        // --- PICK WINNER ---
        strategies.sort((a, b) => b.score - a.score);
        const winner = strategies[0];

        if (winner.packedIndices.size === 0) {
            console.warn("Item too big for sheet:", remainingItems[0]);
            remainingItems.shift(); 
            continue;
        }

        remainingItems = remainingItems.filter((_, i) => !winner.packedIndices.has(i));

        // Create Result Sheet from Winner
        const packer = winner.packer;

        // Auto-Calc Width Logic
        let finalSheetWidth = activeStock.width;
        let maxPlacedX = 0;
        packer.placedItems.forEach(p => {
            const w = (p.rotation === 90) ? p.item.rotatedWidth : p.item.width;
            if (p.x + w > maxPlacedX) maxPlacedX = p.x + w;
        });

        const isAutoCalc = settings.utilizationStrategy === SheetUtilizationStrategy.AutoCalculation;
        if (isAutoCalc) {
            const requiredPhys = sheetMarginLeft + maxPlacedX + sheetMarginRight;
            finalSheetWidth = Math.ceil(requiredPhys / 100) * 100;
            if (finalSheetWidth > 2560) finalSheetWidth = 2560;
        }

        const usedAreaPx = packer.placedItems.reduce((sum, p) => {
             const w = p.rotation === 90 ? p.item.rotatedWidth : p.item.width;
             const h = p.rotation === 90 ? p.item.rotatedHeight : p.item.height;
             return sum + (w * h);
        }, 0);
        const totalAreaPx = finalSheetWidth * activeStock.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: isAutoCalc ? `Auto ${finalSheetWidth}x${activeStock.height} (${winner.name})` : `Sheet ${completedSheets.length + 1}`,
            stockSheetId: activeStock.id,
            width: finalSheetWidth,
            height: activeStock.height,
            material: activeStock.material,
            thickness: activeStock.thickness,
            placedParts: packer.placedItems.map(p => {
                const ox = (p.rotation === 90) ? p.item.rotatedOffsetX : p.item.offsetX;
                const oy = (p.rotation === 90) ? p.item.rotatedOffsetY : p.item.offsetY;

                return {
                    id: generateId(),
                    partId: p.item.partId,
                    x: p.x + sheetMarginLeft + ox,
                    y: p.y + sheetMarginBottom + oy,
                    rotation: p.rotation
                };
            }),
            usedArea: totalAreaPx > 0 ? (usedAreaPx / totalAreaPx) * 100 : 0,
            scrapPercentage: totalAreaPx > 0 ? 100 - ((usedAreaPx / totalAreaPx) * 100) : 100,
            partCount: packer.placedItems.length,
            quantity: 1
        };

        completedSheets.push(resultSheet);

        await new Promise(resolve => setTimeout(resolve, 5));
        yield [...completedSheets];
    }
}

import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings, SheetStock, SheetUtilizationStrategy } from '../types';
import { generateId } from '../utils/helpers';
import { calculatePartPhysicalExtents } from './geometry';

// ----------------------------------------------------------------------
// TYPES & HELPERS
// ----------------------------------------------------------------------

interface PackerItem {
    uid: string;
    partId: string;
    width: number;
    height: number;
    offsetX: number; 
    offsetY: number;
    allowRotation: boolean;
    // Pre-calculated for 90deg rotation
    rotatedWidth: number;
    rotatedHeight: number;
    rotatedOffsetX: number;
    rotatedOffsetY: number;
    area: number; // Optimization helper
}

interface NeighborRef {
    dim: number; // The length of the edge facing the free rect
}

interface FreeRect {
    x: number;
    y: number;
    w: number;
    h: number;
    // Context about what borders this free space
    neighborLeft?: NeighborRef;   // What part is immediately to the left?
    neighborBottom?: NeighborRef; // What part is immediately below?
}

type SplitStrategy = 'Vertical' | 'Horizontal' | 'ShortAxis' | 'LongAxis';

// ----------------------------------------------------------------------
// ROBUST GUILLOTINE PACKER CLASS
// ----------------------------------------------------------------------

class GuillotinePacker {
    width: number;
    height: number;
    spacingX: number;
    spacingY: number;
    useCommonLine: boolean;
    freeRects: FreeRect[];
    placedItems: { item: PackerItem, x: number, y: number, rotation: number }[];
    strategy: SplitStrategy;

    constructor(
        width: number, 
        height: number, 
        spacingX: number, 
        spacingY: number, 
        strategy: SplitStrategy = 'ShortAxis',
        useCommonLine: boolean = false
    ) {
        this.width = width;
        this.height = height;
        this.spacingX = spacingX;
        this.spacingY = spacingY;
        this.useCommonLine = useCommonLine;
        this.freeRects = [{ x: 0, y: 0, w: width, h: height }];
        this.placedItems = [];
        this.strategy = strategy;
    }

    // Creates a deep copy of the packer for simulation
    clone(): GuillotinePacker {
        const p = new GuillotinePacker(this.width, this.height, this.spacingX, this.spacingY, this.strategy, this.useCommonLine);
        // Deep copy freeRects
        p.freeRects = JSON.parse(JSON.stringify(this.freeRects));
        // Shallow copy placed items (items themselves are immutable refs)
        p.placedItems = [...this.placedItems];
        return p;
    }

    // Helper to calculate required spacing based on neighbor match
    getDynamicSpacing(itemDim: number, neighbor?: NeighborRef, axisSpacing?: number): number {
        const defaultSpacing = axisSpacing || 0;

        if (this.useCommonLine && neighbor) {
            // Check if dimensions match (with small tolerance for float errors)
            if (Math.abs(itemDim - neighbor.dim) < 0.1) {
                return -5; // Common Line overlap (fixed for now, could be dynamic)
            }
        }
        return defaultSpacing;
    }

    // Heuristic: Best Area Fit (BAF)
    findPosition(item: PackerItem): { rectIndex: number, rotation: number, score: number, appliedSpacingX: number, appliedSpacingY: number } | null {
        let bestScore = Infinity;
        let bestRectIndex = -1;
        let bestRotation = 0; // 0 or 90
        let bestSpacingX = this.spacingX;
        let bestSpacingY = this.spacingY;

        for (let i = 0; i < this.freeRects.length; i++) {
            const rect = this.freeRects[i];

            // --- Strategy Position Penalty ---
            // Small bias to pick top-left or bottom-left depending on strategy to break ties
            let positionPenalty = 0;
            if (this.strategy === 'Vertical') {
                positionPenalty = (rect.x * 10 + rect.y) * 0.0001; 
            } else if (this.strategy === 'Horizontal') {
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            } else {
                // Generic reading order bias
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            }

            // --- Try 0 degrees ---
            {
                // Determine spacing based on neighbors
                const sX = this.getDynamicSpacing(item.height, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.width, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.width + sX);
                const effectiveUsedH = Math.max(0, item.height + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);

                    // Score: Minimize leftover (Best Short Side Fit)
                    const fitScore = Math.min(leftoverX, leftoverY); 

                    // Common Line Bonus: Prefer placements that use common line
                    const commonLineBonus = (sX < 0 || sY < 0) ? 5000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 0;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }

            // --- Try 90 degrees ---
            if (item.allowRotation) {
                const sX = this.getDynamicSpacing(item.rotatedHeight, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.rotatedWidth, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.rotatedWidth + sX);
                const effectiveUsedH = Math.max(0, item.rotatedHeight + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);
                    const fitScore = Math.min(leftoverX, leftoverY);

                    const commonLineBonus = (sX < 0 || sY < 0) ? 5000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 90;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }
        }

        if (bestRectIndex !== -1) {
            return { 
                rectIndex: bestRectIndex, 
                rotation: bestRotation, 
                score: bestScore,
                appliedSpacingX: bestSpacingX,
                appliedSpacingY: bestSpacingY
            };
        }
        return null;
    }

    placeItem(item: PackerItem, rectIndex: number, rotation: number, spacingX: number, spacingY: number) {
        const rect = this.freeRects[rectIndex];
        const w = rotation === 90 ? item.rotatedWidth : item.width;
        const h = rotation === 90 ? item.rotatedHeight : item.height;

        const actualSpacingX = rect.x === 0 ? 0 : spacingX;
        const actualSpacingY = rect.y === 0 ? 0 : spacingY;

        const placedX = rect.x + actualSpacingX;
        const placedY = rect.y + actualSpacingY;

        this.placedItems.push({
            item,
            x: placedX,
            y: placedY,
            rotation
        });

        const usedW = w + actualSpacingX;
        const usedH = h + actualSpacingY;

        const freeW = rect.w - usedW;
        const freeH = rect.h - usedH;

        let splitHorizontal = false;

        if (this.strategy === 'Horizontal') {
            splitHorizontal = true;
        } else if (this.strategy === 'Vertical') {
            splitHorizontal = false;
        } else if (this.strategy === 'ShortAxis') {
            splitHorizontal = freeW < freeH;
        } else {
            // LongAxis
            splitHorizontal = freeW > freeH;
        }

        this.freeRects.splice(rectIndex, 1);

        let newRectTop: FreeRect | null = null;
        let newRectRight: FreeRect | null = null;

        const splitX = rect.x + usedW;
        const splitY = rect.y + usedH;

        if (splitHorizontal) {
            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: rect.w, 
                    h: freeH,
                    neighborBottom: { dim: w },
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: Math.min(usedH, rect.h),
                    neighborLeft: { dim: h },
                    neighborBottom: rect.neighborBottom 
                };
            }
        } else {
            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: Math.min(usedW, rect.w), 
                    h: freeH,
                    neighborBottom: { dim: w },
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: rect.h,
                    neighborLeft: { dim: h },
                    neighborBottom: rect.neighborBottom
                };
            }
        }

        if (newRectTop && newRectTop.w > 0 && newRectTop.h > 0) this.freeRects.push(newRectTop);
        if (newRectRight && newRectRight.w > 0 && newRectRight.h > 0) this.freeRects.push(newRectRight);

        // Pruning tiny rectangles (waste)
        this.freeRects = this.freeRects.filter(r => r.w >= 1 && r.h >= 1);
    }
}

// ----------------------------------------------------------------------
// GENERATOR
// ----------------------------------------------------------------------

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestResultSheet[]> {

    // 1. Prepare Items
    const rawItems: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const dims0 = calculatePartPhysicalExtents(part, tools);
        const maxY0 = dims0.height - dims0.offsetY; 

        for (let i = 0; i < sp.quantity; i++) {
            rawItems.push({
                uid: generateId(),
                partId: sp.partId,
                width: dims0.width,
                height: dims0.height,
                offsetX: dims0.offsetX,
                offsetY: dims0.offsetY,
                allowRotation: sp.nesting.allow90_270,
                rotatedWidth: dims0.height,
                rotatedHeight: dims0.width,
                rotatedOffsetX: maxY0,
                rotatedOffsetY: dims0.offsetX,
                area: dims0.width * dims0.height
            });
        }
    }

    const completedSheets: NestResultSheet[] = [];
    const { 
        sheetMarginTop, sheetMarginBottom, sheetMarginLeft, sheetMarginRight, 
        partSpacingX, partSpacingY, useCommonLine
    } = settings;

    const calculateEfficiency = (packer: GuillotinePacker, totalArea: number) => {
        const usedArea = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        return usedArea / totalArea;
    };

    let remainingItems = [...rawItems];

    // 2. Packing Loop
    while (remainingItems.length > 0) {

        let activeStock: SheetStock | undefined;
        if (settings.activeSheetId) {
            activeStock = settings.availableSheets.find(s => s.id === settings.activeSheetId);
        }
        if (!activeStock && settings.availableSheets.length > 0) activeStock = settings.availableSheets[0];
        if (!activeStock) break; 

        const packW = activeStock.width - sheetMarginLeft - sheetMarginRight;
        const packH = activeStock.height - sheetMarginTop - sheetMarginBottom;

        // --- MULTI-PASS SIMULATION ---
        const strategies: { name: string, packer: GuillotinePacker, packedIndices: Set<number>, score: number }[] = [];

        const configs = [
            { id: 'Chess-Lookahead', sort: 'max_side', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'BestFit-Short', sort: 'area', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'BestFit-Long', sort: 'area', strategy: 'LongAxis' as SplitStrategy },
            { id: 'MaxSide-Short', sort: 'max_side', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'MaxSide-Long', sort: 'max_side', strategy: 'LongAxis' as SplitStrategy },
            { id: 'Width-Short', sort: 'width', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'Vertical-Strip', sort: 'max_side', strategy: 'Vertical' as SplitStrategy },
            { id: 'Horizontal-Strip', sort: 'max_side', strategy: 'Horizontal' as SplitStrategy },
        ];

        for (const config of configs) {
            const currentItems = [...remainingItems];

            // Initial Sort
            currentItems.sort((a, b) => {
                if (config.sort === 'width') return b.width - a.width;
                if (config.sort === 'max_side') return Math.max(b.width, b.height) - Math.max(a.width, a.height);
                return b.area - a.area;
            });

            const packer = new GuillotinePacker(packW, packH, partSpacingX, partSpacingY, config.strategy, useCommonLine);
            const packedUids = new Set<string>();

            if (config.id === 'Chess-Lookahead') {
                // --- CHESS STRATEGY: Look ahead N steps to pick the best part ---
                // Instead of purely greedy linear iteration, we simulate choices.

                let candidatePool = [...currentItems];
                const LOOKAHEAD_WIDTH = 5; // Look at top 5 largest parts
                const LOOKAHEAD_SIM_LIMIT = 5; // How many subsequent parts to simulate placement for

                while (candidatePool.length > 0) {
                    // 1. Identify candidates (Top N unplaced parts)
                    // We only look at the start of the sorted list to save time, 
                    // assuming sorting already prioritizes 'hard' parts.
                    const candidates = candidatePool.slice(0, LOOKAHEAD_WIDTH);

                    let bestCandidateIdx = -1;
                    let bestSimScore = -1;
                    let bestCandidatePos = null;

                    // 2. Simulate each candidate
                    for (let c = 0; c < candidates.length; c++) {
                        const candidate = candidates[c];
                        const simPacker = packer.clone(); // Clone state

                        // Try place candidate
                        const pos = simPacker.findPosition(candidate);
                        if (pos) {
                            simPacker.placeItem(candidate, pos.rectIndex, pos.rotation, pos.appliedSpacingX, pos.appliedSpacingY);

                            // 3. Fast Forward Simulation: Greedily place subsequent parts
                            let simScore = candidate.area; 
                            let filledCount = 0;

                            // Simulate placing the REST of the pool (limited depth)
                            const simulationPool = candidatePool.filter((_, idx) => idx !== c);

                            for (const simItem of simulationPool) {
                                if (filledCount >= LOOKAHEAD_SIM_LIMIT) break;
                                const simPos = simPacker.findPosition(simItem);
                                if (simPos) {
                                    simPacker.placeItem(simItem, simPos.rectIndex, simPos.rotation, simPos.appliedSpacingX, simPos.appliedSpacingY);
                                    simScore += simItem.area;
                                    filledCount++;
                                }
                            }

                            // Bonus for packing density in the candidate's immediate rect
                            // This encourages tight fits
                            // (Simplification: Area Score is dominant)

                            if (simScore > bestSimScore) {
                                bestSimScore = simScore;
                                bestCandidateIdx = c;
                                bestCandidatePos = pos;
                            }
                        }
                    }

                    // 4. Commit best move
                    if (bestCandidateIdx !== -1 && bestCandidatePos) {
                        const chosen = candidates[bestCandidateIdx];
                        packer.placeItem(chosen, bestCandidatePos.rectIndex, bestCandidatePos.rotation, bestCandidatePos.appliedSpacingX, bestCandidatePos.appliedSpacingY);
                        packedUids.add(chosen.uid);
                        // Remove chosen from pool
                        candidatePool.splice(bestCandidateIdx, 1);
                    } else {
                        // If no candidate fits, remove the first one to advance (it might fit later or on next sheet)
                        // But actually, if top N don't fit, probably none fit easily. 
                        // Just try next in list linearly to be safe.
                        const fallbackIdx = candidatePool.findIndex(itm => {
                            const p = packer.findPosition(itm);
                            if (p) {
                                packer.placeItem(itm, p.rectIndex, p.rotation, p.appliedSpacingX, p.appliedSpacingY);
                                packedUids.add(itm.uid);
                                return true;
                            }
                            return false;
                        });

                        if (fallbackIdx !== -1) {
                            candidatePool.splice(fallbackIdx, 1);
                        } else {
                            // Nothing fits anymore
                            break;
                        }
                    }
                }

            } else {
                // --- STANDARD STRATEGY ---
                for (const item of currentItems) {
                    const bestPos = packer.findPosition(item);
                    if (bestPos) {
                        packer.placeItem(item, bestPos.rectIndex, bestPos.rotation, bestPos.appliedSpacingX, bestPos.appliedSpacingY);
                        packedUids.add(item.uid);
                    }
                }
            }

            const efficiency = calculateEfficiency(packer, packW * packH);
            const count = packedUids.size;

            // Score
            const score = count * 1000 + efficiency * 100;

            const originalIndices = new Set<number>();
            remainingItems.forEach((item, idx) => {
                if (packedUids.has(item.uid)) originalIndices.add(idx);
            });

            strategies.push({ name: config.id, packer, packedIndices: originalIndices, score });
        }

        // --- PICK WINNER ---
        strategies.sort((a, b) => b.score - a.score);
        const winner = strategies[0];

        if (winner.packedIndices.size === 0) {
            console.warn("Item too big for sheet:", remainingItems[0]);
            remainingItems.shift(); 
            continue;
        }

        remainingItems = remainingItems.filter((_, i) => !winner.packedIndices.has(i));

        const packer = winner.packer;

        // Auto-Calc Width Logic
        let finalSheetWidth = activeStock.width;
        let maxPlacedX = 0;
        packer.placedItems.forEach(p => {
            const w = (p.rotation === 90) ? p.item.rotatedWidth : p.item.width;
            if (p.x + w > maxPlacedX) maxPlacedX = p.x + w;
        });

        const isAutoCalc = settings.utilizationStrategy === SheetUtilizationStrategy.AutoCalculation;
        if (isAutoCalc) {
            const requiredPhys = sheetMarginLeft + maxPlacedX + sheetMarginRight;
            finalSheetWidth = Math.ceil(requiredPhys / 100) * 100;
            if (finalSheetWidth > 2560) finalSheetWidth = 2560;
        }

        const usedAreaPx = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        const totalAreaPx = finalSheetWidth * activeStock.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: isAutoCalc ? `Auto ${finalSheetWidth}x${activeStock.height} (${winner.name})` : `Sheet ${completedSheets.length + 1}`,
            stockSheetId: activeStock.id,
            width: finalSheetWidth,
            height: activeStock.height,
            material: activeStock.material,
            thickness: activeStock.thickness,
            placedParts: packer.placedItems.map(p => {
                const ox = (p.rotation === 90) ? p.item.rotatedOffsetX : p.item.offsetX;
                const oy = (p.rotation === 90) ? p.item.rotatedOffsetY : p.item.offsetY;

                return {
                    id: generateId(),
                    partId: p.item.partId,
                    x: p.x + sheetMarginLeft + ox,
                    y: p.y + sheetMarginBottom + oy,
                    rotation: p.rotation
                };
            }),
            usedArea: totalAreaPx > 0 ? (usedAreaPx / totalAreaPx) * 100 : 0,
            scrapPercentage: totalAreaPx > 0 ? 100 - ((usedAreaPx / totalAreaPx) * 100) : 100,
            partCount: packer.placedItems.length,
            quantity: 1
        };

        completedSheets.push(resultSheet);

        await new Promise(resolve => setTimeout(resolve, 5));
        yield [...completedSheets];
    }
}

import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings, SheetStock, SheetUtilizationStrategy } from '../types';
import { generateId } from '../utils/helpers';
import { calculatePartPhysicalExtents } from './geometry';

// ----------------------------------------------------------------------
// TYPES & HELPERS
// ----------------------------------------------------------------------

interface PackerItem {
    uid: string;
    partId: string;
    width: number;
    height: number;
    offsetX: number; 
    offsetY: number;
    allowRotation: boolean;
    // Pre-calculated for 90deg rotation
    rotatedWidth: number;
    rotatedHeight: number;
    rotatedOffsetX: number;
    rotatedOffsetY: number;
    area: number; // Optimization helper
}

interface NeighborRef {
    dim: number; // The length of the edge facing the free rect
}

interface FreeRect {
    x: number;
    y: number;
    w: number;
    h: number;
    // Context about what borders this free space
    neighborLeft?: NeighborRef;   // What part is immediately to the left?
    neighborBottom?: NeighborRef; // What part is immediately below?
}

type SplitStrategy = 'Vertical' | 'Horizontal' | 'ShortAxis' | 'LongAxis';

// ----------------------------------------------------------------------
// ROBUST GUILLOTINE PACKER CLASS
// ----------------------------------------------------------------------

class GuillotinePacker {
    width: number;
    height: number;
    spacingX: number;
    spacingY: number;
    useCommonLine: boolean;
    freeRects: FreeRect[];
    placedItems: { item: PackerItem, x: number, y: number, rotation: number }[];
    strategy: SplitStrategy;

    constructor(
        width: number, 
        height: number, 
        spacingX: number, 
        spacingY: number, 
        strategy: SplitStrategy = 'ShortAxis',
        useCommonLine: boolean = false
    ) {
        this.width = width;
        this.height = height;
        this.spacingX = spacingX;
        this.spacingY = spacingY;
        this.useCommonLine = useCommonLine;
        this.freeRects = [{ x: 0, y: 0, w: width, h: height }];
        this.placedItems = [];
        this.strategy = strategy;
    }

    // Creates a deep copy of the packer for simulation
    clone(): GuillotinePacker {
        const p = new GuillotinePacker(this.width, this.height, this.spacingX, this.spacingY, this.strategy, this.useCommonLine);
        // Deep copy freeRects
        p.freeRects = JSON.parse(JSON.stringify(this.freeRects));
        // Shallow copy placed items (items themselves are immutable refs)
        p.placedItems = [...this.placedItems];
        return p;
    }

    // Helper to calculate required spacing based on neighbor match
    getDynamicSpacing(itemDim: number, neighbor?: NeighborRef, axisSpacing?: number): number {
        const defaultSpacing = axisSpacing || 0;

        if (this.useCommonLine && neighbor) {
            // Check if dimensions match (with small tolerance for float errors)
            if (Math.abs(itemDim - neighbor.dim) < 0.1) {
                return -5; // Common Line overlap (fixed for now, could be dynamic)
            }
        }
        return defaultSpacing;
    }

    // Heuristic: Best Area Fit (BAF)
    findPosition(item: PackerItem): { rectIndex: number, rotation: number, score: number, appliedSpacingX: number, appliedSpacingY: number } | null {
        let bestScore = Infinity;
        let bestRectIndex = -1;
        let bestRotation = 0; // 0 or 90
        let bestSpacingX = this.spacingX;
        let bestSpacingY = this.spacingY;

        for (let i = 0; i < this.freeRects.length; i++) {
            const rect = this.freeRects[i];

            // --- Strategy Position Penalty ---
            // Small bias to pick top-left or bottom-left depending on strategy to break ties
            let positionPenalty = 0;
            if (this.strategy === 'Vertical') {
                positionPenalty = (rect.x * 10 + rect.y) * 0.0001; 
            } else if (this.strategy === 'Horizontal') {
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            } else {
                // Generic reading order bias
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            }

            // --- Try 0 degrees ---
            {
                // Determine spacing based on neighbors
                const sX = this.getDynamicSpacing(item.height, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.width, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.width + sX);
                const effectiveUsedH = Math.max(0, item.height + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);

                    // Score: Minimize leftover (Best Short Side Fit)
                    const fitScore = Math.min(leftoverX, leftoverY); 

                    // Common Line Bonus: Prefer placements that use common line
                    const commonLineBonus = (sX < 0 || sY < 0) ? 5000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 0;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }

            // --- Try 90 degrees ---
            if (item.allowRotation) {
                const sX = this.getDynamicSpacing(item.rotatedHeight, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.rotatedWidth, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.rotatedWidth + sX);
                const effectiveUsedH = Math.max(0, item.rotatedHeight + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);
                    const fitScore = Math.min(leftoverX, leftoverY);

                    const commonLineBonus = (sX < 0 || sY < 0) ? 5000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 90;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }
        }

        if (bestRectIndex !== -1) {
            return { 
                rectIndex: bestRectIndex, 
                rotation: bestRotation, 
                score: bestScore,
                appliedSpacingX: bestSpacingX,
                appliedSpacingY: bestSpacingY
            };
        }
        return null;
    }

    placeItem(item: PackerItem, rectIndex: number, rotation: number, spacingX: number, spacingY: number) {
        const rect = this.freeRects[rectIndex];
        const w = rotation === 90 ? item.rotatedWidth : item.width;
        const h = rotation === 90 ? item.rotatedHeight : item.height;

        const actualSpacingX = rect.x === 0 ? 0 : spacingX;
        const actualSpacingY = rect.y === 0 ? 0 : spacingY;

        const placedX = rect.x + actualSpacingX;
        const placedY = rect.y + actualSpacingY;

        this.placedItems.push({
            item,
            x: placedX,
            y: placedY,
            rotation
        });

        const usedW = w + actualSpacingX;
        const usedH = h + actualSpacingY;

        const freeW = rect.w - usedW;
        const freeH = rect.h - usedH;

        let splitHorizontal = false;

        if (this.strategy === 'Horizontal') {
            splitHorizontal = true;
        } else if (this.strategy === 'Vertical') {
            splitHorizontal = false;
        } else if (this.strategy === 'ShortAxis') {
            splitHorizontal = freeW < freeH;
        } else {
            // LongAxis
            splitHorizontal = freeW > freeH;
        }

        this.freeRects.splice(rectIndex, 1);

        let newRectTop: FreeRect | null = null;
        let newRectRight: FreeRect | null = null;

        const splitX = rect.x + usedW;
        const splitY = rect.y + usedH;

        if (splitHorizontal) {
            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: rect.w, 
                    h: freeH,
                    neighborBottom: { dim: w },
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: Math.min(usedH, rect.h),
                    neighborLeft: { dim: h },
                    neighborBottom: rect.neighborBottom 
                };
            }
        } else {
            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: Math.min(usedW, rect.w), 
                    h: freeH,
                    neighborBottom: { dim: w },
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: rect.h,
                    neighborLeft: { dim: h },
                    neighborBottom: rect.neighborBottom
                };
            }
        }

        if (newRectTop && newRectTop.w > 0 && newRectTop.h > 0) this.freeRects.push(newRectTop);
        if (newRectRight && newRectRight.w > 0 && newRectRight.h > 0) this.freeRects.push(newRectRight);

        // Pruning tiny rectangles (waste)
        this.freeRects = this.freeRects.filter(r => r.w >= 1 && r.h >= 1);
    }
}

// ----------------------------------------------------------------------
// GENERATOR
// ----------------------------------------------------------------------

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestResultSheet[]> {

    // 1. Prepare Items
    const rawItems: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const dims0 = calculatePartPhysicalExtents(part, tools);
        const maxY0 = dims0.height - dims0.offsetY; 

        for (let i = 0; i < sp.quantity; i++) {
            rawItems.push({
                uid: generateId(),
                partId: sp.partId,
                width: dims0.width,
                height: dims0.height,
                offsetX: dims0.offsetX,
                offsetY: dims0.offsetY,
                allowRotation: sp.nesting.allow90_270,
                rotatedWidth: dims0.height,
                rotatedHeight: dims0.width,
                rotatedOffsetX: maxY0,
                rotatedOffsetY: dims0.offsetX,
                area: dims0.width * dims0.height
            });
        }
    }

    const completedSheets: NestResultSheet[] = [];
    const { 
        sheetMarginTop, sheetMarginBottom, sheetMarginLeft, sheetMarginRight, 
        partSpacingX, partSpacingY, useCommonLine
    } = settings;

    const calculateEfficiency = (packer: GuillotinePacker, totalArea: number) => {
        const usedArea = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        return usedArea / totalArea;
    };

    let remainingItems = [...rawItems];

    // 2. Packing Loop
    while (remainingItems.length > 0) {

        let activeStock: SheetStock | undefined;
        if (settings.activeSheetId) {
            activeStock = settings.availableSheets.find(s => s.id === settings.activeSheetId);
        }
        if (!activeStock && settings.availableSheets.length > 0) activeStock = settings.availableSheets[0];
        if (!activeStock) break; 

        const packW = activeStock.width - sheetMarginLeft - sheetMarginRight;
        const packH = activeStock.height - sheetMarginTop - sheetMarginBottom;

        // --- MULTI-PASS SIMULATION ---
        const strategies: { name: string, packer: GuillotinePacker, packedIndices: Set<number>, score: number }[] = [];

        const configs = [
            { id: 'Chess-Lookahead', sort: 'max_side', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'BestFit-Short', sort: 'area', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'BestFit-Long', sort: 'area', strategy: 'LongAxis' as SplitStrategy },
            { id: 'MaxSide-Short', sort: 'max_side', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'MaxSide-Long', sort: 'max_side', strategy: 'LongAxis' as SplitStrategy },
            { id: 'Width-Short', sort: 'width', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'Vertical-Strip', sort: 'max_side', strategy: 'Vertical' as SplitStrategy },
            { id: 'Horizontal-Strip', sort: 'max_side', strategy: 'Horizontal' as SplitStrategy },
        ];

        for (const config of configs) {
            const currentItems = [...remainingItems];

            // Initial Sort
            currentItems.sort((a, b) => {
                if (config.sort === 'width') return b.width - a.width;
                if (config.sort === 'max_side') return Math.max(b.width, b.height) - Math.max(a.width, a.height);
                return b.area - a.area;
            });

            const packer = new GuillotinePacker(packW, packH, partSpacingX, partSpacingY, config.strategy, useCommonLine);
            const packedUids = new Set<string>();

            if (config.id === 'Chess-Lookahead') {
                // --- CHESS STRATEGY: Look ahead N steps to pick the best part ---
                // Instead of purely greedy linear iteration, we simulate choices.

                let candidatePool = [...currentItems];
                const LOOKAHEAD_WIDTH = 5; // Look at top 5 largest parts
                const LOOKAHEAD_SIM_LIMIT = 5; // How many subsequent parts to simulate placement for

                while (candidatePool.length > 0) {
                    // 1. Identify candidates (Top N unplaced parts)
                    // We only look at the start of the sorted list to save time, 
                    // assuming sorting already prioritizes 'hard' parts.
                    const candidates = candidatePool.slice(0, LOOKAHEAD_WIDTH);

                    let bestCandidateIdx = -1;
                    let bestSimScore = -1;
                    let bestCandidatePos = null;

                    // 2. Simulate each candidate
                    for (let c = 0; c < candidates.length; c++) {
                        const candidate = candidates[c];
                        const simPacker = packer.clone(); // Clone state

                        // Try place candidate
                        const pos = simPacker.findPosition(candidate);
                        if (pos) {
                            simPacker.placeItem(candidate, pos.rectIndex, pos.rotation, pos.appliedSpacingX, pos.appliedSpacingY);

                            // 3. Fast Forward Simulation: Greedily place subsequent parts
                            let simScore = candidate.area; 
                            let filledCount = 0;

                            // Simulate placing the REST of the pool (limited depth)
                            const simulationPool = candidatePool.filter((_, idx) => idx !== c);

                            for (const simItem of simulationPool) {
                                if (filledCount >= LOOKAHEAD_SIM_LIMIT) break;
                                const simPos = simPacker.findPosition(simItem);
                                if (simPos) {
                                    simPacker.placeItem(simItem, simPos.rectIndex, simPos.rotation, simPos.appliedSpacingX, simPos.appliedSpacingY);
                                    simScore += simItem.area;
                                    filledCount++;
                                }
                            }

                            if (simScore > bestSimScore) {
                                bestSimScore = simScore;
                                bestCandidateIdx = c;
                                bestCandidatePos = pos;
                            }
                        }
                    }

                    // 4. Commit best move
                    if (bestCandidateIdx !== -1 && bestCandidatePos) {
                        const chosen = candidates[bestCandidateIdx];
                        packer.placeItem(chosen, bestCandidatePos.rectIndex, bestCandidatePos.rotation, bestCandidatePos.appliedSpacingX, bestCandidatePos.appliedSpacingY);
                        packedUids.add(chosen.uid);
                        // Remove chosen from pool
                        candidatePool.splice(bestCandidateIdx, 1);
                    } else {
                        // If no candidate fits, remove the first one to advance (it might fit later or on next sheet)
                        // But actually, if top N don't fit, probably none fit easily. 
                        // Just try next in list linearly to be safe.
                        const fallbackIdx = candidatePool.findIndex(itm => {
                            const p = packer.findPosition(itm);
                            if (p) {
                                packer.placeItem(itm, p.rectIndex, p.rotation, p.appliedSpacingX, p.appliedSpacingY);
                                packedUids.add(itm.uid);
                                return true;
                            }
                            return false;
                        });

                        if (fallbackIdx !== -1) {
                            candidatePool.splice(fallbackIdx, 1);
                        } else {
                            // Nothing fits anymore
                            break;
                        }
                    }
                }

            } else {
                // --- STANDARD STRATEGY ---
                for (const item of currentItems) {
                    const bestPos = packer.findPosition(item);
                    if (bestPos) {
                        packer.placeItem(item, bestPos.rectIndex, bestPos.rotation, bestPos.appliedSpacingX, bestPos.appliedSpacingY);
                        packedUids.add(item.uid);
                    }
                }
            }

            const efficiency = calculateEfficiency(packer, packW * packH);
            const count = packedUids.size;

            // Score
            const score = count * 1000 + efficiency * 100;

            const originalIndices = new Set<number>();
            remainingItems.forEach((item, idx) => {
                if (packedUids.has(item.uid)) originalIndices.add(idx);
            });

            strategies.push({ name: config.id, packer, packedIndices: originalIndices, score });
        }

        // --- PICK WINNER ---
        strategies.sort((a, b) => b.score - a.score);
        const winner = strategies[0];

        if (winner.packedIndices.size === 0) {
            console.warn("Item too big for sheet:", remainingItems[0]);
            remainingItems.shift(); 
            continue;
        }

        // --- SHEET REPLICATION LOGIC ---
        // Instead of just creating 1 sheet, let's see if we can create N identical sheets
        // to reduce variety.

        const templateParts = winner.packer.placedItems;
        const requiredParts = new Map<string, number>();
        templateParts.forEach(p => {
            requiredParts.set(p.item.partId, (requiredParts.get(p.item.partId) || 0) + 1);
        });

        // First, remove the parts for the *first* sheet (the winner)
        remainingItems = remainingItems.filter((_, i) => !winner.packedIndices.has(i));

        let sheetQuantity = 1;

        // Now look at remainingItems to see if we can perform this exact layout again
        while (true) {
            // Find indices of parts that can satisfy the requirement for ONE more sheet
            const indicesToRemove: number[] = [];
            const tempUsedIndices = new Set<number>(); // To avoid picking same item twice in one pass
            let possible = true;

            for (const [partId, reqQty] of requiredParts.entries()) {
                let found = 0;
                for (let i = 0; i < remainingItems.length; i++) {
                    if (tempUsedIndices.has(i)) continue;

                    if (remainingItems[i].partId === partId) {
                        tempUsedIndices.add(i);
                        indicesToRemove.push(i);
                        found++;
                        if (found === reqQty) break;
                    }
                }
                if (found < reqQty) {
                    possible = false;
                    break;
                }
            }

            if (possible) {
                sheetQuantity++;
                // Commit removal. Sort descending to splice safely.
                indicesToRemove.sort((a, b) => b - a);
                indicesToRemove.forEach(idx => remainingItems.splice(idx, 1));
            } else {
                break; // Not enough parts for another full sheet
            }
        }

        const packer = winner.packer;

        // Auto-Calc Width Logic
        let finalSheetWidth = activeStock.width;
        let maxPlacedX = 0;
        packer.placedItems.forEach(p => {
            const w = (p.rotation === 90) ? p.item.rotatedWidth : p.item.width;
            if (p.x + w > maxPlacedX) maxPlacedX = p.x + w;
        });

        const isAutoCalc = settings.utilizationStrategy === SheetUtilizationStrategy.AutoCalculation;
        if (isAutoCalc) {
            const requiredPhys = sheetMarginLeft + maxPlacedX + sheetMarginRight;
            finalSheetWidth = Math.ceil(requiredPhys / 100) * 100;
            if (finalSheetWidth > 2560) finalSheetWidth = 2560;
        }

        const usedAreaPx = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        const totalAreaPx = finalSheetWidth * activeStock.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: isAutoCalc ? `Auto ${finalSheetWidth}x${activeStock.height} (${winner.name})` : `Sheet ${completedSheets.length + 1}`,
            stockSheetId: activeStock.id,
            width: finalSheetWidth,
            height: activeStock.height,
            material: activeStock.material,
            thickness: activeStock.thickness,
            placedParts: packer.placedItems.map(p => {
                const ox = (p.rotation === 90) ? p.item.rotatedOffsetX : p.item.offsetX;
                const oy = (p.rotation === 90) ? p.item.rotatedOffsetY : p.item.offsetY;

                return {
                    id: generateId(),
                    partId: p.item.partId,
                    x: p.x + sheetMarginLeft + ox,
                    y: p.y + sheetMarginBottom + oy,
                    rotation: p.rotation
                };
            }),
            usedArea: totalAreaPx > 0 ? (usedAreaPx / totalAreaPx) * 100 : 0,
            scrapPercentage: totalAreaPx > 0 ? 100 - ((usedAreaPx / totalAreaPx) * 100) : 100,
            partCount: packer.placedItems.length,
            quantity: sheetQuantity // <-- Applied here
        };

        completedSheets.push(resultSheet);

        await new Promise(resolve => setTimeout(resolve, 5));
        yield [...completedSheets];
    }
}

import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings, SheetStock, SheetUtilizationStrategy } from '../types';
import { generateId } from '../utils/helpers';
import { calculatePartPhysicalExtents } from './geometry';

// ----------------------------------------------------------------------
// TYPES & HELPERS
// ----------------------------------------------------------------------

interface PackerItem {
    uid: string;
    partId: string;
    width: number;
    height: number;
    offsetX: number; 
    offsetY: number;
    allowRotation: boolean;
    // Pre-calculated for 90deg rotation
    rotatedWidth: number;
    rotatedHeight: number;
    rotatedOffsetX: number;
    rotatedOffsetY: number;
    area: number; 
    preferredRotation?: number; // 0 or 90, based on density simulation
}

interface NeighborRef {
    dim: number; // The length of the edge facing the free rect
}

interface FreeRect {
    x: number;
    y: number;
    w: number;
    h: number;
    // Context about what borders this free space
    neighborLeft?: NeighborRef;   // What part is immediately to the left?
    neighborBottom?: NeighborRef; // What part is immediately below?
}

type SplitStrategy = 'Vertical' | 'Horizontal' | 'ShortAxis' | 'LongAxis';

// ----------------------------------------------------------------------
// PRE-FLIGHT ANALYSIS
// ----------------------------------------------------------------------

/**
 * Simulates filling a sheet with a single part to determine the optimal orientation
 * for maximum density.
 */
const determineOptimalOrientation = (
    partW: number, 
    partH: number, 
    sheetW: number, 
    sheetH: number, 
    gapX: number, 
    gapY: number,
    canRotate: boolean
): number | undefined => {
    if (!canRotate) return 0;

    // Helper: Simple Grid Calculation
    const calculateCapacity = (w: number, h: number) => {
        if (w > sheetW || h > sheetH) return 0;
        const cols = Math.floor((sheetW + gapX) / (w + gapX));
        const rows = Math.floor((sheetH + gapY) / (h + gapY));
        return cols * rows;
    };

    // Case 0: Orientation 0
    const count0 = calculateCapacity(partW, partH);

    // Case 90: Orientation 90
    const count90 = calculateCapacity(partH, partW);

    // Decision with hysteresis (require significant advantage to switch from 0)
    if (count90 > count0) return 90;
    if (count0 > count90) return 0;

    // If equal, prefer the one that aligns long edge with long edge of sheet (usually 0 for landscape sheet)
    return sheetW > sheetH ? (partW > partH ? 0 : 90) : (partW > partH ? 90 : 0);
};

// ----------------------------------------------------------------------
// ROBUST GUILLOTINE PACKER CLASS
// ----------------------------------------------------------------------

class GuillotinePacker {
    width: number;
    height: number;
    spacingX: number;
    spacingY: number;
    useCommonLine: boolean;
    freeRects: FreeRect[];
    placedItems: { item: PackerItem, x: number, y: number, rotation: number }[];
    strategy: SplitStrategy;

    constructor(
        width: number, 
        height: number, 
        spacingX: number, 
        spacingY: number, 
        strategy: SplitStrategy = 'ShortAxis',
        useCommonLine: boolean = false
    ) {
        this.width = width;
        this.height = height;
        this.spacingX = spacingX;
        this.spacingY = spacingY;
        this.useCommonLine = useCommonLine;
        this.freeRects = [{ x: 0, y: 0, w: width, h: height }];
        this.placedItems = [];
        this.strategy = strategy;
    }

    // Creates a deep copy of the packer for simulation
    clone(): GuillotinePacker {
        const p = new GuillotinePacker(this.width, this.height, this.spacingX, this.spacingY, this.strategy, this.useCommonLine);
        p.freeRects = JSON.parse(JSON.stringify(this.freeRects));
        p.placedItems = [...this.placedItems];
        return p;
    }

    // Helper to calculate required spacing based on neighbor match
    getDynamicSpacing(itemDim: number, neighbor?: NeighborRef, axisSpacing?: number): number {
        const defaultSpacing = axisSpacing || 0;

        if (this.useCommonLine && neighbor) {
            // Check if dimensions match (with small tolerance for float errors)
            if (Math.abs(itemDim - neighbor.dim) < 0.5) {
                // If dimensions match, we can effectively share the line.
                // The API assumes spacing is ADDED. Negative spacing simulates overlap/sharing.
                // For common line cut (single cut for two parts), distance is 0 or tool width.
                // Here we assume "Common Line" means 0 distance between geometrical edges.
                // However, our coordinates usually include tool compensation? 
                // Let's assume geometry is the finished part. Common line means gap = tool width (one cut).
                // Or true common line (0 gap). Let's use a small negative to indicate tightness priority.
                return -5; 
            }
        }
        return defaultSpacing;
    }

    // Heuristic: Best Area Fit (BAF)
    findPosition(item: PackerItem): { rectIndex: number, rotation: number, score: number, appliedSpacingX: number, appliedSpacingY: number } | null {
        let bestScore = Infinity;
        let bestRectIndex = -1;
        let bestRotation = 0; // 0 or 90
        let bestSpacingX = this.spacingX;
        let bestSpacingY = this.spacingY;

        for (let i = 0; i < this.freeRects.length; i++) {
            const rect = this.freeRects[i];

            // --- Strategy Position Penalty ---
            // Small bias to pick top-left or bottom-left depending on strategy to break ties
            let positionPenalty = 0;
            if (this.strategy === 'Vertical') {
                positionPenalty = (rect.x * 10 + rect.y) * 0.0001; 
            } else if (this.strategy === 'Horizontal') {
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            } else {
                // Generic reading order bias
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            }

            // --- Try 0 degrees ---
            {
                // Determine spacing based on neighbors
                const sX = this.getDynamicSpacing(item.height, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.width, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.width + sX);
                const effectiveUsedH = Math.max(0, item.height + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);

                    // Score: Minimize leftover (Best Short Side Fit)
                    const fitScore = Math.min(leftoverX, leftoverY); 

                    // Common Line Bonus: Huge preference
                    const commonLineBonus = (sX < 0 || sY < 0) ? 50000 : 0; // Massively prioritized

                    // Optimal Orientation Bonus:
                    // If the item prefers 0 deg and we are at 0, small bonus.
                    const orientationBonus = (item.preferredRotation === 0) ? 1000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus - orientationBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 0;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }

            // --- Try 90 degrees ---
            if (item.allowRotation) {
                const sX = this.getDynamicSpacing(item.rotatedHeight, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.rotatedWidth, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.rotatedWidth + sX);
                const effectiveUsedH = Math.max(0, item.rotatedHeight + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);
                    const fitScore = Math.min(leftoverX, leftoverY);

                    const commonLineBonus = (sX < 0 || sY < 0) ? 50000 : 0;
                    const orientationBonus = (item.preferredRotation === 90) ? 1000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus - orientationBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 90;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }
        }

        if (bestRectIndex !== -1) {
            return { 
                rectIndex: bestRectIndex, 
                rotation: bestRotation, 
                score: bestScore,
                appliedSpacingX: bestSpacingX,
                appliedSpacingY: bestSpacingY
            };
        }
        return null;
    }

    placeItem(item: PackerItem, rectIndex: number, rotation: number, spacingX: number, spacingY: number) {
        const rect = this.freeRects[rectIndex];
        const w = rotation === 90 ? item.rotatedWidth : item.width;
        const h = rotation === 90 ? item.rotatedHeight : item.height;

        const actualSpacingX = rect.x === 0 ? 0 : spacingX;
        const actualSpacingY = rect.y === 0 ? 0 : spacingY;

        const placedX = rect.x + actualSpacingX;
        const placedY = rect.y + actualSpacingY;

        this.placedItems.push({
            item,
            x: placedX,
            y: placedY,
            rotation
        });

        const usedW = w + actualSpacingX;
        const usedH = h + actualSpacingY;

        const freeW = rect.w - usedW;
        const freeH = rect.h - usedH;

        let splitHorizontal = false;

        if (this.strategy === 'Horizontal') {
            splitHorizontal = true;
        } else if (this.strategy === 'Vertical') {
            splitHorizontal = false;
        } else if (this.strategy === 'ShortAxis') {
            splitHorizontal = freeW < freeH;
        } else {
            // LongAxis
            splitHorizontal = freeW > freeH;
        }

        this.freeRects.splice(rectIndex, 1);

        let newRectTop: FreeRect | null = null;
        let newRectRight: FreeRect | null = null;

        const splitX = rect.x + usedW;
        const splitY = rect.y + usedH;

        // NOTE ON NEIGHBORS:
        // When splitting, we must correctly assign neighbor references.
        // neighborLeft: The edge to the left of the new rect.
        // neighborBottom: The edge below the new rect.

        if (splitHorizontal) {
            // Horizontal Split (Line along X)
            // Top Rect: Above the placed item line
            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: rect.w, 
                    h: freeH,
                    neighborBottom: { dim: w }, // Below it is the top edge of the item just placed (which has width 'w')
                    neighborLeft: rect.neighborLeft 
                };
            }
            // Right Rect: To the right of the placed item
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: Math.min(usedH, rect.h),
                    neighborLeft: { dim: h }, // To its left is the right edge of the item (height 'h')
                    neighborBottom: rect.neighborBottom 
                };
            }
        } else {
            // Vertical Split (Line along Y)
            // Top Rect: Above the placed item
            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: Math.min(usedW, rect.w), 
                    h: freeH,
                    neighborBottom: { dim: w }, // Below is item top
                    neighborLeft: rect.neighborLeft 
                };
            }
            // Right Rect: To the right
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: rect.h,
                    neighborLeft: { dim: h }, // Left is item right
                    neighborBottom: rect.neighborBottom
                };
            }
        }

        // We push Right then Top (or Top then Right) - order affects heuristic search order but not correctness
        if (newRectTop && newRectTop.w > 0 && newRectTop.h > 0) this.freeRects.push(newRectTop);
        if (newRectRight && newRectRight.w > 0 && newRectRight.h > 0) this.freeRects.push(newRectRight);

        // Pruning tiny rectangles (waste)
        this.freeRects = this.freeRects.filter(r => r.w >= 1 && r.h >= 1);
    }
}

// ----------------------------------------------------------------------
// GENERATOR
// ----------------------------------------------------------------------

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestResultSheet[]> {

    // 0. Pre-Calculation: Determine Preferred Orientation for each part
    const orientationPreferences = new Map<string, number>();

    // Get primary sheet size for simulation
    const stockSheet = settings.availableSheets.find(s => s.id === settings.activeSheetId) || settings.availableSheets[0];
    const simW = stockSheet ? stockSheet.width - settings.sheetMarginLeft - settings.sheetMarginRight : 2500;
    const simH = stockSheet ? stockSheet.height - settings.sheetMarginTop - settings.sheetMarginBottom : 1250;

    const uniquePartIds = Array.from(new Set(scheduledParts.map(sp => sp.partId)));

    for (const pid of uniquePartIds) {
        const part = allParts.find(p => p.id === pid);
        const sched = scheduledParts.find(sp => sp.partId === pid);
        if (part && sched) {
            const dims = calculatePartPhysicalExtents(part, tools);
            const pref = determineOptimalOrientation(
                dims.width, dims.height, 
                simW, simH, 
                settings.partSpacingX, settings.partSpacingY,
                sched.nesting.allow90_270
            );
            if (pref !== undefined) {
                orientationPreferences.set(pid, pref);
            }
        }
    }

    // 1. Prepare Items
    const rawItems: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;

        const dims0 = calculatePartPhysicalExtents(part, tools);
        const maxY0 = dims0.height - dims0.offsetY; 

        const preferredRot = orientationPreferences.get(sp.partId);

        for (let i = 0; i < sp.quantity; i++) {
            rawItems.push({
                uid: generateId(),
                partId: sp.partId,
                width: dims0.width,
                height: dims0.height,
                offsetX: dims0.offsetX,
                offsetY: dims0.offsetY,
                allowRotation: sp.nesting.allow90_270,
                rotatedWidth: dims0.height,
                rotatedHeight: dims0.width,
                rotatedOffsetX: maxY0,
                rotatedOffsetY: dims0.offsetX,
                area: dims0.width * dims0.height,
                preferredRotation: preferredRot
            });
        }
    }

    const completedSheets: NestResultSheet[] = [];
    const { 
        sheetMarginTop, sheetMarginBottom, sheetMarginLeft, sheetMarginRight, 
        partSpacingX, partSpacingY, useCommonLine
    } = settings;

    const calculateEfficiency = (packer: GuillotinePacker, totalArea: number) => {
        const usedArea = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        return usedArea / totalArea;
    };

    let remainingItems = [...rawItems];

    // 2. Packing Loop
    while (remainingItems.length > 0) {

        let activeStock: SheetStock | undefined;
        if (settings.activeSheetId) {
            activeStock = settings.availableSheets.find(s => s.id === settings.activeSheetId);
        }
        if (!activeStock && settings.availableSheets.length > 0) activeStock = settings.availableSheets[0];
        if (!activeStock) break; 

        const packW = activeStock.width - sheetMarginLeft - sheetMarginRight;
        const packH = activeStock.height - sheetMarginTop - sheetMarginBottom;

        // --- MULTI-PASS SIMULATION ---
        const strategies: { name: string, packer: GuillotinePacker, packedIndices: Set<number>, score: number }[] = [];

        const configs = [
            { id: 'Chess-Lookahead', sort: 'max_side', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'BestFit-Short', sort: 'area', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'BestFit-Long', sort: 'area', strategy: 'LongAxis' as SplitStrategy },
            { id: 'MaxSide-Short', sort: 'max_side', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'MaxSide-Long', sort: 'max_side', strategy: 'LongAxis' as SplitStrategy },
            { id: 'Width-Short', sort: 'width', strategy: 'ShortAxis' as SplitStrategy },
            { id: 'Vertical-Strip', sort: 'max_side', strategy: 'Vertical' as SplitStrategy },
            { id: 'Horizontal-Strip', sort: 'max_side', strategy: 'Horizontal' as SplitStrategy },
        ];

        for (const config of configs) {
            const currentItems = [...remainingItems];

            // Initial Sort
            currentItems.sort((a, b) => {
                if (config.sort === 'width') return b.width - a.width;
                if (config.sort === 'max_side') return Math.max(b.width, b.height) - Math.max(a.width, a.height);
                return b.area - a.area;
            });

            const packer = new GuillotinePacker(packW, packH, partSpacingX, partSpacingY, config.strategy, useCommonLine);
            const packedUids = new Set<string>();

            if (config.id === 'Chess-Lookahead') {
                // --- CHESS STRATEGY: Look ahead N steps to pick the best part ---
                // Instead of purely greedy linear iteration, we simulate choices.

                let candidatePool = [...currentItems];
                const LOOKAHEAD_WIDTH = 5; // Look at top 5 largest parts
                const LOOKAHEAD_SIM_LIMIT = 5; // How many subsequent parts to simulate placement for

                while (candidatePool.length > 0) {
                    // 1. Identify candidates (Top N unplaced parts)
                    // We only look at the start of the sorted list to save time, 
                    // assuming sorting already prioritizes 'hard' parts.
                    const candidates = candidatePool.slice(0, LOOKAHEAD_WIDTH);

                    let bestCandidateIdx = -1;
                    let bestSimScore = -1;
                    let bestCandidatePos = null;

                    // 2. Simulate each candidate
                    for (let c = 0; c < candidates.length; c++) {
                        const candidate = candidates[c];
                        const simPacker = packer.clone(); // Clone state

                        // Try place candidate
                        const pos = simPacker.findPosition(candidate);
                        if (pos) {
                            simPacker.placeItem(candidate, pos.rectIndex, pos.rotation, pos.appliedSpacingX, pos.appliedSpacingY);

                            // 3. Fast Forward Simulation: Greedily place subsequent parts
                            let simScore = candidate.area; 
                            let filledCount = 0;

                            // Simulate placing the REST of the pool (limited depth)
                            const simulationPool = candidatePool.filter((_, idx) => idx !== c);

                            for (const simItem of simulationPool) {
                                if (filledCount >= LOOKAHEAD_SIM_LIMIT) break;
                                const simPos = simPacker.findPosition(simItem);
                                if (simPos) {
                                    simPacker.placeItem(simItem, simPos.rectIndex, simPos.rotation, simPos.appliedSpacingX, simPos.appliedSpacingY);
                                    simScore += simItem.area;
                                    filledCount++;
                                }
                            }

                            if (simScore > bestSimScore) {
                                bestSimScore = simScore;
                                bestCandidateIdx = c;
                                bestCandidatePos = pos;
                            }
                        }
                    }

                    // 4. Commit best move
                    if (bestCandidateIdx !== -1 && bestCandidatePos) {
                        const chosen = candidates[bestCandidateIdx];
                        packer.placeItem(chosen, bestCandidatePos.rectIndex, bestCandidatePos.rotation, bestCandidatePos.appliedSpacingX, bestCandidatePos.appliedSpacingY);
                        packedUids.add(chosen.uid);
                        // Remove chosen from pool
                        candidatePool.splice(bestCandidateIdx, 1);
                    } else {
                        // Fallback logic
                        const fallbackIdx = candidatePool.findIndex(itm => {
                            const p = packer.findPosition(itm);
                            if (p) {
                                packer.placeItem(itm, p.rectIndex, p.rotation, p.appliedSpacingX, p.appliedSpacingY);
                                packedUids.add(itm.uid);
                                return true;
                            }
                            return false;
                        });

                        if (fallbackIdx !== -1) {
                            candidatePool.splice(fallbackIdx, 1);
                        } else {
                            break;
                        }
                    }
                }

            } else {
                // --- STANDARD STRATEGY ---
                for (const item of currentItems) {
                    const bestPos = packer.findPosition(item);
                    if (bestPos) {
                        packer.placeItem(item, bestPos.rectIndex, bestPos.rotation, bestPos.appliedSpacingX, bestPos.appliedSpacingY);
                        packedUids.add(item.uid);
                    }
                }
            }

            const efficiency = calculateEfficiency(packer, packW * packH);
            const count = packedUids.size;

            // Score
            const score = count * 1000 + efficiency * 100;

            const originalIndices = new Set<number>();
            remainingItems.forEach((item, idx) => {
                if (packedUids.has(item.uid)) originalIndices.add(idx);
            });

            strategies.push({ name: config.id, packer, packedIndices: originalIndices, score });
        }

        // --- PICK WINNER ---
        strategies.sort((a, b) => b.score - a.score);
        const winner = strategies[0];

        if (winner.packedIndices.size === 0) {
            console.warn("Item too big for sheet:", remainingItems[0]);
            remainingItems.shift(); 
            continue;
        }

        // --- SHEET REPLICATION LOGIC ---
        // Instead of just creating 1 sheet, let's see if we can create N identical sheets
        // to reduce variety.

        const templateParts = winner.packer.placedItems;
        const requiredParts = new Map<string, number>();
        templateParts.forEach(p => {
            requiredParts.set(p.item.partId, (requiredParts.get(p.item.partId) || 0) + 1);
        });

        // First, remove the parts for the *first* sheet (the winner)
        remainingItems = remainingItems.filter((_, i) => !winner.packedIndices.has(i));

        let sheetQuantity = 1;

        // Now look at remainingItems to see if we can perform this exact layout again
        while (true) {
            // Find indices of parts that can satisfy the requirement for ONE more sheet
            const indicesToRemove: number[] = [];
            const tempUsedIndices = new Set<number>(); // To avoid picking same item twice in one pass
            let possible = true;

            for (const [partId, reqQty] of requiredParts.entries()) {
                let found = 0;
                for (let i = 0; i < remainingItems.length; i++) {
                    if (tempUsedIndices.has(i)) continue;

                    if (remainingItems[i].partId === partId) {
                        tempUsedIndices.add(i);
                        indicesToRemove.push(i);
                        found++;
                        if (found === reqQty) break;
                    }
                }
                if (found < reqQty) {
                    possible = false;
                    break;
                }
            }

            if (possible) {
                sheetQuantity++;
                // Commit removal. Sort descending to splice safely.
                indicesToRemove.sort((a, b) => b - a);
                indicesToRemove.forEach(idx => remainingItems.splice(idx, 1));
            } else {
                break; // Not enough parts for another full sheet
            }
        }

        const packer = winner.packer;

        // Auto-Calc Width Logic
        let finalSheetWidth = activeStock.width;
        let maxPlacedX = 0;
        packer.placedItems.forEach(p => {
            const w = (p.rotation === 90) ? p.item.rotatedWidth : p.item.width;
            if (p.x + w > maxPlacedX) maxPlacedX = p.x + w;
        });

        const isAutoCalc = settings.utilizationStrategy === SheetUtilizationStrategy.AutoCalculation;
        if (isAutoCalc) {
            const requiredPhys = sheetMarginLeft + maxPlacedX + sheetMarginRight;
            finalSheetWidth = Math.ceil(requiredPhys / 100) * 100;
            if (finalSheetWidth > 2560) finalSheetWidth = 2560;
        }

        const usedAreaPx = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
        const totalAreaPx = finalSheetWidth * activeStock.height;

        const resultSheet: NestResultSheet = {
            id: generateId(),
            sheetName: isAutoCalc ? `Auto ${finalSheetWidth}x${activeStock.height} (${winner.name})` : `Sheet ${completedSheets.length + 1}`,
            stockSheetId: activeStock.id,
            width: finalSheetWidth,
            height: activeStock.height,
            material: activeStock.material,
            thickness: activeStock.thickness,
            placedParts: packer.placedItems.map(p => {
                const ox = (p.rotation === 90) ? p.item.rotatedOffsetX : p.item.offsetX;
                const oy = (p.rotation === 90) ? p.item.rotatedOffsetY : p.item.offsetY;

                return {
                    id: generateId(),
                    partId: p.item.partId,
                    x: p.x + sheetMarginLeft + ox,
                    y: p.y + sheetMarginBottom + oy,
                    rotation: p.rotation
                };
            }),
            usedArea: totalAreaPx > 0 ? (usedAreaPx / totalAreaPx) * 100 : 0,
            scrapPercentage: totalAreaPx > 0 ? 100 - ((usedAreaPx / totalAreaPx) * 100) : 100,
            partCount: packer.placedItems.length,
            quantity: sheetQuantity // <-- Applied here
        };

        completedSheets.push(resultSheet);

        await new Promise(resolve => setTimeout(resolve, 5));
        yield [...completedSheets];
    }
}

import { NestResultSheet, ScheduledPart, Part, Tool, NestingSettings, SheetStock, SheetUtilizationStrategy } from '../types';
import { generateId } from '../utils/helpers';
import { calculatePartPhysicalExtents } from './geometry';

// ----------------------------------------------------------------------
// TYPES & HELPERS
// ----------------------------------------------------------------------

interface PackerItem {
    uid: string;
    partId: string;
    width: number;
    height: number;
    offsetX: number; 
    offsetY: number;
    allowRotation: boolean;
    // Pre-calculated for 90deg rotation
    rotatedWidth: number;
    rotatedHeight: number;
    rotatedOffsetX: number;
    rotatedOffsetY: number;
    area: number; 
    preferredRotation?: number; // 0 or 90, based on density simulation
}

interface NeighborRef {
    dim: number; // The length of the edge facing the free rect
}

interface FreeRect {
    x: number;
    y: number;
    w: number;
    h: number;
    // Context about what borders this free space
    neighborLeft?: NeighborRef;   // What part is immediately to the left?
    neighborBottom?: NeighborRef; // What part is immediately below?
}

type SplitStrategy = 'Vertical' | 'Horizontal' | 'ShortAxis' | 'LongAxis';

// ----------------------------------------------------------------------
// PRE-FLIGHT ANALYSIS
// ----------------------------------------------------------------------

/**
 * Simulates filling a sheet with a single part to determine the optimal orientation
 * for maximum density.
 */
const determineOptimalOrientation = (
    partW: number, 
    partH: number, 
    sheetW: number, 
    sheetH: number, 
    gapX: number, 
    gapY: number,
    canRotate: boolean
): number | undefined => {
    if (!canRotate) return 0;

    // Helper: Simple Grid Calculation
    const calculateCapacity = (w: number, h: number) => {
        if (w > sheetW || h > sheetH) return 0;
        const cols = Math.floor((sheetW + gapX) / (w + gapX));
        const rows = Math.floor((sheetH + gapY) / (h + gapY));
        return cols * rows;
    };

    // Case 0: Orientation 0
    const count0 = calculateCapacity(partW, partH);

    // Case 90: Orientation 90
    const count90 = calculateCapacity(partH, partW);

    // Decision with hysteresis (require significant advantage to switch from 0)
    if (count90 > count0) return 90;
    if (count0 > count90) return 0;

    // If equal, prefer the one that aligns long edge with long edge of sheet (usually 0 for landscape sheet)
    return sheetW > sheetH ? (partW > partH ? 0 : 90) : (partW > partH ? 90 : 0);
};

// ----------------------------------------------------------------------
// ROBUST GUILLOTINE PACKER CLASS
// ----------------------------------------------------------------------

class GuillotinePacker {
    width: number;
    height: number;
    spacingX: number;
    spacingY: number;
    useCommonLine: boolean;
    freeRects: FreeRect[];
    placedItems: { item: PackerItem, x: number, y: number, rotation: number }[];
    strategy: SplitStrategy;

    constructor(
        width: number, 
        height: number, 
        spacingX: number, 
        spacingY: number, 
        strategy: SplitStrategy = 'ShortAxis',
        useCommonLine: boolean = false
    ) {
        this.width = width;
        this.height = height;
        this.spacingX = spacingX;
        this.spacingY = spacingY;
        this.useCommonLine = useCommonLine;
        this.freeRects = [{ x: 0, y: 0, w: width, h: height }];
        this.placedItems = [];
        this.strategy = strategy;
    }

    // Creates a deep copy of the packer for simulation
    clone(): GuillotinePacker {
        const p = new GuillotinePacker(this.width, this.height, this.spacingX, this.spacingY, this.strategy, this.useCommonLine);
        p.freeRects = JSON.parse(JSON.stringify(this.freeRects));
        p.placedItems = [...this.placedItems];
        return p;
    }

    // Helper to calculate required spacing based on neighbor match
    getDynamicSpacing(itemDim: number, neighbor?: NeighborRef, axisSpacing?: number): number {
        const defaultSpacing = axisSpacing || 0;

        if (this.useCommonLine && neighbor) {
            // Check if dimensions match (with small tolerance for float errors)
            if (Math.abs(itemDim - neighbor.dim) < 0.5) {
                return -5; 
            }
        }
        return defaultSpacing;
    }

    // Heuristic: Best Area Fit (BAF)
    findPosition(item: PackerItem): { rectIndex: number, rotation: number, score: number, appliedSpacingX: number, appliedSpacingY: number } | null {
        let bestScore = Infinity;
        let bestRectIndex = -1;
        let bestRotation = 0; // 0 or 90
        let bestSpacingX = this.spacingX;
        let bestSpacingY = this.spacingY;

        for (let i = 0; i < this.freeRects.length; i++) {
            const rect = this.freeRects[i];

            // --- Strategy Position Penalty ---
            // Small bias to pick top-left or bottom-left depending on strategy to break ties
            let positionPenalty = 0;
            if (this.strategy === 'Vertical') {
                positionPenalty = (rect.x * 10 + rect.y) * 0.0001; 
            } else if (this.strategy === 'Horizontal') {
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            } else {
                // Generic reading order bias
                positionPenalty = (rect.y * 10 + rect.x) * 0.0001;
            }

            // --- Try 0 degrees ---
            {
                // Determine spacing based on neighbors
                const sX = this.getDynamicSpacing(item.height, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.width, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.width + sX);
                const effectiveUsedH = Math.max(0, item.height + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);

                    // Score: Minimize leftover (Best Short Side Fit)
                    const fitScore = Math.min(leftoverX, leftoverY); 

                    // Common Line Bonus: Huge preference
                    const commonLineBonus = (sX < 0 || sY < 0) ? 50000 : 0; 

                    // Optimal Orientation Bonus:
                    const orientationBonus = (item.preferredRotation === 0) ? 1000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus - orientationBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 0;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }

            // --- Try 90 degrees ---
            if (item.allowRotation) {
                const sX = this.getDynamicSpacing(item.rotatedHeight, rect.neighborLeft, this.spacingX);
                const sY = this.getDynamicSpacing(item.rotatedWidth, rect.neighborBottom, this.spacingY);

                const effectiveUsedW = Math.max(0, item.rotatedWidth + sX);
                const effectiveUsedH = Math.max(0, item.rotatedHeight + sY);

                if (effectiveUsedW <= rect.w && effectiveUsedH <= rect.h) {
                    const leftoverX = Math.abs(rect.w - effectiveUsedW);
                    const leftoverY = Math.abs(rect.h - effectiveUsedH);
                    const fitScore = Math.min(leftoverX, leftoverY);

                    const commonLineBonus = (sX < 0 || sY < 0) ? 50000 : 0;
                    const orientationBonus = (item.preferredRotation === 90) ? 1000 : 0;

                    const totalScore = fitScore + positionPenalty - commonLineBonus - orientationBonus;

                    if (totalScore < bestScore) {
                        bestScore = totalScore;
                        bestRectIndex = i;
                        bestRotation = 90;
                        bestSpacingX = sX;
                        bestSpacingY = sY;
                    }
                }
            }
        }

        if (bestRectIndex !== -1) {
            return { 
                rectIndex: bestRectIndex, 
                rotation: bestRotation, 
                score: bestScore,
                appliedSpacingX: bestSpacingX,
                appliedSpacingY: bestSpacingY
            };
        }
        return null;
    }

    placeItem(item: PackerItem, rectIndex: number, rotation: number, spacingX: number, spacingY: number) {
        const rect = this.freeRects[rectIndex];
        const w = rotation === 90 ? item.rotatedWidth : item.width;
        const h = rotation === 90 ? item.rotatedHeight : item.height;

        const actualSpacingX = rect.x === 0 ? 0 : spacingX;
        const actualSpacingY = rect.y === 0 ? 0 : spacingY;

        const placedX = rect.x + actualSpacingX;
        const placedY = rect.y + actualSpacingY;

        this.placedItems.push({
            item,
            x: placedX,
            y: placedY,
            rotation
        });

        const usedW = w + actualSpacingX;
        const usedH = h + actualSpacingY;

        const freeW = rect.w - usedW;
        const freeH = rect.h - usedH;

        let splitHorizontal = false;

        if (this.strategy === 'Horizontal') {
            splitHorizontal = true;
        } else if (this.strategy === 'Vertical') {
            splitHorizontal = false;
        } else if (this.strategy === 'ShortAxis') {
            splitHorizontal = freeW < freeH;
        } else {
            // LongAxis
            splitHorizontal = freeW > freeH;
        }

        this.freeRects.splice(rectIndex, 1);

        let newRectTop: FreeRect | null = null;
        let newRectRight: FreeRect | null = null;

        const splitX = rect.x + usedW;
        const splitY = rect.y + usedH;

        if (splitHorizontal) {
            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: rect.w, 
                    h: freeH,
                    neighborBottom: { dim: w },
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: Math.min(usedH, rect.h),
                    neighborLeft: { dim: h },
                    neighborBottom: rect.neighborBottom 
                };
            }
        } else {
            if (freeH > 0) {
                newRectTop = { 
                    x: rect.x, 
                    y: splitY, 
                    w: Math.min(usedW, rect.w), 
                    h: freeH,
                    neighborBottom: { dim: w },
                    neighborLeft: rect.neighborLeft 
                };
            }
            if (freeW > 0) {
                newRectRight = { 
                    x: splitX, 
                    y: rect.y, 
                    w: freeW, 
                    h: rect.h,
                    neighborLeft: { dim: h },
                    neighborBottom: rect.neighborBottom
                };
            }
        }

        if (newRectTop && newRectTop.w > 0 && newRectTop.h > 0) this.freeRects.push(newRectTop);
        if (newRectRight && newRectRight.w > 0 && newRectRight.h > 0) this.freeRects.push(newRectRight);

        // Pruning tiny rectangles (waste)
        this.freeRects = this.freeRects.filter(r => r.w >= 1 && r.h >= 1);
    }
}

// ----------------------------------------------------------------------
// GENERATOR
// ----------------------------------------------------------------------

const calculateEfficiency = (packer: GuillotinePacker, totalArea: number) => {
    const usedArea = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
    return usedArea / totalArea;
};

// Helper to reconstruct PackerItems from a Result Sheet + Remaining Items
const reconstructItems = (sheets: NestResultSheet[], remainingItems: PackerItem[], allItemsRef: PackerItem[]): PackerItem[] => {
    const items: PackerItem[] = [];

    // 1. Items from Sheets
    sheets.forEach(sheet => {
        // Multiply by sheet quantity
        for (let q = 0; q < sheet.quantity; q++) {
            sheet.placedParts.forEach(pp => {
                // Find original definition to preserve rotation constraints etc.
                // We create a fresh copy with a new UID to treat it as a movable item
                const template = allItemsRef.find(i => i.partId === pp.partId);
                if (template) {
                    items.push({
                        ...template,
                        uid: generateId()
                    });
                }
            });
        }
    });

    // 2. Remaining items
    items.push(...remainingItems);

    return items;
};

const shuffleArray = <T>(array: T[]): T[] => {
    const newArr = [...array];
    for (let i = newArr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [newArr[i], newArr[j]] = [newArr[j], newArr[i]];
    }
    return newArr;
};

// Packs a SINGLE sheet as tightly as possible
const packSingleSheet = (
    items: PackerItem[], 
    activeStock: SheetStock,
    settings: NestingSettings
): { packer: GuillotinePacker, packedItems: PackerItem[], remainingItems: PackerItem[] } => {

    const packW = activeStock.width - settings.sheetMarginLeft - settings.sheetMarginRight;
    const packH = activeStock.height - settings.sheetMarginTop - settings.sheetMarginBottom;

    const strategies: { packer: GuillotinePacker, packedCount: number, score: number }[] = [];
    const configs = [
        { id: 'Chess-Step', strategy: 'ShortAxis' as SplitStrategy },
        { id: 'BestFit-Short', strategy: 'ShortAxis' as SplitStrategy },
        { id: 'BestFit-Long', strategy: 'LongAxis' as SplitStrategy },
    ];

    for (const config of configs) {
        const packer = new GuillotinePacker(packW, packH, settings.partSpacingX, settings.partSpacingY, config.strategy, settings.useCommonLine);
        const packedIds = new Set<string>();

        // Local copy for this strategy
        const currentPool = [...items];

        if (config.id === 'Chess-Step') {
            // "Lookahead" logic
            let pool = [...currentPool];
            while (pool.length > 0) {
                const candidates = pool.slice(0, 5); // Look at top 5
                let bestIdx = -1;
                let bestScore = -1;
                let bestPos = null;

                for (let c = 0; c < candidates.length; c++) {
                    const cand = candidates[c];
                    const sim = packer.clone();
                    const pos = sim.findPosition(cand);
                    if (pos) {
                        sim.placeItem(cand, pos.rectIndex, pos.rotation, pos.appliedSpacingX, pos.appliedSpacingY);
                        // Simulate next steps lightly
                        let simScore = cand.area;
                        const rest = pool.filter((_, i) => i !== c);
                        for (let k = 0; k < Math.min(3, rest.length); k++) {
                            const p2 = sim.findPosition(rest[k]);
                            if (p2) {
                                sim.placeItem(rest[k], p2.rectIndex, p2.rotation, p2.appliedSpacingX, p2.appliedSpacingY);
                                simScore += rest[k].area;
                            }
                        }
                        if (simScore > bestScore) {
                            bestScore = simScore;
                            bestIdx = c;
                            bestPos = pos;
                        }
                    }
                }

                if (bestIdx !== -1 && bestPos) {
                    const chosen = candidates[bestIdx];
                    packer.placeItem(chosen, bestPos.rectIndex, bestPos.rotation, bestPos.appliedSpacingX, bestPos.appliedSpacingY);
                    packedIds.add(chosen.uid);
                    pool.splice(bestIdx, 1);
                } else {
                    // Fallback linear
                    const fallbackIdx = pool.findIndex(itm => {
                        const p = packer.findPosition(itm);
                        if(p) {
                            packer.placeItem(itm, p.rectIndex, p.rotation, p.appliedSpacingX, p.appliedSpacingY);
                            packedIds.add(itm.uid);
                            return true;
                        }
                        return false;
                    });
                    if (fallbackIdx !== -1) pool.splice(fallbackIdx, 1);
                    else break; // Full
                }
            }
        } else {
            // Standard Linear
            for (const item of currentPool) {
                const pos = packer.findPosition(item);
                if (pos) {
                    packer.placeItem(item, pos.rectIndex, pos.rotation, pos.appliedSpacingX, pos.appliedSpacingY);
                    packedIds.add(item.uid);
                }
            }
        }

        const efficiency = calculateEfficiency(packer, packW * packH);
        strategies.push({ packer, packedCount: packedIds.size, score: packedIds.size * 1000 + efficiency * 100 });
    }

    strategies.sort((a,b) => b.score - a.score);
    const winner = strategies[0];

    const packedSet = new Set(winner.packer.placedItems.map(p => p.item.uid));
    const packedItems = items.filter(i => packedSet.has(i.uid));
    const remainingItems = items.filter(i => !packedSet.has(i.uid));

    return { packer: winner.packer, packedItems, remainingItems };
};

// Generates a NestResultSheet object from a packer
const createSheetResult = (
    packer: GuillotinePacker, 
    activeStock: SheetStock, 
    settings: NestingSettings, 
    index: number,
    suffix: string = ""
): NestResultSheet => {

    // Auto-Calc Width Logic
    let finalSheetWidth = activeStock.width;
    let maxPlacedX = 0;
    packer.placedItems.forEach(p => {
        const w = (p.rotation === 90) ? p.item.rotatedWidth : p.item.width;
        if (p.x + w > maxPlacedX) maxPlacedX = p.x + w;
    });

    const isAutoCalc = settings.utilizationStrategy === SheetUtilizationStrategy.AutoCalculation;
    if (isAutoCalc) {
        const requiredPhys = settings.sheetMarginLeft + maxPlacedX + settings.sheetMarginRight;
        finalSheetWidth = Math.ceil(requiredPhys / 100) * 100;
        if (finalSheetWidth > 2560) finalSheetWidth = 2560;
    }

    const usedAreaPx = packer.placedItems.reduce((sum, p) => sum + p.item.area, 0);
    const totalAreaPx = finalSheetWidth * activeStock.height;

    return {
        id: generateId(),
        sheetName: `Sheet ${index + 1}${suffix}`,
        stockSheetId: activeStock.id,
        width: finalSheetWidth,
        height: activeStock.height,
        material: activeStock.material,
        thickness: activeStock.thickness,
        placedParts: packer.placedItems.map(p => {
            const ox = (p.rotation === 90) ? p.item.rotatedOffsetX : p.item.offsetX;
            const oy = (p.rotation === 90) ? p.item.rotatedOffsetY : p.item.offsetY;

            return {
                id: generateId(),
                partId: p.item.partId,
                x: p.x + settings.sheetMarginLeft + ox,
                y: p.y + settings.sheetMarginBottom + oy,
                rotation: p.rotation
            };
        }),
        usedArea: totalAreaPx > 0 ? (usedAreaPx / totalAreaPx) * 100 : 0,
        scrapPercentage: totalAreaPx > 0 ? 100 - ((usedAreaPx / totalAreaPx) * 100) : 100,
        partCount: packer.placedItems.length,
        quantity: 1 // Optimization always yields discrete sheets initially, grouped later if needed
    };
};

export async function* nestingGenerator(
    scheduledParts: ScheduledPart[], 
    allParts: Part[], 
    tools: Tool[], 
    settings: NestingSettings
): AsyncGenerator<NestResultSheet[]> {

    // --- 0. PREPARATION ---
    const orientationPreferences = new Map<string, number>();
    const stockSheet = settings.availableSheets.find(s => s.id === settings.activeSheetId) || settings.availableSheets[0];
    const simW = stockSheet ? stockSheet.width - settings.sheetMarginLeft - settings.sheetMarginRight : 2500;
    const simH = stockSheet ? stockSheet.height - settings.sheetMarginTop - settings.sheetMarginBottom : 1250;

    const uniquePartIds = Array.from(new Set(scheduledParts.map(sp => sp.partId)));
    for (const pid of uniquePartIds) {
        const part = allParts.find(p => p.id === pid);
        const sched = scheduledParts.find(sp => sp.partId === pid);
        if (part && sched) {
            const dims = calculatePartPhysicalExtents(part, tools);
            const pref = determineOptimalOrientation(dims.width, dims.height, simW, simH, settings.partSpacingX, settings.partSpacingY, sched.nesting.allow90_270);
            if (pref !== undefined) orientationPreferences.set(pid, pref);
        }
    }

    const allItemsReference: PackerItem[] = []; // Template for reconstructing
    const initialItems: PackerItem[] = [];

    for (const sp of scheduledParts) {
        const part = allParts.find(p => p.id === sp.partId);
        if (!part) continue;
        const dims0 = calculatePartPhysicalExtents(part, tools);
        const maxY0 = dims0.height - dims0.offsetY; 
        const preferredRot = orientationPreferences.get(sp.partId);

        // Template item
        const tpl: PackerItem = {
            uid: '', // assigned later
            partId: sp.partId,
            width: dims0.width,
            height: dims0.height,
            offsetX: dims0.offsetX,
            offsetY: dims0.offsetY,
            allowRotation: sp.nesting.allow90_270,
            rotatedWidth: dims0.height,
            rotatedHeight: dims0.width,
            rotatedOffsetX: maxY0,
            rotatedOffsetY: dims0.offsetX,
            area: dims0.width * dims0.height,
            preferredRotation: preferredRot
        };
        allItemsReference.push(tpl);

        for (let i = 0; i < sp.quantity; i++) {
            initialItems.push({ ...tpl, uid: generateId() });
        }
    }

    // Sort initially by Max Side (Greedy baseline)
    initialItems.sort((a, b) => Math.max(b.width, b.height) - Math.max(a.width, a.height));

    // --- 1. INITIAL GREEDY PASS ---
    // We reuse the generic loop logic by treating it as the first optimization pass with no shuffle
    let currentSheets: NestResultSheet[] = [];
    let pool = [...initialItems];
    let sheetIdx = 0;

    while (pool.length > 0) {
        let activeStock: SheetStock | undefined;
        if (settings.activeSheetId) activeStock = settings.availableSheets.find(s => s.id === settings.activeSheetId);
        if (!activeStock && settings.availableSheets.length > 0) activeStock = settings.availableSheets[0];
        if (!activeStock) break; 

        const res = packSingleSheet(pool, activeStock, settings);

        // If nothing fit, skip
        if (res.packedItems.length === 0) {
            console.warn("Item too big for sheet:", pool[0]);
            pool.shift();
            continue;
        }

        const resultSheet = createSheetResult(res.packer, activeStock, settings, sheetIdx);
        currentSheets.push(resultSheet);

        pool = res.remainingItems;
        sheetIdx++;

        // Yield intermediate progress
        await new Promise(resolve => setTimeout(resolve, 5));
        yield [...currentSheets];
    }

    // --- 2. ITERATIVE OPTIMIZATION PHASE ---
    // At this point, `currentSheets` contains the greedy result.
    // We now enter an infinite loop trying to improve sheet by sheet.

    let targetSheetIndex = 0;
    let patience = 0; // How many failed shuffles before moving to next sheet
    const MAX_PATIENCE = 50; 

    // Reconstruct mutable pool from current result
    // We need to maintain the "State" of the nesting as a list of PackerItems per Sheet
    // But since `packSingleSheet` is destructive (consumes items), we need a way to 
    // "take apart" the existing solution starting from `targetSheetIndex`.

    while (true) {
        // Yield current state to let UI know we are optimizing
        // (UI just re-renders the same sheets, maybe add a marker "Optimizing Sheet X...")
        // Since we modify `currentSheets` in place below if better, just yielding is enough.

        // 1. Identify Target Sheet
        if (targetSheetIndex >= currentSheets.length) targetSheetIndex = 0;

        const activeStock = settings.availableSheets.find(s => s.id === currentSheets[targetSheetIndex].stockSheetId) || settings.availableSheets[0];

        // 2. Dissolve Target Sheet and ALL subsequent sheets into a pool of items
        // We keep sheets 0 to target-1 fixed.
        const fixedSheets = currentSheets.slice(0, targetSheetIndex);
        const sheetsToOptimize = currentSheets.slice(targetSheetIndex);

        // Reconstruct items from the sheets we are about to destroy/repack
        const optimizationPool = reconstructItems(sheetsToOptimize, [], allItemsReference);

        if (optimizationPool.length === 0) {
            targetSheetIndex = 0; // Should not happen
            continue;
        }

        // 3. MUTATION: Shuffle
        // Rule: Keep the FIRST part of the target sheet fixed (Anchor)
        // Find which item was the first placed on the target sheet in the current solution
        // The `sheetsToOptimize[0]` is the current version of the target sheet.
        const originalFirstPartId = sheetsToOptimize[0].placedParts[0]?.partId;

        // Separate the anchor item from the pool
        let anchorItem: PackerItem | undefined;
        let restPool: PackerItem[] = [];

        if (originalFirstPartId) {
            const idx = optimizationPool.findIndex(i => i.partId === originalFirstPartId);
            if (idx !== -1) {
                anchorItem = optimizationPool[idx];
                restPool = optimizationPool.filter((_, i) => i !== idx);
            } else {
                restPool = optimizationPool; // Should not happen
            }
        } else {
            restPool = optimizationPool;
        }

        // Shuffle the rest
        const shuffledRest = shuffleArray(restPool);
        const trialItems = anchorItem ? [anchorItem, ...shuffledRest] : shuffledRest;

        // 4. Pack Target Sheet (Trial)
        const trialRes = packSingleSheet(trialItems, activeStock, settings);

        // 5. Evaluate
        const currentEfficiency = sheetsToOptimize[0].usedArea; // Percent

        // Calculate efficiency of trial sheet
        // Re-calc Area to be precise
        const trialPacker = trialRes.packer;
        // Note: packSingleSheet auto-calculates best strategy.
        // We need to convert usedArea from packer to Percentage to compare.
        // Or simply compare Total Used Area (px^2) if sheet size is constant.
        // However, sheet width might be Auto-Calc.
        // Let's create the ResultSheet object to get the real standardized Efficiency.
        const trialSheetResult = createSheetResult(trialRes.packer, activeStock, settings, targetSheetIndex, " (Opt)");

        // Compare
        if (trialSheetResult.usedArea > (currentEfficiency + 0.1)) {
            // SUCCESS: Improvement found!

            // 1. Commit this sheet
            const newSheets = [...fixedSheets, trialSheetResult];

            // 2. Repack the remaining items (The Tail) using Greedy (Fast)
            // We don't optimize the tail yet, just validly pack it so we have a full valid state.
            let tailPool = trialRes.remainingItems;
            // Sort tail by size for decent packing
            tailPool.sort((a, b) => Math.max(b.width, b.height) - Math.max(a.width, a.height));

            let tempIdx = targetSheetIndex + 1;
            while(tailPool.length > 0) {
                const res = packSingleSheet(tailPool, activeStock, settings);
                if (res.packedItems.length === 0) { tailPool.shift(); continue; } // discard giant items if any
                newSheets.push(createSheetResult(res.packer, activeStock, settings, tempIdx));
                tailPool = res.remainingItems;
                tempIdx++;
            }

            // Update Global State
            currentSheets = newSheets;

            // Reset patience and move to next sheet
            patience = 0;
            targetSheetIndex++;

            // Yield Result
            yield currentSheets;

        } else {
            // FAILURE: No improvement
            patience++;
            if (patience > MAX_PATIENCE) {
                // Move on to try optimizing the next sheet
                patience = 0;
                targetSheetIndex++;
            }
        }

        // Yield occasionally even if no improvement to keep UI responsive? 
        // No, `yield` pauses execution. If we yield too often without changes, it might flicker or slow down reacting to "Stop".
        // But we need to yield to check for cancellation effectively in the consuming loop (App.tsx).
        // Actually, the consuming loop in App.tsx runs `next()`. If we don't yield, the UI freezes.
        // We MUST yield periodically.
        if (patience % 10 === 0) {
            await new Promise(resolve => setTimeout(resolve, 0)); // Unblock event loop
        }
    }
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { AppMode, NestLayout, Part, Tool, PlacedTool, ManualPunchMode, Point, NibbleSettings, DestructSettings, PlacementReference, SnapMode, ScheduledPart, TurretLayout, AutoPunchSettings, PlacementSide, TeachCycle, ToastMessage, ParametricScript, MachineSettings, OptimizerSettings, PunchOp } from './types';
